  val MOD = 1000000007
  val out = new PrintWriter(System.out)

  def solve(): Unit = {
    val N = ni()
    val A = Array.ofDim[Int](N, N)
    REP(N) { i =>
      REP(N) { j =>
        A(i)(j) = ni()
      }
    }

    val dp = Array.ofDim[Long](1 << N)
    dp(0) = 1

    REP(N) { i =>
      next_comb_bit(N, i) { set =>
        REP(N) { j =>
          if (A(i)(j) == 1 && (set & (1 << j)) == 0) {
            val next = set | (1 << j)
            dp(next) = (dp(next) + dp(set)) % MOD
          }
        }
//        debug(dp)
      }
    }

    out.println(dp((1 << N) - 1))
  }

  /**
    * nCk を全羅列する方法
    */
  def next_comb_bit(n: Int, k: Int)(f: Int => Unit) {
    if (k == 0) f(0)
    else {
      var flag = (1 << k) - 1
      while (flag < (1 << n)) {
        f(flag)
        val x = flag & -flag // 一番右の1
        val y = flag + x // 連続した1を0に、１個上のビットを1にする
        val z = flag & ~y // 連続した1部分
        flag = (z / x >> 1) | y // 連続した1を一つ減らして一番右に移動 + y
      }
    }
  }

