  }

  class InputReader(val stream: InputStream) {
    private val reader = new BufferedReader(new InputStreamReader(stream), 32768)
    private var tokenizer: StringTokenizer = _

    def next(): String = {
      while (tokenizer == null || !tokenizer.hasMoreTokens)
        tokenizer = new StringTokenizer(reader.readLine)
      tokenizer.nextToken
    }

    def nextInt(): Int = next().toInt
    def nextLong(): Long = next().toLong
    def nextChar(): Char = next().charAt(0)
  }
  val sc = new InputReader(System.in)
  def ni(): Int = sc.nextInt()
  def nl(): Long = sc.nextLong()
  def nc(): Char = sc.nextChar()
  def ns(): String = sc.next()
  def ns(n: Int): Array[Char] = ns().toCharArray
  def na(n: Int, offset: Int = 0): Array[Int] = map(n)(_ => ni() + offset)
  def na2(n: Int, offset: Int = 0): (Array[Int], Array[Int]) = {
    val A1, A2 = Array.ofDim[Int](n)
    REP(n) { i =>
      A1(i) = ni() + offset
      A2(i) = ni() + offset
    }
    (A1, A2)
  }
  def nm(n: Int, m: Int): Array[Array[Int]] = {
    val A = Array.ofDim[Int](n, m)
    REP(n) { i =>
      REP(m) { j =>
        A(i)(j) = ni()
      }
    }
    A
  }
  def nal(n: Int): Array[Long] = map(n)(_ => nl())
  def nm_c(n: Int, m: Int): Array[Array[Char]] = map(n) (_ => ns(m))
  def REP(n: Int, offset: Int = 0)(f: Int => Unit): Unit = {
    var i = offset
    val N = n + offset
    while(i < N) { f(i); i += 1 }
  }
  def REP_r(n: Int, offset: Int = 0)(f: Int => Unit): Unit = {
    var i = n - 1 + offset
    while(i >= offset) { f(i); i -= 1 }
  }

  def map[@specialized A: ClassTag](n: Int, offset: Int = 0)(f: Int => A): Array[A] = {
    val res = Array.ofDim[A](n)
    REP(n)(i => res(i) = f(i + offset))
    res
  }


  def sumL(as: Array[Int]): Long = {
    var s = 0L
    REP(as.length)(i => s += as(i))
    s
  }

  def cumSum(as: Array[Int]) = {
    val cum = Array.ofDim[Long](as.length + 1)
    REP(as.length) { i =>
      cum(i + 1) = cum(i) + as(i)
    }
    cum
  }
}

object Main extends App {

  import scala.io.StdIn._

  val n = readLine.trim.toInt
  val prefer = Array.tabulate(n){_ ⇒ readLine.trim.split(' ').map(_ == "1")}
  println(search(prefer))
  def search(prefer: Array[Array[Boolean]]): Long = {
    val memo = Array.tabulate(1 << prefer.length){_ ⇒ -1l}
    val mod = 1000000007L
    def solve(current: Int, used: Flag): Long = {
      if (current < 0) 1L
      else if (memo(used.index) >= 0) memo(used.index)
      else{
        prefer.indices.filter(p ⇒ !used(p) && prefer(current)(p)).map(p ⇒ solve(current - 1, used.updated(p, true))).sum.let{_ % mod}.also{max ⇒ memo(used.index) = max}
      }
    }
    solve(prefer.length - 1, new Flag)
  }
  class Flag(var index: Int = 0){
    def update(position: Int, value: Boolean): Unit = if (value) index |= 1 << position else index &= ~(1 << position)
    def apply(position: Int): Boolean = (index & (1 << position)) != 0
    def updated(position: Int, value: Boolean): Flag = if (value) new Flag(index | (1 << position)) else new Flag(index & ~(1 << position))
  }
  implicit class Extend[T](value: T){
    def also(func: T ⇒ Unit): T = {func(value); value}
    def let[A](func: T ⇒ A): A = func(value)
  }
}

