const int MOD = 1000000007;
const int INF = 1LL << 30;
const double EPS = 1e-10;

int N;
int a[21][21];
int used[21][1LL<<21];
int memo[21][1LL<<21];

int dfs(int v, int ms) {
  if (v == N) return 1;
  if (used[v][ms]) return memo[v][ms];
  used[v][ms] = 1;
  int res = 0;
  REP(i, N) if (a[v][i] && (ms & (1LL << i))) {
    (res += dfs(v+1, ms - (1LL << i))) %= MOD;
  }
  return memo[v][ms] = res;
}

