inline ll modexp(ll x, ll ex , ll md) {
    ll ans = 1ll;
    while (ex > 0) {
        if (ex & 1ll) ans = (ans * x) % md;
        ex >>= 1ll;
        x = (x * x) % md;
    }
    return ans;
}

const int inf = 1e9 + 7;
const ll mod = 1e9 + 7;

void solve(){
  int n;
  cin >> n;
  vector<vector<int>> cost (n + 1 , vector<int> (n + 1 , 0));
  for (int i = 1; i <= n; i++){
    for (int j = 1; j <= n; j++){
      cin >> cost[i][j];
    }
  }
  vector<vector<ll>> dp (n + 1 , vector<ll> (1 << n , 0));
  dp[0][0] = 1;
  for (int i = 0; i <= n; i++){
    for (int mask = 0; mask < (1 << n); ++mask){
      if (__builtin_popcount (mask) != i) continue;
      if (i + 1 > n) continue;
      for (int j = 1; j <= n; j++){
        if (mask & (1 << (j - 1))) continue;
        if (cost[i + 1][j] == 0) continue;
        dp[i + 1][mask | (1 << (j - 1))] += dp[i][mask];
        dp[i + 1][mask | (1 << (j - 1))] %= mod;
      }
    }
  }
  cout << dp[n][(1 << n) - 1] << endl;
}
