long long int mod = 1e9+7;
int bit;
vector<vector<int>> memo;

int helper(vector<vector<int>>& arr,int index,int mask){
    if(mask == (1<<bit)-1) return 1;
    if(index == arr.size()) return 0;
    if(memo[index][mask]!=-1) return memo[index][mask];
    int include = 0;
    include = helper(arr,index+1,mask);
    for(int i = 0; i < bit;i++){
        if((mask&(1<<i))==0 and arr[index][i]==1){
            include += helper(arr,index+1,mask|(1<<i)); 
            include %= mod;
        }
    }
    memo[index][mask] = include;
    return include;
}


