struct dpstruct
{
    vector<vector<int>> states;
    int mod;
    int n;
    vector<vector<bool>> comp;

    int dp(int i, int j)
    {
        if (i == 0 && j == 0) return 1;
        if (i == 0) return 0;
        if (states[i][j] != -1) return states[i][j];

        long long l = 0;
        for (int k = 0; k < n; k++)
        {
            if (!get(j, k)) continue;
            if (!comp[i - 1][k]) continue;
            l += dp(i - 1, unset(j, k));
        }
        return states[i][j] = l % mod;
    }
};

