int const MOD = (1e9) + 7;
int memo[22][1<<22];
int findans(int pos, int bitmask){
  if(pos == N)
    return 1;
  int &ans= memo[pos][bitmask];
  if(ans!=-1)
    return ans%MOD;
  ans = 0;
  for(int i=0;i<N;i++){
    if(arr[pos][i] == 1 && ((bitmask&(1<<i)) == 0)){
      ans = (ans%MOD + findans(pos+1, bitmask|(1<<i))%MOD)%MOD;
    }
  }
  return ans%=MOD;
}
