ll n;

ll calc(vvi &v,ll i,ll subset,vvi &dp)
{
    if(i==n)
    {
        if(subset==0)
            return 1;
        else
            return 0;
    }

    if(dp[i][subset]!=-1)
        return dp[i][subset];

    ll ans=0;
    for(ll m=0;m<n;m++)
    {
        bool f = ( (1<<m)&(subset) )?1:0;
        if( f && v[i][m]==1)
        {
            ans = (ans + calc(v,i+1,subset^(1<<m),dp))%MOD;
        }
    }

    return dp[i][subset]=ans;

}

