vector<vector<int>> m; int n;
ll solve(int x, int wmask) {

	if(dp[x][wmask] >= 0) return dp[x][wmask];

	if(x == n - 1) { // last man in world
		for(int i = 0; i < n; i++) {
			if(m[x][i] && ((wmask >> i) & 1)) {dp[x][wmask] = 1; return 1;}
