        for ( int b = 0; b < B; b++ ) {
            for ( int j = 0; j < N; j++ ) {
                if ( ((~b) & A[i-1]) & (1 << j) ) {
                    int nb = b | (1<<j);
                    dp[i][nb] += dp[i-1][b];
                }
            }
        }
    }
    return dp[N][B-1].value;
}

int main() {
    auto ans = solve();
    cout << ans << "\n";
    return 0;
}

