const int N=22;

ll n;
vector<vector<ll> > compat(N,vector<ll>(N));
ll dp[N][(1<<N)];

ll solve(ll i,ll wom_sub){
	if(i==n+1){
		if(wom_sub==0)
		return 1;
	    return 0;
	}

	if(dp[i][wom_sub]!=-1)
	return dp[i][wom_sub];

	ll ans=0;

	for(ll wom=0;wom<n;wom++){
		bool avail = (((1<<wom)&(wom_sub))==0)?0:1;
		if(avail && compat[i][wom+1]){
			ans=(ans+solve(i+1,wom_sub ^ (1<<wom)))%mod;
		}
	}
