int compat[22][22] = {};
int mod = 1e9 + 7;
int top(int i, int wstatus, int n)
{
	//base case
	if (i == n)
	{
		if (wstatus == 0) // no women is available, all used therefore success
			return 1;
		return 0;//unsuccessful pairing
	}
	if (memo[i][wstatus] != -1)
		return memo[i][wstatus];
	int ans = 0;
	for (int j = 0; j < n; j++)
	{
		if (compat[i][j] && (wstatus & (1 << j))) //woman compatible as well as available
		{
			ans += top(i + 1, (wstatus ^ (1 << j)), n);// xoring making this woman unavailable for next man
			ans = ans % mod;
		}
	}
	return memo[i][wstatus] = ans;
}
