/*
看到这个数据范围 n <= 21，就感觉是状压 dp
怎么设计状态呢
因为答案与顺序无关，所以 f[i] 为前 i 个男生匹配完了的方案数。
好像没法记录女生选的情况，所以在加一维 f[i][mask] 为前 i 个男生匹配完，女生状态为 mask 的方案数
第 i 个男生可以枚举一个女生转移
好像 i 这一维不需要啊
好像枚举 i 这一步也不需要啊
mask 中 1 的个数是 i 啦
n <= 21，如果枚举 i 这一维的话，大概是 2^21 * 21 * 21  = 924844032 TLE
如果不枚举 i 的话 2^n * n AC 啦 
要用到什么呢？
判断某一位是不是 1：用 & 
去掉某一位的 1：用 ^ 
求有多少个 1：这一步可以用一个函数啊，开头是双下划线，好像 noip 不让用：__builtin_popcount
额这个函数怎么记住？划分一下是：built in pop count 好记多了呀 
哦，初始状态 f[0] = 0;  答案是 f[(1 << n) - 1] 
*/
#include <bits/stdc++.h>
using namespace std;
const int N = 21 + 5;
int n, a[N][N], f[1 << N], p = 1e9 + 7; 
int main() {
	int n; scanf("%d", &n);
	for (int i = 1; i <= n; i++)
		for (int j = 1; j <= n; j++)
			scanf("%d", &a[i][j]);
	f[0] = 1;
	for (int mask = 0; mask < (1 << n); mask++) {
		int i = __builtin_popcount(mask);
		for (int j = 1; j <= n; j++) {
			if (mask & (1 << (j - 1)) && a[i][j])
				f[mask] = (f[mask] + f[mask ^ (1 << (j - 1))]) % p;
		}
	}
	printf("%d\n", f[(1 << n) - 1]);
	return 0;
}

