int rec(int indx, int mask){

	if(mask==(1<<N)-1) return 1;
	if(indx>=N) return 0;
	if(dp[indx][mask]!=-1) return dp[indx][mask];
	int ret=0;
	for(int i=0;i<N;i++){
		if(A[indx][i]==1 && !((1<<i)&mask)){
			ret+=rec(indx+1,(mask|(1<<i)));
			ret=(ret%MOD);
		}
	}
	return dp[indx][mask]=ret;
}

