using ll = long long;

#define off(b, th) (b & ~(1 << th))

void solve() {
  int n;
  cin >> n;
  vector<vector<int>> a(n, vector<int>(n));
  REP(i, n) REP(j, n) cin >> a[i][j];

  const ll MOD = 1e9 + 7;

  vector<vector<ll>> dp(n, vector<ll>(1 << n, -1));

  function<ll(int,int)> bt = [&](int i, int state) -> ll {
    if (i == n){
      return 1ll;
    }
    ll &res = dp[i][state];
    if (res != -1) return res;
    res = 0;
    REP(j, n){
      if (a[i][j] && (state >> j & 1)){
        res = (res + bt(i + 1, off(state, j))) % MOD;
      }
    }
    return res;
  };

  int state = (1 << n) - 1;
  ll ans = bt(0, state);
  cout << ans << "\n";
}

int main() {
  ios::sync_with_stdio(0);
  cin.tie(0);

  int T = 1;
  // cin >> T;
  while (T--) {
    solve();
  }
}

