  {
    for (int k = 0; k < mask; k++)
    {
      if (__builtin_popcount(k) != N - i)
        continue;
      for (int j = 0; j < N; j++)
      {
        if (A[i] & k & (1 << j))
          add(dp[i + 1][k - (1 << j)], dp[i][k]);
      }
    }
  }
  cout << dp[N][0] << endl;

  return 0;
}

