ModInt mem[22][2097152 + 5];

//j_[k] = false iff the kth woman is free
// considering the ith man, picking from remaining women encoded by j
ModInt solve(int i, int j_) {
  if (i == n) return 1; //made it to the end
  if (!is_set[i][j_]) {
    mem[i][j_] = 0;
    for (int k = 0; k < n; k++) {
      if (!(j_ & (1 << k)) && compat[i][k]) {
        //try this woman
        mem[i][j_] += solve(i+1, j_ | (1 << k));
      }
    }
    is_set[i][j_] = true;
  }
  return mem[i][j_]; 
}

