int f(int i, int j)
{
	if (i==0)
		return a[0][31-__builtin_clz(j)];
	if (dp[i][j]!=-1)
		return dp[i][j];
	int ans=0;
	for (int k=j; k; k^=(k&-k))
		if (a[i][31-__builtin_clz(k&-k)])
		{
			ans+=f(i-1,j^(k&-k));
			if (ans>=MOD)
				ans-=MOD;
		}
	return dp[i][j]=ans;	
}

