void compute(int p,int r,int n,long long int& c, vector<int> col,vector<vector<int>> mat,vector<vector<int>> dp)
{
    if(r==n)
    {
        c++;
        return;
    }

    for(int j=0;j<n;j++)
    {
        if(col[j]==1)
            continue;
        if(mat[r][j]==1 && col[j]==0)
        {
            col[j]=1;
            compute(j,r+1,n,c,col,mat,dp);
            col[j]=0;
        }
    }
    return;
}
int main()
{
    int n;
    cin>>n;
    vector<vector<int>> mat(n,vector<int>(n,0));
    vector<vector<int>> dp(n,vector<int>(n,0));

    for(int i=0;i<n;i++)
    {
        for(int j=0;j<n;j++)
        {
             cin>>mat[i][j];
             dp[i][j]=0;
        }
    }

    long long int sum=0;
    vector<int> col(n,0);
    for(int p=0;p<n;p++)
    {
        long long int c=0;
        if(mat[0][p]==1)
        {
            col[p]=1;
            compute(p,1,n,c,col,mat,dp);
            sum=(sum%1000000007+c%1000000007)%1000000007;
            col[p]=0;
        }
    }
    cout<<sum;
    return 0;
}

