using int64 = long long;

constexpr int64 P = 1000000007;

// Verified: ABC133E, ABC132D, ABC130E
struct FiniteField {
 private:
  int64 x;
 public:
  FiniteField(int64 input_x) : x(input_x) {}
  FiniteField() : x(0) {}
  int64 Value() { return x; }
  inline FiniteField operator+(FiniteField o) {
    FiniteField r(*this); r += o; return r;
  }
  inline FiniteField operator-(FiniteField o) {
    FiniteField r(*this); r -= o; return r;
  }
  inline FiniteField operator* (FiniteField o) {
    FiniteField r(*this); r *= o; return r;
  }
  inline FiniteField operator/ (FiniteField o) {
    FiniteField r(*this); r /= o; return r;
  }
  inline void operator+= (FiniteField o) { x = (x + o.x) % P; }
  inline void operator-= (FiniteField o) { x = (x + P - o.x) % P; }
  inline void operator*= (FiniteField o) { x = (x * o.x) % P; }
  void operator/=(FiniteField o) {
    int64 p = P - 2; while (p) { if (p % 2) { *this *= o; } o *= o; p /= 2; }
  }
};

template<typename T>
vector<vector<T>> Make2DVector(int d1, int d2, T default_value) {
  return vector<vector<T>>(d1, vector<T>(d2, default_value));
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n;
  cin >> n;
  vector<vector<int>> mat = Make2DVector(n, n, 0);
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      cin >> mat[i][j];
    }
  }

  vector<vector<FiniteField>> dp = Make2DVector(n + 1, 1 << n, FiniteField(0));
  vector<vector<int>> dp_solved = Make2DVector(n + 1, 1 << n, 0);

  function<FiniteField(int, int)> solve = [&](int k, int set) -> FiniteField {
    if (dp_solved[k][set]) return dp[k][set];

    if (k == n) return 1;

    FiniteField value = 0;
    for (int i = 0; i < n; i++) {
      if ((set & (1 << i)) == 0) continue;
      if (mat[k][i] == 0) continue;
      value += solve(k + 1, set - (1 << i));
    }
    dp_solved[k][set] = 1;
    dp[k][set] = value;
    return value;
  };
  cout << solve(0, (1 << n) - 1).Value() << endl;
}

