int main()
{
	cin >> N;
	for(int i = 0; i < N; i++){
		for(int j = 0; j < N; j++){
			cin >> a[i][j];
		}
	}

	for(int i = 0; i < 1 << N; i++){
		for(int j = 0; j < N; j++){
			DP[i][j] = -1;
		}
	}

	cout << calc() << endl;

