int rec(int S, int V, int n){
	if(DP[S][V] >= 0){
		return DP[S][V];
	}

	if(!a[n][V]){
		DP[S][V] = 0;
		return 0;
	}
	else if(n == N-1){
		DP[S][V] = 1;
		return DP[S][V];
	}

	int sum = 0;
	int nextS = S | (1 << V);
	for(int i = 0; i < N; i++){
		if(i != V && !(S >> i & 1)){
			// なるべく関数呼び出しを少なくすると少し速くなる...
			sum += DP[nextS][i] >= 0 ? DP[nextS][i] : rec(nextS, i, n+1);
			sum %= mod;
		}
	}

	DP[S][V] = sum;
	return DP[S][V];
}

int calc(){
	int sum = 0;
	for(int i = 0; i < N; i++){
		sum += rec(0, i, 0);
		sum %= mod;
	}
	return sum;
}

