int dpfunc(int val) {
	if (__builtin_popcountll(val) == n)
		return 1;
	else if (dp[val] != -1)
		return dp[val];

	int ans = 0, index = __builtin_popcountll(val);
	for (int i = 0; i < n; i++) {
		if ((val & (1<<i)) == 0 and arr[index][i] == 1)
			ans = (ans + dpfunc(val + (1<<i)))%mod; 
