int solve(vector<vector <int> > &comp, int i , int womenSubs , int n )
{
    if(i == n+1)
	{	if(womenSubs == 0)
			return 1;
		else
			return 0;
	}
	if(dp[i][womenSubs] != -1)
		return dp[i][womenSubs];
