int binpow(int a, int b){
	int res = 1;
	while(b){
		if(b % 2)
			res = res * a;
		a *= a;
		b >>= 1;
	}
	return res;
}

ll dp(vector<vector<int>> &v, int mmask, int i){
	if(i == v.size())
		return 1;
	if(memo[mmask] != -1)
		return memo[mmask];
	memo[mmask] = 0;
	for(int e : v[i]){
		if(mmask & binpow(2, e)){
			memo[mmask] = (memo[mmask] + dp(v, mmask & (binpow(2, 21)-1-binpow(2, e)), i+1)) % MOD;
		}
	}
	return memo[mmask];
}

