const long long MOD = 1000000007LL;
const int MSTATE = 1 << 21;
int n, adj[21];
long long dp[MSTATE];

long long helper(int pos, int state){

    if(pos == n)
        return 1;

    if(dp[state] != -1)
        return dp[state];

    long long tot = 0;

    int possible = (state ^ adj[pos]) & adj[pos];
    for(;possible; possible &= possible - 1)
        tot = (tot + helper(pos + 1, state | (possible & -possible))) % MOD;

    dp[state] = tot;

    return tot;

}

