ll ways(vector<vector<ll>>&v,string state,ll i){
	if(i==v.size())
		return 1;
	string newstate="";

	for(ll j=0;j<state.length();j++){
		if(v[i][j]){
			newstate.push_back(state[j]);
		}	
		else{
			newstate.push_back('0');
		}
	}

	if(dp.find(newstate)==dp.end()){
		ll ans=0;
		for(ll j=0;j<newstate.length();j++){
			if(newstate[j]=='1'){
				state[j]='0';
				ans=(ans+ways(v,state,i+1))%M;
				state[j]='1';			
			}
		}	
		dp[newstate]= ans;
	}
	return dp[newstate];
}

