template <size_t W>
bool next_combination(size_t n, size_t k, std::bitset<W> &S) {
  if ((S >> (n-k)).count() == k) { return false; }
  auto const s = S.to_ullong(), x = s & -s, y = s + x;
  S = std::bitset<W>((((s & ~y) / x) >> 1) | y);
  return true;
}

