int func(int ind, int women){
  if(ind == n and women == (1<<n) - 1)
    return 1;
  else if(ind == n)
    return 0;
  if(dp[ind][women] != -1)
    return dp[ind][women];
  dp[ind][women] = 0;
  for(int i = 0; i < n; i++){
    if(a[ind][i] == 1 and (women&(1<<i)) == 0){
      dp[ind][women] += func(ind + 1, (women | (1<<i)));
      dp[ind][women] %= mod;
    }
  }
  return dp[ind][women];
}


