ll dp[25][1<<23];
ll bitCount[1<<23];
ll a[25];
void fix(ll &v) {
	if( v >= mod)
		v-= mod;
	if(v < 0)
		v+=mod;
}
int unsetBit(int v, int j) {
	return (v & (~(1<<j)));
}
int main() {
	int n;
	cin>>n;
	for(int i=0;i<n;i++) {
		for(int j=0;j<n;j++) {
			int bit;
			cin>>bit;
			if(bit) 
				a[i] = a[i] | (1<<j);
		}
	}
	dp[0][0] = 1;
	bitCount[1] = 1;
	vector<ll> bucket[n+1];
	bucket[1].push_back(1);
	for (int i = 2; i < (1<<n); ++i) {
		bitCount[i] = bitCount[i/2] + (i&1);
		bucket[bitCount[i]].push_back(i);
	}
	for(int i=1; i <= n; i++) {
		for(int j=0; j< (int)bucket[i].size(); j++) {
			int mask = bucket[i][j];
			for(int k=0; k < n; k++) {
				if(a[i-1] & (1<<k) && (mask & (1<<k)) ) {
					dp[i][mask] += dp[i-1][unsetBit(mask,k)];
					fix(dp[i][mask]);
				}
			}
		}
	}
	int mask = 1<<n;
	mask--;
	if(dp[n][mask] < 0) dp[n][mask] += mod;
	cout<<dp[n][mask]<<endl;
	return 0;
}

