    if(id == n) return 0;

    int &z = dp[mask][id];
    if(~z) return z;

    z = 0;
    int temp = 0;
    for(int i=0; i<n; i++){
        if(a[i][id] && !(mask&(1<<i))){
            add_self(z, recurse(mask|(1<<i), id+1));
        }
    }
    return z;
}

