    vector<vector<int>> a(n, vector<int>(n));
    // dp[i][j] : 男i人目まででの人数 j は使った女の集合
    vector<vector<mint<MOD>>> dp(n+1, vector<mint<MOD>>(1<<n,0));
    dp[0][0] = 1;
    REP(i, n) REP(j,n) cin >> a[i][j];
    REP(i, n) {
        REP(j, 1<<n) {
            if (bitpopcount(j) == i) {
                REP(k, n) {
                    if (((j & (1 << k)) == 0) && a[i][k]) {
                        dp[i + 1][j | (1 << k)] += dp[i][j];
                    }
                }
            }
        }
    }
    cout << dp[n][(1 << n) - 1] << endl;
    return 0;
}

