long long int p=1e9 +7;
int n;

bool compatibility[21][21];
ll dp[21][1ll << 21];               //dp[i][j] represents i people left and
                                    //j is the bitmask for women left

ll solve(int N,int left){
    ll curr=0;                       //initialise with 0

    if(dp[N-1][left]!=-1){             //check if we have already found the dpwer
        return dp[N-1][left];
    }

    if(N==1) {
        for(int j=0;j<n;j++){
            int x=1<<j;                         // bit fo jth woman
            if(left & x){                       //check if the jth women is left
                if(compatibility[N-1][j]){ 
                    dp[N-1][left]=1;
                    return 1;                   //If they are compatible return 1, as only 1 of the n women will be available
                }
                else{
                    dp[N-1][left]=0;
                    return 0;                   //If the last 2 aren't compatible return 0
                }
            }
        }
    }

    for(int i=0;i<n;i++) {

        if(left & (1ll<<i)){                            //If the ith women is left - available for pairing 

            if(compatibility[N-1][i])   {               //If the 2 are compatible
                curr += solve(N-1, left - (1ll << i));  // now the ith women is unavailble so unset the bit in left  
            }
        }
    }

    curr%=p;
    dp[N-1][left] = curr;

    return dp[N-1][left];
}


