  for(int i=0; i<N; i++){
    for(int j=0; j<N; j++){
      cin >> buf;
      if(buf==1){
        data.at(i).set(j);
      }
    }
  }

  vector<mint> dp(1<<N);
  Memo memo;
  solve(data, 0, &dp, &memo);

  mint ans= dp.at(0);

  cout << ans << endl;
}

