i64 n, a[22][22], dp[22][1 << 21];

i64 dfs(i64 i, i64 s) {
  if (i >= n) return 1;
  if (dp[i][s] >= 0) return dp[i][s];
  i64 y = 0;
  for (i64 j = 0; j < n; ++j) {
    i64 bit = i64(1) << j;
    if (!(s & bit) && a[i][j]) y += dfs(i + 1, s | bit);
  }
  return dp[i][s] = y % mod;
}

