#include <iostream>
using namespace std;

#define MD 1000000007

int dp[2097157], P[25];
int N, A[25][25];
int U[25], n, h;

int solve()
{
    int c = N - n;
    int res = 0;
    n--;
    for (int i = 0; i <= n; i++) if (A[c][U[i]])
    {
        h -= P[U[i]];
        if (dp[h] != -1) res = (res + dp[h]) % MD;
        else
        {
            if (i < n)
            {
                int tmp = U[i];
                U[i] = U[n];
                res = (res + solve()) % MD;
                U[i] = tmp;
            }
            else res = (res + solve()) % MD;
        }
        h += P[U[i]];
    }
    n++;
    dp[h] = res;
    return(res);
}

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cin >> N;
    for (int i = 0; i < N; i++) P[i] = 1 << i;
    for (int i = 0; i < N; i++) for (int j = 0; j < N; j++) cin >> A[i][j];
    for (int i = 0; i < N; i++) U[i] = i;
    n = N;
    h = (1 << N) - 1;
    int lim = 1 << N;
    dp[0] = 1;
    for (int i = 1; i < lim; i++) dp[i] = -1;
    cout << solve() << '\n';
    return(0);
}

