int memo[23][(1 << 21) + 1] = {};

int dp(int man, int rem_wmn)
{
    if (!rem_wmn)
        return 1;
    if (memo[man][rem_wmn])
        return memo[man][rem_wmn] - 1;
    int num = 0;
    for (int i = 0; i < n; i++)
    {
        if (!arr[man][n - 1 - i])
            continue;
        num = (num + (dp(man + 1, rem_wmn ^ (1 << i)))) % M;
    }
    memo[man][rem_wmn] = num + 1;
    return num;    
}

