ll dfs(ll bit){
    ll i = __builtin_popcount(bit);
    if(dp[i][bit]!=-1)return dp[i][bit];

    if(i==n-1){
        bool abc=0;
        for(int j=0;j<n;j++){
            if(bit&(1<<j))continue;
            if(a[i][j]==0)continue;
            abc=1;
            break;
        }
        if(abc==1)return dp[i][bit]=1;
        else return dp[i][bit]=0;
    }

    ll res=0;
    for(int j=0;j<n;j++){
        if(bit&(1<<j))continue;
        if(a[i][j]==0)continue;
        bit|=(1<<j);
        res+=dfs(bit);
        res%=MOD;
        bit&=~(1<<j);
    }
    dp[i][bit]=res;
    return res;
}
