ll sol(ll i,ll bitval,ll n,vector<vector<ll> > &v,vector<vector<ll> > &dp)
{
    if(i==n)
    {
        return 1;
    }
    if(dp[i][bitval]!=-1)
    {
        return dp[i][bitval];
    }
    ll ans = 0;
    for(ll j=0;j<n;j++)
    {
        if(v[i][j])
        {
            ll x = (1<<j)&(bitval);
            if(!x)
            {
                ll nbit = (1<<j)|(bitval);
                ans = (ans+sol(i+1,nbit,n,v,dp))%M;
            }
        }
    }
    return dp[i][bitval] = ans;
}


