int compute(bitset<21> bt,int id){ 
	int val=0; 
	for(int i=0;i<21;i++){ 
		if(bt.test(i)){ 
			val+=1<<i; 
		} 
	} 
	if(dp[val][id]!=-1){ 
		return dp[val][id]; 
	} 

	if(id==n-1){ 
		for(int i=0;i<n;i++){ 
			if(!bt.test(i) and a[i][id]==1){
				return dp[val][id]=1;
			} 
		}
		return dp[val][id]=0; 
	} 
	int s=0;
	for(int i=0;i<n;i++){ 
		if(!bt.test(i) and a[i][id]==1){ 
			bt.set(i);
			s=add(s,compute(bt,id+1));
			bt.reset(i); 
		}
	}
	return dp[val][id]=s; 
}



