const long long modulo = 1000000007;

struct Solver
{
    int N;
    vector< vector<int> > a;
    vector<long long> ways;

    void addSelf(long long& x, long long y) {
        x += y;

        if (x >= modulo) {
            x -= modulo;
        }
    }

    long long solve(int _N, vector< vector<int> >& _a) {
        N = _N;
        a = _a;

        ways.resize(two(N));
        ways[0] = 1;

        for (int mask = 0; mask < two(N) - 1; ++mask) {
            int i = __builtin_popcount(mask);

            for (int j = 0; j < N; ++j) {
                if (a[i][j] && !(mask & two(j))) {
                    addSelf(ways[mask | two(j)], ways[mask]);
                }
            }
        }

        return ways[two(N) - 1];
    }
};

