        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < N; ++j) {
                a[i][j] = readInt();
            }
        }

        Solver solver;
        long long ways = solver.solve(N, a);
        cout << ways << endl;
    }

    return 0;
}

