int solve()
{
    if (dp[h] != -1) return(dp[h]);
    int c = N - n;
    if (c == N)
    {
        dp[h] = 1;
        return(1);
    }
    int res = 0;
    n--;
    for (int i = 0; i <= n; i++) if (A[c][U[i]])
    {
        h -= P[U[i]];
        if (i < n)
        {
            int tmp = U[i];
            U[i] = U[n];
            res = (res + solve()) % MD;
            U[i] = tmp;
        }
        else res = (res + solve()) % MD;
        h += P[U[i]];
    }
    n++;
    dp[h] = res;
    return(res);
}

