                }
                if (a[i][j]) {
                    int new_mask = mask | (1 << j);
                    dp[new_mask] = (dp[new_mask] + dp[mask]);
                    dp[new_mask] -= (dp[new_mask] >= MOD) * MOD;
                }
            }
