int dpf(int crr,int last,int parent){
	// printf("%d %d \n",crr,last );
	if(dp[crr][last]!=-1){
		return dp[crr][last];
	}
	dp[crr][last]=0;
	ll a=1;
	if(last==0){
		ll b=1;
		for(int i=0;i<v[crr].size();i++){
			if(v[crr][i]!=parent){
				a*=dpf(v[crr][i],0,crr);
				a%=mod;
				b*=dpf(v[crr][i],1,crr);
				b%=mod;
			}
		}
		dp[crr][last]=a+b;
		dp[crr][last]%=mod;
	}
	else{
		for(int i=0;i<v[crr].size();i++){
			if(v[crr][i]!=parent){	
				a*=dpf(v[crr][i],0,crr);
				a%=mod;
			}
		}
		dp[crr][last]=a;
	}
	if(dp[crr][last]==0){
		if(last==0)
			dp[crr][last]=2;
		else
			dp[crr][last]=1;
	}
	return dp[crr][last];
}
