LL POW(LL x,LL y)
{
    LL ans=1;
    LL base=x;
    while(y)
    {
        if(y&1)
        {
            ans*=base;
        }
        base=base*base;
        y=y>>1;
    }
    return ans;
}

LL cal(LL index,LL mask)
{
    if(dp[index][mask]==-1)
    {
        if(index!=1)
        {
            LL ways=0;
            LL one=(LL)1;
            LL currmask=mask;
            for(LL i=1;i<=n;i++)
            {
                LL check=(one<<(i-1));
                LL p=(check&currmask);
                if(arr[index][i]==1 && (p!=0))
                {
                    LL t=~check;
                    LL give=(t)&currmask;          
                    if(dp[index-1][give]==-1)
                    {
                        dp[index-1][give]=cal(index-1,give);
                    }
                    ways+=dp[index-1][give];
                    ways%=mod;
                }
            }

            dp[index][mask]=(ways)%mod;
        }
        else
        {
            LL ways=0;
            LL one=1;
            LL currmask=mask;
            for(LL i=1;i<=n;i++)
            {
                LL check=(one<<(i-1));
                LL p=check&currmask;
                if(arr[index][i]==1 && (p!=0))
                {
                    ways++;
                    ways%=mod;
                }
            }

            dp[index][mask]=(ways)%mod;
        }        
    }
    return dp[index][mask];
}

