void solve(ll N, std::vector<std::vector<ll>> a) {
  vector<ll> dp((1 << N) + 1, 0);
  dp.at(0) = 1;
  for (int S = 1; S < (1 << N); S++) {
    bitset<3> bs = S;
    int i = __builtin_popcount(S);
    rep(j, N) {
      if ((S >> j) & 1 == 1 && a.at(i - 1).at(j) == 1) {
        int v = S ^ (1 << j);
        dp.at(S) = (dp.at(S) + dp.at(S ^ (1 << j))) % MOD;
      }
    }
  }

  cout << dp.at((1 << N) - 1) << endl;
}

