int n;
int a[22][22];
int dp[22][(1 << 22)];
const int MOD = 1e9 + 7;

int recur(int i, int mask){
    if(i == n && mask == (1<<n) - 1) return 1;
    if(i == n) return 0;
    if(dp[i][mask] != -1) return dp[i][mask];
    else{
        int ans = 0;
        for(int j = 0; j < n; j++){
            if(a[i][j] == 1 && (mask & (1<<j)) == 0){
                int mask2 = (mask ^ (1<<j));
                ans += recur(i+1,mask2);
                ans %= MOD;
            }
        }
        dp[i][mask] = ans;
    }
}


