    cin>>n;
    for(int i = 0; i <n; i++){
        for(int j  = 0 ; j < n; j++){
            cin>>a[i][j];
        }
    }
    memset(dp,-1,sizeof dp);
    cout<<recur(0,0)%MOD;
}

