ll memo(ll female){
  if(dp[female]>=0) return dp[female];
  if(female==(1ll<<n)-1) return dp[female]=1;

  int male=0;
  for(int i=0;(1ll<<i)<=female;i++){
    if((1ll<<i)&female) male++;
  }
  ll res=0;
  for(int i=0;i<a[male].size();i++){
    int u=a[male][i];
    if((1ll<<u)&female) continue;

    res=(res+memo(female|(1ll<<u)))%MOD;
  }

  return dp[female]=res;
}

