inline ll binex(ll a,ll b)
{
    ll ans=1,temp=a%mod;
    while(b!=0){
        if(b&1) ans=(ans*temp)%mod;
        temp=(temp*temp)%mod;
        b=b>>1;
    }
    return ans;
}

inline ll solve(int n,int mask,int idx)
{
        //cerr<<idx<<" "<<mask<<endl;
    if(mask==(1<<n)-1) return 1;
    if(idx==-1) return 0;
    if(dp[mask][idx]!=-1) return dp[mask][idx];
    ll temp=0;
    rep(i,0,n){
        if(!mat[i][idx] || (mask&(1<<i))!=0) continue;
        else temp+=solve(n,mask|(1<<i),idx-1);
    }
    return dp[mask][idx]=temp%mod;
}

