    for (int mask = 0; mask < (1 << num_pairs) - 1; ++mask) {
        const auto m = num_set_bits(mask);
        for (int w = 0; w < num_pairs; ++w) {
            if (compatibility[m][w] && !(mask & (1 << w))) {
                int m2 = mask ^ (1 << w);
                mod_add(dp[m2], dp[mask]);
            }
        }
    }
    return dp.back();
}

