using namespace std;

#define MOD 1000000007

int N;
vector<vector<int>> a, memo;

long long solve(int i, int s) {
    // 男性 i 人（男性 0 〜 男性 i-1）が
    // 集合 s に含まれる女性とペアを作っている場合の
    // 残りの男女でペアを作る方法の数（memo[i][s]の値）を返す

    // i==N なら、全員ペアを作ったので、1通りを返す
    if (i == N) return 1;

    // すでに計算済みならメモの値を返す
    if (memo[i][s] != -1) return memo[i][s];

    long long ans = 0;

    // i < N なら、男性 i のペア相手を探す
    for (int j = 0; j < N; j++) {
        // 女性 j についてチェック
        if ((s & (1 << j)) != 0) {
            // 女性 j がすでにペアを組んでいるならパス
            continue;
        }
        if (a[i][j] == 1) {
            // 男性 i が女性 j とペアになれるなら
            // 二人をペアにして、残りのパターン数を足す
            ans += solve(i + 1, s ^ (1 << j));
            ans %= MOD;
        }
    }
    // メモに記録
    memo[i][s] = ans;
    return ans;
}

int main(void) {
    cin >> N;
    // N×N の配列を用意
    a = vector<vector<int>>(N, vector<int>(N));
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            cin >> a[i][j];
        }
    }

    // (N+1)×2^N のDP用配列を用意
    memo = vector<vector<int>>(N + 1, vector<int>(1 << N, -1));
    // memo[i][s]:
    //   男性 i 人（男性 0 〜 男性 i-1）が
    //   集合 s に含まれる女性とペアを作っている場合の
    //   残りの男女でペアを作る方法の数を返す

    // memo[0][0] の値が答え
    cout << solve(0, 0) << endl;

    return 0;
}

