map<ll, mint> dp[2];  // [a][b]  b=女性の成立状態
void solve()
{
    ll N;
    in(N);
    vvll A(N, vll(N));
    for1 (i, N) {
        vin(A[i], N);
    }
    ll i1 = 1;
    ll i2 = 0;
    dp[i2][0] = 1;
    const ll loopmax = 1u << N;
    for1 (i, N) {  // i=男性の番号
        i1 ^= 1;
        i2 ^= 1;
        dp[i2].clear();
        for1 (k, N) {
            if (A[i][k] == 0) {
                continue;
            }
            ll kb = 1u << k;
            for (auto pa : dp[i1]) {
                ll j = pa.first;  // j=女性の成立状態
                if ((j & kb) == 0) {
                    dp[i2][j | kb] += dp[i1][j];
                }
            }
        }
        dumpa(dp[i2], loopmax);
    }
    print(dp[i2][loopmax - 1]);
}

