long long DP(long long i,long long used)
{
    if (i==n) return 1;
    if (F[i][used]>-1) return F[i][used];

    long long &res=F[i][used];
    res=0;
    for (int j=0;j<=n-1;j++) {
        if (a[i][j]==0 || ((used>>j) & 1)) continue;
        res+=(DP(i+1,used | (1<<j)))%1000000007;
    }
    return res;
}

