long long m=1e9+7;
int n;
long long dp[3000000];
int compatible[25][25];
int is_compatible(int g, int b){
    if(compatible[g][b]==1)return 1;
    else return 0;
}
long long solve(long long b_mask){
   if(dp[b_mask]!=-1)return dp[b_mask];
   int g=0;
   for(int i=0;i<=n;i++)if(b_mask&(1<<(i)))g++;
   int boy;
     long long res=0;
   if(g==1){
       for(int i=0;i<n;i++){
           if (b_mask & (1 << (i))) {
               boy=i+1;break;
           }
       }
       if(is_compatible(g,boy))return dp[b_mask]=1;
       else return dp[b_mask]=0;
   }
   for(int i=0;i<n;i++){
       long long temp=b_mask;
       if((b_mask & (1 << (i)))&&is_compatible(g,i+1)){
           temp=temp ^ (1 << (i));
           res=(res+solve(temp));
           if(res>=m)res-=m;
       }
    }
   return dp[b_mask]=res;
}
