ll solve ( int pos, int mask ) {
	if ( pos == n ) {
		int taken = __builtin_popcount(mask);
		if ( taken == n ) return 1;
		return 0;
	}
	if ( dp[pos][mask] != -1 ) return dp[pos][mask];
