int p = 1000000007;
struct hash_pair { 
    template <class T1, class T2> 
    size_t operator()(const pair<T1, T2>& p) const
    { 
        auto hash1 = hash<T1>{}(p.first); 
        auto hash2 = hash<T2>{}(p.second); 
        return hash1 ^ hash2; 
    } 
};
unordered_map<pair<vector<bool>,int>,int,hash_pair>dp;
inline int helper(unordered_map<int,unordered_map<int,int> >&pairs,int i,vector<bool>&taken){
	if(dp.find(make_pair(taken,i)) != dp.end()){
		return dp[{taken,i}];
	}
	if(i == taken.size())
	return 1;
	int ans = 0;
	//cout<<pairs.size();
	for(auto it=pairs[i].begin();it != pairs[i].end();it++){
		if(it->second == 1 && !taken[it->first]){
			taken[it->first] = true;
			ans = (ans%p + helper(pairs,i+1,taken)%p)%p;
			taken[it->first] = false;
		}
	}
	dp[{taken,i}] = ans;
	//cout<<i<<" "<<ans<<endl;
	return ans;
}
