    for (int i = 0; i < N; i++) {
        for (auto itr = dp[i % 2].begin(); itr != dp[i % 2].end(); itr++) {
            int dist = distance(dp[i % 2].begin(), itr);
            if (*itr == 0) continue;
            for (int k = 0; k < N; k++) {
                if (a[i][k] == 0) continue;
                if ((dist>>k)&1) continue;
                int next = dist | (1<<k);
                dp[(i + 1) % 2][next] += *itr;
            }
        }
    }
    cout << dp[N % 2][(1<<N) - 1] << endl;
}

