		pos[i].push_back(j);
	}

	vector<vector<mint>> dp(N + 1, vector<mint>(1 << N));

	dp[0][0] = 1;
	FOR(i, 1, N + 1) {
		for (int j : pos[i - 1]) { //(i-1)からjを使用する
			REP(k, (1 << N)) if ((k & (1 << j))) {
				int src = (k & ~(1 << j));
				dp[i][k] += dp[i - 1][src];
			}
		}
	}

	cout << dp.back().back() << endl;
}

