int binary_to_decimal(int mask){
	int num = mask; 
    int dec_value = 0; 

    int base = 1; 

    int temp = num; 
    while (temp) { 
        int last_digit = temp % 10; 
        temp = temp / 10; 

        dec_value += last_digit * base; 

        base = base * 2; 
    } 

    return dec_value;
}

bool is_viable(int i, int mask){ 

	int cmp = pow(10,i);
	if(cmp > mask) return true;

	mask/=cmp;

	if(mask%10==1) return false;
	else return true;
}

int util(int index, int mask){

	if(index==n) return 1;

	int conv = binary_to_decimal(mask);
	if(dp[index][conv]!=-1) return dp[index][conv];

	int ans=0;
	bool found = false;

	loop(i,0,n){
		if(arr[index][i]==1 and is_viable(i, mask)){
			found=true;
			int temp = pow(10, i);
			mask += temp;
			ans += util(i+1, mask);
			mask -= temp;
		}
	}

	if(!found) return dp[index][conv] = 0;
	else return dp[index][conv] = ans;

}

