#include <bits/stdc++.h>

using namespace std;

typedef long long int ll;

const int N = 21;
const int mod = (int) 1e9 + 7;

int n;
int mat[N][N];
int memo[N][1 << N];

int dp(int at, int mask) {
    if(at == n) return 1;
    int &ans = memo[at][mask];
    if(ans != -1) return ans;
    ans = 0;
    for(int i = 0; i < n; ++i) {
        if((mask & (1 << i)) > 0) continue;
        if(mat[at][i] == 0) continue;
        ans += dp(at + 1, mask | (1 << i));
        ans %= mod;
    }
    return ans;
}

