inline int add(int x, int y) { return (x += y) >= Mod ? x - Mod : x; }

void init() {
  scanf("%d", &N);
  for (int i = 0; i < N; ++i)
    for (int j = 0; j < N; ++j)
      scanf("%d", &A[i][j]);
}

int dfs(int x, int s) {
  if (x == -1) return s == 0;
  if (Vis[x][s] == true) return Dp[x][s];
  Vis[x][s] = true;
  for (int i = 0; i < N; ++i) {
    if (A[x][i] == 0) continue;
    if (s & (1 << i)) {
      int q = s &~ (1 << i);
      Dp[x][s] = add(Dp[x][s], dfs(x - 1, q));
    }
  }
  return Dp[x][s];
}

void solve() {
  printf("%d\n", dfs(N - 1, (1 << N) - 1));
}

int main() {
  init();
  solve();
  return 0;
}

