            if (p_cnt > i) continue;
            rep(j, N) {
                if (grid[i][j] == 0) continue;
                dp[i + 1][(v | (1 << j))] += dp[i][v];
            }
        }
    }
    cout << dp[N][(1 << N) - 1] << '\n';
}

