int p[21][21];
int dp[21][1<<21];

int matching(int n,int i,int mask)
{
	if(i==n)
	{
		if(mask==(1<<n)-1) return 1;
		else return 0;
	}
	else if(dp[i][mask]!=-1) return dp[i][mask];
	else
	{
		int ans=0;
		for(int j=0;j<n;j++)
		{
			if(p[i][j])
			{
				int tempmask=1<<j;
				if(!(tempmask&mask))
				{
					ans+=matching(n,i+1,mask|tempmask);
					ans%=mod;
				}
			}
		}
		return dp[i][mask]=ans;
	}
}


