int fun(int i, int num) {
    if(i == n) {
        if(num == (1 << n) - 1) return 1;
        return 0;
    }
    if(dp[i][num] != -1) return dp[i][num];
    ll ans = 0;
    for(int j = 0; j < n; j++) {
        if(matrix[i][j] && !(num & (1 << j))) {
            ans += fun(i + 1, (num | (1 << j)));
            ans %= MOD;
        }
    }
    return dp[i][num] = ans;
}

