typedef long long int ll;
int mod=pow(10,9)+7;
int dp[22][(1<<22)+9];
vector<vector<int>>adj;
int solve(int n,int idx,int mask){
  if(mask==(1<<n)-1)
    return 1;
  if(idx==n)return 0;
  if(dp[idx][mask]!=-1)return dp[idx][mask];
  int new_mask;
  int ans=0;
  for(int i=0;i<(int)adj[idx].size();i++){
    int j=adj[idx][i];
    if(mask &(1<<j))continue;
    new_mask=mask;
    new_mask |=(1<<j);
    ans+=solve(n,idx+1,new_mask);
    ans%=mod;
  }
  dp[idx][mask]=ans;
  return dp[idx][mask];
}
int main(){
  int n;
  cin>>n;
  int arr[n][n];
  adj.resize(n+1);
