    for(ll j=0;j<n;j++){
      cin>>arr[i][j];
      if(arr[i][j]==1)adj[i].push_back(j);
    }
  }
  memset(dp,-1,sizeof(dp));
  int idx=0;
  int mask=0;
  int ans=solve(n,idx,mask);
  cout<<ans<<endl;
}

