ll dp[N][1ll << N] = {};
ll solve(ll r, ll c, ll n)
{
	if (r == n)
	{
		if (c == ((1ll << n) - 1))
			return 1;
		return 0;
	}
	if (dp[r][c] != -1)
		return dp[r][c];
	ll ans = 0;
	forn(i, n)
	{
		if (a[r][i] and !(c & (1ll << i)))
		{
			ans += solve(r + 1, (c | (1ll << i)), n);
			ans %= MOD;
		}
	}
	dp[r][c] = ans % MOD;
