using namespace std;

const int mod = 1e9+7;

struct Mint {
	long long x; Mint() : x(0) {}
	Mint(long long _x) : x ((_x%mod + mod)%mod) {}
	Mint& fix() { x = (x%mod + mod)%mod; return *this; }
	Mint& operator+=(const Mint& other) { if ((x += other.x) >= mod) { x-= mod; } return *this;}
	Mint& operator-=(const Mint& other) { if ((x += mod-other.x) >= mod) { x -= mod; } return *this; }
	Mint& operator*=(const Mint& other) { (x*=other.x)%=mod; return *this; }
	Mint operator+(const Mint& other) const { return Mint(*this) += other; }
	Mint operator-(const Mint& other) const { return Mint(*this) -= other; }
	Mint operator*(const Mint& other) const { return Mint(*this) *= other; }
	Mint operator-() const { return Mint(0) - *this; }
	Mint operator++(int) { Mint result(*this); *this += 1; return result; }
	Mint operator--(int) { Mint result(*this); *this -= 1; return result; }
	bool operator<(const Mint& other) const { return x < other.x; }
	bool operator==(const Mint& other) const { return x == other.x;} 
	// convert n to ll before using fstexp
	Mint fstexp(long long n) const { 
		Mint res(1), a(x);
		while (n > 0) { if (n & 1) { res  *= a; } a *= a; n >>= 1; }
	return res; }
	Mint operator ~ () const { return (*this).fstexp(mod - 2);}
};
ostream& operator << (ostream& out, const Mint& val) { return out << val.x; }
istream& operator >> (istream& in, Mint& val ) { in >> val.x; return in;}
