using namespace std;

ll mod = 1e9 + 7;

ll dp[22][1<<21];

ll nop(int man, int women_set, int total, int comp[][21])
{
  if(man >= total)
  {
    return (women_set == 0) ? 1 : 0;
  }

  if(dp[man][women_set] != -1)
    return dp[man][women_set];

  ll ans = 0;
  //cout<<women_set<<endl;
  //cout<<"calling for man: "<<man<<endl;
  for(int woman = 0 ; woman <total ; woman ++)
  {
    bool avail = ((women_set & (1<<woman)) == 0)?false:true;

    //cout<<"for woman: "<<woman<<" avail = "<<avail<<endl;

    if(avail && comp[man][woman])
    {
      ans += nop(man+1,(women_set ^ (1<<woman)),total,comp);
    }

  }

  return dp[man][women_set] = ans%mod;

}

