#include <iostream>
#include <vector>
#include <unordered_map>
#include <math.h>

using namespace std;

typedef long long int ll;
ll MOD = pow(10,9) + 7;

inline void allot_person(int& mask,int p)
{
    int z = (1<<p);
    mask |= z;
}

inline void unallot_person(int& mask,int p)
{
    int z = (1<<p);
    mask ^= z;
}

inline bool check_allot(int mask,int p)
{
    int z = (1<<p);
    mask &= z;
    return mask;
}

inline ll solve(vector<vector<bool>>& G,int& alloted,int woman,int n,vector<vector<ll>>& memo)
{
    //cout<<woman<<endl;

    if (memo[alloted][woman] != -1)
    {
        return memo[alloted][woman];
    }

    if (alloted == pow(2,n) - 1) return 1;
    if (woman == n) return 0;

    ll ans = 0;

    //allot

    for (int man=0;man<n;++man)
    {
        //cout<<"M"<<man<<endl;
        if (G[man][woman] && !check_allot(alloted,man))
        {
            //cout<<"GOT_IN"<<endl;
            allot_person(alloted,man);
            ans += solve(G,alloted,woman+1,n,memo);
            ans %= MOD;
            unallot_person(alloted,man);
        }
    }

    memo[alloted][woman] = ans;
    //ans %= MOD;

    return ans;

}


int main()
{
    int N;
    cin>>N;
    vector<vector<bool>> G(N,vector<bool>(N));

    for (int i=0;i<N;++i)
    {
        for (int j=0;j<N;++j)
        {
            bool x;
            cin>>x;
            G[i][j] = x;
        }
    }

    ll states = pow(2,N) + 1;
    vector<vector<ll>> memo(states,vector<ll>(N+1,-1));

    int mask = 0;

    cout<<solve(G,mask,0,N,memo)<<endl;

    return 0;
}

