mint dfs(int i,ll bit){
    //cout<<i<<" "<<bit<<endl;
    if(M[{i,bit}]>0)return dp[i][bit];
    M[{i,bit}]=1;

    if(i==n-1){
        bool abc=0;
        for(int j=0;j<n;j++){
            if(bit&(1<<j))continue;
            if(a[i][j]==0)continue;
            abc=1;
            break;
        }
        if(abc==1)return 1;
        else return 0;
    }

    mint res=0;
    for(int j=0;j<n;j++){
        if(bit&(1<<j))continue;
        if(a[i][j]==0)continue;
        bit|=(1<<j);
        res+=dfs(i+1,bit);
        bit&=~(1<<j);
    }
    dp[i][bit]=res;
    return res;
}
