ll solve(ll i, ll b)
{
    if (i == n)
    {
        if (b == ((1LL << n) - 1LL))
            return 1LL;
        else
            return 0LL;
    }

    if (dp[i][b] == -1)
    {
        ll ans = 0;
        for (int j = 0; j < n; j++)
        {
            ll a = b & (1LL << j);
            if (a == 0LL && check[i][j] == 1LL)
                ans = mod(ans + solve(i + 1, b | (1LL << j)));
        }

        dp[i][b] = ans;
    }
    return dp[i][b];
}

