int DP(int i, int mask)//já escolhi até o homem i - 1 e tenho essas mulheres sobrando
{
	if(dp[i][mask] != -1) return dp[i][mask];

	if(i == n - 1)
	{
		int women = log2( mask );

		return dp[i][mask] = v[i][women];
