ll solve(ll n, ll k) {
    //(n + 1) bits are set in k
    if (dp[n][k] >= 0)  return dp[n][k];
    if (!(k&(k-1)) && n == 0)   return dp[0][0] = a[0][__builtin_ctzll(k)];
