void findBitCombinations(int k) 
{ 
    string str = ""; 
    unordered_map<string, ll> mp;
    for (int len = 0; len <= k; len++)  
    { 
        DP[len][0].push_back(str); 
        str = str + "0"; 
    } 

    mp[str.substr(0,k)] = 1;
    for (int len = 1; len <= k; len++) 
    { 
        for (int n = 1; n <= len; n++) 
        { 
            for (string str : DP[len - 1][n]){
                DP[len][n].push_back("0" + str); 
                if(len == k)
                    mp["0"+str] = 0;
            } 

            for (string str : DP[len - 1][n - 1]){
                DP[len][n].push_back("1" + str); 
                if(len == k)
                    mp["1"+str] = 0;
            }
        } 
    } 

    for (int n = 0; n < k; ++n)
    {
        for (string str : DP[k - 1][n]){
            str = "0" + str;
            for (int j = 0; j < k; ++j)
            {
                if(str[j]=='0' && arr[n][j] == 1){
                    string t = str;
                    t[j] = '1';
                    mp[t] = (mp[t] + mp[str])%MOD;
                }
            }
        }

        if(n)
        for (string str : DP[k - 1][n - 1]){
            str = "1" + str;
            for (int j = 0; j < k; ++j)
            {
                if(str[j]=='0' && arr[n][j] == 1){
                    string t = str;
                    t[j] = '1';
                    mp[t] = (mp[t] + mp[str])%MOD;
                }
            }
        }
    }

    str ="";
    for (int i = 0; i < k; ++i)
    {
        str += "1";
    }
    cout<<mp[str];
} 

