const int MOD = 1e+9 + 7;

long long solution(int N, vector<vector<int>>& a)
{
    vector<vector<long long>> dp(N+1, vector<long long>(1<<N, 0));
    dp[0][0] = 1;
    for(int i = 0; i < N; ++i){
        for(int j = 0; j < (1<<N); ++j){
            if(__builtin_popcount(j) != i) continue;
            for(int k = 0; k < N; ++k){
                if(!(j & (1<<k)) and a[i][k] == 1){
                    dp[i+1][j+(1<<k)] += dp[i][j];
                    dp[i+1][j+(1<<k)] %= MOD;
                }
            }
        }
    }
    return dp[N][(1<<N)-1];   
}

