int countbits(int x){
	int count = 0 ;
	while(x){
		count++;
		x = x&x-1;
	}
	return count;
}

long long int solve(int x, int n){
	if(x == (1<<n) -1) return 1;
	if(x >= (1<<n)) return 0;
	if(dp[x] != -1) return dp[x];
	int ans = 0;
	int count = countbits(x);
	// cout<<x<<" "<<n<<"\n";

	for(int i=0;i<n;i++){
		if(!(x&(1<<i)) && arr[count][i] == 1) ans += solve(x | (1<<i), n)%mod;
		ans%=mod;
	}
	dp[x] = ans;
	return dp[x];
}

