long long int mod=1e9+7;

long long int solve( int root, int prev, int col){
   //coloring the root with black color
   if(dp[root][col]!=-1)
   	return dp[root][col];
   dp[root][col]=1;
   if( col==0){
     for(int v:adj[root]){
     	if(v!=prev){
          solve(v,root, 1);
          dp[root][col]*=dp[v][1];
          dp[root][col]%=mod;
     	}
     }  
   } 
   else{

     for(int v:adj[root]){
     	if(v!=prev){
     	  solve(v,root,0);
     	  solve(v,root, 1);	
          dp[root][col]*=((dp[v][0]+dp[v][1])%mod);
          dp[root][col]%=mod;
     	}
     } 
   }
   return dp[root][col]%mod;

}


