int solve(vector<ll>arr, int n, int i, int mask)
{
	if(i==n && mask==0)
		return dp[i][mask]=1;
	if(mask==0)
		return dp[i][mask]=1;
	if(dp[i][mask]!=-1)
		return dp[i][mask];
	ll val=arr[i];
	val&=mask;
	int ans=0;
	for(int i=0;i<n;i++)
	{
		if((val>>i)&1)
		{
			ans= (ans+ solve(arr,n,i+1,mask&(~(1<<i))))%mod;
		}
	}
	return dp[i][mask] =ans%mod;

}

