int f(int i, int mask)
{
    if (mask == 0)
        return 1;
    else if (i == 21)
        return 0;

    if (dp[i][mask] != -1)
        return dp[i][mask];

    int sol = 0;
    for (int j = mask; j > 0; j -= (j & (-j)))
