int solve(int mask) {

	if (mask == (1LL<<n)-1) return 1;
	// bool found = false;
	if (seen[mask]) return dp[mask];
	int i = 0;

	for(int j = 0; j < n; ++j){
		if (mask & (1LL<<j)) ++i;
	}

	int ans = 0;

	for(int j = 0; j < n; ++j){
		if (matrix[i][j]){
			if ((1LL<<j)&mask) continue;
			ans += solve(mask|(1LL<<j));
			ans %= MOD;
		}
	}

	seen[mask] = true;
	return dp[mask] = ans;
}

