  }

  // dp[S] := bicnt(S)番目までの男性と, 女性の部分集合Sでマッチングする場合の数
  vector<int> dp(1 << n, 0);
  vector<int> bitcnt(1 << n, 0);
  // 男性0人と女性0人とマッチングする場合の数は1
  // (マッチングがないという状態が1つある)
  dp[0] = 1;

  for (int bit = 1; bit < (1 << n); bit++) {
    bitcnt[bit] = bitcnt[bit / 2] + (bit & 1);
    for (int lady = 0; lady < n; lady++) {
      // 集合に含まれていないなら無視
      if (!((bit >> lady) & 1)) {
        continue;
      }
      // 差集合はあるbitだけたってるやつを引いてあげればいい
      dp[bit] += dp[bit - (1 << lady)] * a[bitcnt[bit] - 1][lady];
      dp[bit] %= MOD;
    }
  }
  cout << dp[(1 << n) - 1] << endl;
  return 0;
}

