						if (dp[i][m] >= MOD) dp[i][m] %= MOD;
					}

				}
			}

			if (i == n - 1) {
				ans += dp[i][m];
				if (ans >= MOD) ans %= MOD;
			}
		}
	}

	cout << ans;

	return 0;
}

