int memo[1 << 21];
int A[maxn][maxn];
int solve(int mask){
    int last = N-__builtin_popcount(mask);
    if (!mask && last == N)return 1;
    if(!mask || last == N)return 0;
    int &ans = memo[mask];
    if (ans != -1)return ans;
    ans = 0;
    for (int i = 0;i < N;i++){
        if (mask & (1 << i)&& A[last+1][i])
            ans =(ans+solve(mask^1 << i))%mod;
    }
    return ans;
}
