	ll dp[22][1 << 21];
	memset(dp, 0, sizeof(dp));
	int mn = 1 << n;
	int p = 1;
	int dig = 0;
	while (p < mn )
	{
		dp[1][p] = tb[1][dig];
		p <<= 1;
		dig++;
	}
	for (int i = 2; i <= n; i++)
	{
		for (int j = 0; j < 1 << n; j++)
		{
			int cnt = 0;
			int tj = j;
			while (tj > 0)
			{
				if (tj & 1) cnt++;
				tj >>= 1;
			}
			if (cnt != i) continue;
			for (size_t k = 0; k < n; k++)
			{
				if ((j & (1 << k)) == 0) continue;
				if (tb[i][k] == 0) continue;
				dp[i][j] += dp[i - 1][j ^ (1 << k)];
				dp[i][j] %= INF;
			}
		}
	}

	cout << dp[n][(1 << n) - 1] << endl;
}


