int N;

bool is_ok(int number, int i)
{
	return (number & (1<<i)) == 0;
}

ll run(int mask, int i)
{
	if (i == N)
		return 1;
	if (dp[mask] != -1)
		return dp[mask];
	dp[mask] = 0;
	for (int j(0); j < N; ++j)
		if( is_ok(mask, j) && can[i][j])
		{
			dp[mask] += run(mask + (1<<j), i+1);
			dp[mask] %= MOD;
		}
	return dp[mask];
}

int main(void)
{
	ios_base::sync_with_stdio(false); cin.tie(0); cout.tie(0);

	read(N);
	for (int i(0); i < MAX; ++i)
		dp[i] = -1;
	FOR(i,0,N) FOR(j,0, N)
		read(can[i][j]);
	cout << run(0, 0) << endl;
}

