const int mod = 1e9 + 7;
int n; // no. of pairs
int findways(vector<int> &dp, int mask, vector<vector<int>> &check)
{
  //cout << "mask " << std::bitset<5>(mask)<<endl;
  if (mask == 0)
    return 1;
  if (dp[mask] != 0)
    return dp[mask];
  int male = __builtin_popcount(mask);       // ith male
  for (int female = 0; female < n; ++female) // ith female
    if (check[male - 1][female] && (mask & (1 << female)))
    {
      int new_mask = mask ^ (1 << female);

      dp[mask] = (dp[mask] + findways(dp, new_mask, check)) % mod;
    }
  return dp[mask];
}

