ll solve(int i, ll s) {
	if (s == 0) {
		return 1;
	}

	if (i == n) {
		return 0;
	}

	if (dp[i][s] != -1) {
		return dp[i][s];
	}

	ll tmp = s;
	dp[i][s] = 0;

	for (int j = 0; j < n; j++) {
		int bit = tmp & 1;
		if (bit && c[i][j] == 1) {
			dp[i][s] = (dp[i][s] + solve(i + 1, (s ^  (1 << j)))) % mod;
		}
		tmp = tmp >> 1;
	}

	return dp[i][s];
}


