//Solution
void solve(){
    ll n; cin>>n;
    vec<vec<ll>> match(n,vec<ll>(n,0LL));
    for(ll i = 0LL; i<n; i++){
        for(ll j = 0LL; j<n; j++){
            cin>>match[i][j];
        }
    }
    ll mxN = (1LL<<n);
    vec<vec<ll>> dp(n+1,vec<ll>(mxN,0LL)); dp[0][0] = 1;
    for(ll i = 1LL; i<=n; i++){
        for(ll mask = 0LL; mask<mxN; mask++){
            if(!dp[i-1][mask]){continue;}
            for(ll j = 0LL; j<n; j++){
                if(match[i-1][j]){
                    ll sub_mask = 1<<j;
                    if(!(mask&sub_mask)){
                        add_self(dp[i][mask|sub_mask],dp[i-1][mask]);
                    }
