void solve()
{
	ll N;
	cin >> N;
	vvll a(N);
	REP(i, N){ a[i] = cinv(N); }

	vector<map<ll, mll>> dp(N);

	REP(j, N){
		if (a[0][j] == 0) continue;
		dp[0][1LL<<j] = 1;
	}

	REPS(i, 1, N-1){
		EACH(e, dp[i-1]){
			ll bit = e.first;
			mll count = e.second;
			REP(j, N){
				if (a[i][j] == 0) continue;
				ll mask = (1LL<<j);
				if (bit & mask) continue;
				dp[i][bit | mask] += count;
			}
		}
	}
	mll ans = dp[N-1][(1LL<<N)-1];
	cout << ans << '\n';
}

