long long a[200005] = {0};
RMQ rmq;

lli solve(){
  lli ans=0;
  rmq = RMQ(n+1);
  for(lli i=0;i<n;i++){
    lli now = a[i];
    now += rmq.pick(0,h[i]);
    rmq.update(h[i],now);
    ans = max(ans,now);
  }
  return ans;
}

