ll help(ll mask, int man,const vector<vector<int>> &mp, int n)
{
    if (man >= n && (mask == (1 << n) - 1))
        return 1;
    else if (man >= n)
        return 0;

    if (dp[mask] != -1)
        return dp[mask];
    ll ans = 0;
    for (int i = 0; i < n; i++)
    {
        if (mp[man][i] && !(mask & (1 << i))){
            ans += help(mask ^ (1 << i), man + 1, mp, n);
            ans %= p;
        }
    }
    return dp[mask] = ans;
}

ll factorial(ll n)
{
    if (n == 1 || n == 0)
        return 1;
    return  n * factorial(n - 1);
}

