int solve(int m, int w) {
	if (m == n) {
		if (w == 0) {
			return 1;
		}
		return 0;
	}
	if (dp[m][w] != -1) {
		return dp[m][w];
	}
	ll t = 0;
	for (int i = 0; i < n; i++) {
		int val = (1 << i);
		bool available = (((val & w) == 0)? 0 : 1);
		if (available && a[m][i]) {
			t = (t + solve(m + 1, val ^ w)) % mod;
		}
	}
	return dp[m][w] = t;
}

