int n, a[25][25];
ll dp[(1 << 21) + 5];

ll solve(int ind, int mask){
	if(ind == n){
		return __builtin_popcount(mask) == n; //all paired 
	}
	if(dp[mask] != -1){
		return dp[mask];
	}
	ll ans = 0;
	for(int i = 0; i < n; i++){
		if(a[ind][i] && !(mask & (1 << i))){
			ans += solve(ind + 1, mask | (1 << i));
			ans %= MOD;
		}
	}
	return dp[mask] = ans % MOD;
}

