int dp[100000000];
int ways(int **mat,int n,int p,int mask)
{
    if(mask==((1<<n)-1))
        return 1;
    int ans=0;
    if(dp[mask]>0)
        return dp[mask];
    for(int i=0;i<n;i++)
    {
        if((mask&(1<<i))==0 && mat[p][i]==1)
        {
            ans=(ans%MOD+ways(mat,n,p+1,(mask|(1<<i)))%MOD)%MOD;
        }
    }
    return dp[mask]=ans;
}
