namespace SOLVE {
	const int half = 12;
	int n;
	int FIRST, SECOND;
	vector<vector<VLL>> memo;

	vector<VLL> adjmatrix;


	ll counts(int men, ll first, ll second) { // first and second half of the bitsets
		// debug_out(first, second);


		if (memo[men][first][second] != -1) {
			return memo[men][first][second];
		}

		if (men == n) {
			if (first == 0 && second == 0) {
				memo[men][first][second] = 1;
				return 1;
			}
			memo[men][first][second] = 0;
			return 0;
		}

		ll count = 0;

		REP(i, 0, FIRST) {
			if (first & (1 << i)) {
				if (adjmatrix[men][i]) {
					count += counts(men + 1, first & ~(1 << i), second);
					count %= mod;
				}
			}
		}

		REP(i, 0, SECOND) {
			if (second & (1 << i)) {
				if (adjmatrix[men][i + half]) {
					count += counts(men + 1, first, second & ~(1 << i));
					count %= mod;
				}
			}
		}
		memo[men][first][second] = count;
		// debug_out(men, first, second, memo[men][first][second]);
		return count;


	}

	void main() {
		// dp[bitmask] - bitmask says how many people are left to choose from.
		in(n);
		adjmatrix.resize(n, VLL(n));

		REP(i, 0, n) {
			REP(j, 0, n) {
				in(adjmatrix[i][j]); // men women
			}
		}



		if (n <= half) {
			FIRST = n;
			SECOND = 0;
		}
		else {
			FIRST = half;
			SECOND = n - half;
		}

		memo.resize(n + 5, vector<VLL>((1 << FIRST) + 5, VLL((1 << SECOND) + 5, -1)));

		debug_out("processed", FIRST, SECOND);

		ll ans = counts(0, (1 << FIRST) - 1, (1 << SECOND) - 1);
		ans %= mod;
		cout << ans;


	}
}


