const int N = 22;
const int MOD = 1e9 + 7;

int dp[1 << N], graph[N][N];

void add(int& a, int b) {
    a += b;
    if (a >= MOD)
        a -= MOD;
}

void solve() {
    int n;
    cin >> n;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j)
            cin >> graph[i][j];
    }

    dp[0] = 1;
    for (int msk = 1; msk < (1 << n); ++msk) {
        int bits = 0, temp = msk;
        while (temp) {
            bits += temp % 2;
            temp /= 2;
        }

        for (int i = 0; i < n; ++i) {
            if (graph[bits - 1][i] && (msk & (1 << i)))
                add(dp[msk], dp[msk ^ (1 << i)]);
        }
    }

    cout << dp[(1 << n) - 1] << '\n';
}

