#define REP(i, n) for(int i = 0; i < (int)(n); ++i)
#define FOR(i, m, n) for(int i = (int)(m); i < (int)(n); ++i)

const int MOD = 1e+9 + 7;

int main()
{
    int N;
    cin >> N;
    vector<vector<int>> a(N, vector<int>(N));
    REP(i, N) REP(j, N) cin >> a[i][j];

    // dp[i][j]: 男性は 1-index, 女性は 0 index で状態
    //           i 番目の男性までマッチングしたとき、 女性 j もマッチングが終わっている場合の数
    vector<vector<long long>> dp(N+1, vector<long long>(1<<N));
    dp[0][0] = 1;
    REP(i, N){
        REP(j, (1<<N)){  // 立っている bit はマッチが終わっている
            if(i != __builtin_popcount(j)) continue;
            REP(k, N){
                if(!(j & (1<<k)) and a[i][k] == 1){
