double JHelper(vector<vector<vector<double>>>& dp,int a,int b,int c,int n) {
    //cout<<a<<" "<<b<<" "<<c<<endl;
    if(a==0&&b==0&&c==0)
        return 0;
    if(dp[a][b][c]>0)
        return dp[a][b][c];
    double sum=a+b+c;
    double ans=1.0*n/sum;
    if(a)
        ans+=JHelper(dp,a-1,b,c,n)*(1.0*a/sum);
    if(b)
        ans+=JHelper(dp,a+1,b-1,c,n)*(1.0*b/sum);
    if(c)
        ans+=JHelper(dp,a,b+1,c-1,n)*(1.0*c/sum);
    dp[a][b][c]=ans;
    return ans;
}
