void solve() {
    int N;
    cin >> N;
    // ちょっとTLE気味？？　bitsetで高速化するのかな
    vector<vector<int>> A(N, vector<int>(N));
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            cin >> A[i][j];
        }
    }
    int mod = 1e9 + 7;
    vector<vector<int>> dp(N + 1, vector<int>(1 << N, 0));
    dp[0][0] = 1;

    for(int i = 0; i < N; i++) {
        for (int s = 0; s < 1 << N; s++) {
            for (int j = 0; j < N; j++) {
                if (s >> j & 1) continue;
                if (A[i][j] == 0) continue;
                dp[i + 1][s | (1 << j)] += dp[i][s];
                dp[i + 1][s | (1 << j)] %= mod;
            }
        }
    }
    cout << dp[N][(1 << N) - 1] << endl;
}

