ll dfs(ll d){
    ll ans = 0;
    if(dp[d][check] != -1) return dp[d][check];
    if(d == N-1){
        for(int i=0;i<N;i++){
            if(m[N-1][i] == 1 && ((check>>i)&1) == 0) ans++;
        }
        ans %= MOD;
        return dp[d][check] = ans;
