ll mod=1000000007;

void solve(int n, int m)
{
    if(dp[n][m]!=-1)
        return;
    dp[n][m]=0;

    if(m==N-1)
    {
        for(int i=0; i<N; i++)
        {

            if( a[m][i]==1 && (n&(1<<i))==(1<<i))
            {
                dp[n][m]=1;
                dp[n][m]%=mod;
                return;
            }
        }
    }

    for(int i=0; i<N; i++)
    {

        if( a[m][i]==1 && (n&(1<<i))==(1<<i))
        {
            solve(n^(1<<i), m+1);
            dp[n][m]+=dp[n^(1<<i)][m+1];
            dp[n][m]%=mod;
        }
    }

}

