ll rec(int S, int V, int n){
	if(DP[S][V] >= 0){
		return DP[S][V];
	}

	if(!a[n][V]){
		return 0;
	}

	if(n == N-1){
		return a[N-1][V];
	}

	ll sum = 0;
	for(int i = 0; i < N; i++){
		if(i != V && !(S >> i & 1)){
			sum += rec(S | (1 << V), i, n+1);
			sum %= mod;
		}
	}

	DP[S][V] = sum;
	return DP[S][V];
}

ll calc(){
	ll sum = 0;
	for(int i = 0; i < N; i++){
		sum += rec(0, i, 0);
		sum %= mod;
	}
	return sum;
}

