    for (int i=0; i<N; ++i) 
        for (int j=0; j<N; ++j) 
            cin >> arr[i][j];

    ll total_subsets = pow(2, N);            
    // dp[i] -> i in binary representation stores which women are already matched            
    ll dp[total_subsets] = {0};
    dp[0] = 1;

    for (ll i=1; i<total_subsets; ++i){
        // We can only match k men with k women, so counting the number of 1's in bitvector tells us for which man we are matching.
        int man = countSetBits(i);
        // We iterate over all matched women, and see if the jth women can actually get matched with @man
        for (int j=0; j<N; ++j){
            // If jth woman was already matched, we need to see if it couldve been matched with @man and add that count to dp[i]
            if (((i>>j)&1) && (arr[man-1][N-j-1]))
                dp[i] += dp[~(1<<j)&i];     
            dp[i] = dp[i] % MOD;
        }
    }

    cout << dp[total_subsets-1];
    return 0;
}

