struct modll{using X = int; X v=0;operator X(){return v;}modll(){}modll(int n){v=n;}modll(ll n){v=n;};
modll operator+(ll b){ll ret=v+b;if(ret>=MOD)ret-=MOD;return {ret};}
modll operator+(int b){ll ret=v+b;if(ret>=MOD)ret-=MOD;return {ret};}
modll operator+(modll b){X ret=v+b.v;if(ret>=MOD)ret-=MOD;return {ret};}
modll operator-(ll b){ll ret=v-b;if(ret<0)ret+=MOD;return {ret};}
