modll &operator+=(modll b){v+=b.v;if(v>=MOD)v-=MOD;return*this;}
modll &operator-=(modll b){v-=b.v;if(v<0)v+=MOD;return*this;}
modll &operator*=(modll b){v=v*b.v%MOD;return*this;}
modll &operator++(int){v++;if(v>=MOD)v-=MOD;return*this;}
modll &operator--(int){v--;if(v<0)v+=MOD;return*this;}
modll inv(modll &x,int y){if(y==0)return {1};
modll p=inv(x,y/2);p=p*p;return(y%2==0)?p:(x*p);}
modll operator/(modll b){return {(v*inv(b,MOD-2))%MOD};}
modll operator/(int b){modll t=b;return{(v*inv(t,MOD-2))%MOD};}
