void solve() {
	int n;
	cin >> n;
	int allmask = (1 << n);
	vector<vector<bool>> m(n, vector<bool>(n));
	for(int i = 0; i < n; i++) for(int j = 0, p; j < n; j++) {
		cin >> p; m[i][j] = p;
	}
	vector<vector<modll>> dp(n + 1, vector<modll>(allmask, 1));
	for(int i = 1; i <= n; i++) {
		for(int mask = 0; mask < allmask; mask++) {
			if(i != __builtin_popcount(mask)) continue;
			modll ret = 0;
			for(int j = 0; j < n; j++) {
				if(m[i - 1][j] and (mask >> j) & 1) {
					int newmask = mask & ~(1 << j);
					ret += dp[i - 1][newmask];
				}
			}
			dp[i][mask] = ret;
		}
	}
	cout << dp[n][allmask - 1] << "\n";
}

