int func(int idx, int mask)
{
	if(idx==n)
		return (mask == (int)pow(2,n)-1);
	int & ans = dp[idx][mask];
	if(ans != -1)
		return ans;
    ans = 0;
	for(int j=0;j<n;j++)
	{
		if(arr[idx][j] && !(mask & (1<<(n-j-1))))
			ans = (ans + func(idx+1,mask|(1<<(n-j-1))))%mod;
	}
	return ans;
}

