ll rec(ll mask,ll j,ll n)
{
    if(mask == ((1ll << n) - 1))//All done right
     return 0;
   // else if((mask == 0) and (j != (n-1))) return 0;//No way left
    else if(j == (n-1))//ek jon e baki
    {
        //tar pochondo r kyeu ache naki dekhte hobe to
        bool f = false;
        for(ll i = 0;i < n;i++)
        {
            if((!(mask & (1ll << i))) and a[i][j])
            {
              f = true;
              break;
            }
        }
        if(f) return memo[mask][j] = 1;
        else return memo[mask][j] = 0;
    }
    else if(memo[mask][j] != -1)
     return memo[mask][j];//Return the memoized solution
    else
    {
        //Well before coming to the generalised solution it is important that we think about the base cases a little bit more

        ll val = 0;
        for(ll k = 0;k < n;k++)
        {
            if((a[k][j] == 1) and ((mask & (1ll << k)) == 0))
            {
                val = ((val % mod) + (rec((mask | (1ll << k)),j + 1,n)) % mod)%mod;
            }
        }
        return memo[mask][j] = val % mod;
    }

}
