ll solve(ll pos, ll mask){
    if(pos == n && mask == ((1<<n) -1)) return 1;
    if(pos>=n) return 0;
    if(dp[pos][mask]!=-1) return dp[pos][mask];
    ll res = 0;
    for(ll i = 0; i < n; i++){
        ll k = arr[pos][i];
