int MAX = 1e9+7;

vector<vector<int> > records;
int num;
vector<vector<int> > compatibilities;

int go(int unmatched_man, int matched_women){

    if(records[unmatched_man][matched_women] != -1)
        return records[unmatched_man][matched_women];

    if(unmatched_man == num){
        if(matched_women == ((1 << num)-1))
            return 1;
        return 0;
    }

    records[unmatched_man][matched_women] = 0;

    for(int woman = 0; woman < num; woman++){
        if(compatibilities[unmatched_man][woman])
        {
            if((matched_women & (1 << woman)) == 0){
                int new_matched = matched_women | (1 << woman);
                (records[unmatched_man][matched_women] += go(unmatched_man + 1, new_matched)) %= MAX;
            }
        }

    }

    return records[unmatched_man][matched_women];
}


int match(){
    num = compatibilities.size();

    records = vector<vector<int> >(num+1, vector<int>((1 << num), -1));

    return go(0, 0);
}

