int g[N][N];

int solve(int i, int t) {
  if (i == n) {
    return 1;
  }
  if (!vis[i][t]) {
    vis[i][t] = true;
    for (int j = 0; j < n; j++) {
      if (!(t & 1 << j) && g[i][j]) {
        add(dp[i][t], solve(i + 1, t | 1 << j));
      }
    }
  }
  return dp[i][t];
}

