int binpow(int a, int b){
	int res = 1;
	while(b){
		if(b % 2)
			res = res * a;
		a *= a;
		b >>= 1;
	}
	return res;
}

ll dp(vector<vector<int>> &v, int mmask, int i){
	if(i == v.size())
		return 1;
	if(memo[mmask][i] != -1)
		return memo[mmask][i];
	memo[mmask][i] = 0;
	for(int e : v[i]){
