int matching(int pos, int mask) {
	if (pos == n) return 1;
	int &ans = dp[mask];
	if (ans != -1) return ans;

	ans = 0;
	for (int i = 0; i < n; i++) {
		if (!(mask & (1 << i)) and rel[pos][i]) {
			ans += matching(pos + 1, mask | (1 << i));
			ans %= mod;
		}
	}

	return ans;
}

