ll recursion(ll &n,ll mask,vector<vector<int>> &vec,ll level,vector<vector<int>> &dp){
  if(level>=n){
    if(mask==allmask) return 1;
    return 0;
  }
  if(dp[mask][level]!=-1) return dp[mask][level];
  ll val=0;
  for(int i=0;i<n;i++){
    if(vec[i][level]==1 && (mask & (1<<i))==0){
      val=(val%mod+recursion(n,mask | (1<<i),vec,level+1,dp)%mod)%mod;
    }
  }
  dp[mask][level]=val;
  return dp[mask][level]%mod;
} 
