const int N = 22;
const ll MOD = 1e9 + 7;

ll dp[N][1 << N], graph[N][N];

void solve() {
    int n;
    cin >> n;

    const int msklen = 1 << n;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j)
            cin >> graph[i][j];
    }

    dp[0][0] = 1;
    for (int i = 1; i <= n; ++i) {
        for (int msk = 0; msk < msklen; ++msk) {
            for (int j = 0; j < n; ++j) {
                if (msk & (1 << j) && graph[i - 1][j])
                    dp[i][msk] = (dp[i][msk] + dp[i - 1][msk ^ (1 << j)]) % MOD;
            }
        }
    }

    ll ans = 0;
    for (int i = 0; i < msklen; ++i)
        ans += dp[n][i];
    cout << ans << '\n';
}

int main() {
    ios::sync_with_stdio(0);
    cin.tie(nullptr); cout.tie(nullptr);
    srand(time(0));

    int t = 1;
//    cin >> t;
    while (t--)
        solve();

    return 0;
}

