const int N = 25;

map<pll, ll>dp;

ll power(ll n, ll p)
{
  ll res = 1;

  while (p)
  {
    if (p & 1) res *= n;
    res %= mod;
    p >>= 1LL;
    n *= n;
    n %= mod;
  }
  return res;
}

ll fac(ll n)
{
  ll ans = 1;

  fo(i, 2, n) ans = (ans * i) % mod;
  return ans;
}

bool comp[N][N];

ll n;

ll f(int mask1, int mask2)
{

  if (!(mask1 | mask2)) return 1;
  if (!mask1 and mask2) return 0;
  if (mask1 and !mask2) return 0;

  if (dp.count(mp(mask1, mask2))) return dp[mp(mask1, mask2)];

  ll cur = 0;
  ll ans = 0;

  fo(i, 0, n - 1)
  {
    if (mask1 & (1 << i))
    {
      fo(j, 0, n - 1)
      {
        cur = 0;
        if (mask2 & (1 << j) and comp[i][j]) cur = f(mask1 ^ (1 << i) , mask2 ^ (1 << j));

        ans += cur;
        ans %= mod;
      }
    }
  }

  return dp[mp(mask1, mask2)] = ans;
}
void solve()
{
  cin >> n;

  fo(i, 0, n - 1)
  {
    fo(j, 0, n - 1) cin >> comp[i][j];
  }

  dp.clear();

  ll ans = f((1 << n) - 1, (1 << n) - 1);

  ans *= power(fac(n), mod - 2);
  ans %= mod;

  cout << ans << endl;


}

