    // Bit演算を楽にするライブラリ ２進数
    // @author tada
    class Bit {
    public:
        // コンストラクタでサイズ数
        Bit(int length) {
            length_ = length;
            bit_ = -1; // while(bit.next()) をされるのを想定
        }

        // 一つ先の値に移動する もう次に進めないならばfalseを返す
        bool Next() {
            if (++bit_ >= (1 << length_)) return false;
            return true;
        }

        // Bit操作 指定したインデックスを変更する
        void Change(int i, int value = 1) {
            if (value == 1) bit_ |= (1 << i);
            else bit_ &= ~(1 << i);
        }

        // 指定したインデックスが1かどうか
        bool IsSelected(int i) {
            return bit_ & (1 << i);
        }

        // 1の個数を返す 引数で範囲 [l, r) 準備中
        int GetSelectedNum(){ //int l, int r) {
            return __builtin_popcount(bit_);
        }

        // ビット情報を初期状態に戻す
        void Reset() {
            bit_ = -1;
        }

        // ビット列をint型で返す
        int GetBit() {
            return bit_;
        }

        // ビット長を返す
        int GetLength() {
            return length_;
        }

    private:
        int bit_;
        int length_;
    };
}

int main() {

    int n = inp1;
    vector<vector<int>> a(n, vector<int>(n));
    rep(i, n)rep(j, n) cin >> a[i][j];

    // bitDP

    // dp[i][s] := i番目までの男を見たときに，女性集合sとマッチするパターン数
    // 女性集合sとは 0110 の場合は，2,3番目の女性がマッチングしている
    vector<vector<ll>> dp(n + 1, vector<ll>((1 << n) + 1, 0LL));

    dp[0][0] = 1LL;

    Bit bit(n);

    rep(i, n) {
        bit.Reset();
        while (bit.Next()) {
            int b = bit.GetBit();
            // ペアが決まっている男性の数と女性の数が一致しないと意味がない
            if (i + 1 != bit.GetSelectedNum()) continue;
            // ひとり少ないやつから遷移
            rep(j, n) {
                dp[i + 1][b] += dp[i][b & ~(1 << j)] * a[i][j];
                dp[i + 1][b] %= mod;
            }
        }
    }

    //Cout(dp[n]);

    Cout(dp[n][(1 << n) - 1]);

    return 0;
}

