ll ways(int i,int womensubset,vector<vector<int>> &v,int n)
{
    // initilly womensubset is all 1 bcz all the women is available ......
    if(i==(n+1))
    {
        return womensubset==0?1:0;
    }
    else
    {
        if(dp[i][womensubset]!=-1)
        {
            return dp[i][womensubset];
        }

        long long int  ans=0;
        for(int j=0;j<n;j++)
        {
            // sabse pehle ye check krna hai ki kya vo women available that is abhi vo kisi bhi 
            // men ke sath paired nhi hai...
            int available=(womensubset&(1<<j)?1:0);
            // agr non zero hai it simply means ki vo jth bit set hai that is vo available hai..
            if(available && v[i][j+1]==1)
            {
                // available bhi hai aur uss bande ke sath compatible bhi hai...
                ans=(ans%p+ways(i+1,(womensubset^(1<<j)),v,n)%p)%p;
                // ab vo jth women ti paired ho gyi tu vo agle bande ke liye available nhi hai
                // it means ki ab aapko jth bit ko unset krna padega..
            }
        }
        return dp[i][womensubset]=ans;
    }
}

ll solve(int n,vector<vector<int>> &v)
{
    memset(dp,-1,sizeof(dp));
    return ways(1,((1<<n)-1),v,n);
}

