void _main(int tc) {
  int n;
  cin >> n;
  vector<vector<int>> can(n, vector<int>(n));
  rep(n) { rep(j, n) cin >> can[i][j]; }
  int const mod = 1e9 + 7;
  auto addSelf = [](int &a, int b) -> void {
    a += b;
    if (a >= mod) a -= mod;
  };

  /************* Recursive ************* O(N*2^21) fast enough
  vector<vector<int>> mem(n, vector<int>(1 << n, -1));
  function<int(int, int)> f = [&](int i, int mask) -> int {
    if (mask == (1 << n) - 1) return 1;
    if (i == n) return 0;
    if (mem[i][mask] != -1) return mem[i][mask];
    mem[i][mask] = 0;
    rep(j, n) {
      if (can[i][j] && ((mask >> j) & 1) == 0)
        addSelf(mem[i][mask], f(i + 1, mask | (1 << j)));
    }
    return mem[i][mask];
  };
  cout << f(0, 0) << endl;
  *********** End Recursive ***********/

  /************* Iterative ************* O(N*N*2^21) too slow
  vector<vector<int>> mem(n + 1, vector<int>((1 << n)));

  rep(n + 1) { mem[i][(1 << n) - 1] = 1; }

  rep(i, n - 1, -1) {
    rep(mask, (1 << n) - 1, -1) {
      rep(j, n) {
        if (can[i][j] && ((mask >> j) & 1) == 0) {
          addSelf(mem[i][mask], mem[i + 1][mask | (1 << j)]);
        }
      }
    }
  }
  cout << mem[0][0] << endl;
  *********** End Iterative ***********/
  /*
    We can observe that the index "i" corresponds exactly to the number of "1"
    bits in mask, because if there are "i" women selected that means that there
    will be "i" bits set to "1" and it also means that "i" men are also already
    selected. Therefore index "i" is equal to the number of "1" bits in mask.
  */
  /*
    We should iterate backwards because our DP depends always on bigger numbers.
    000
    001
    010
    011
    100
    101
    110
    111
   */
  vector<vector<int>> mem(n + 1, vector<int>((1 << n)));

  rep(n + 1) { mem[i][(1 << n) - 1] = 1; }

  rep(mask, (1 << n) - 2, -1) {
    int i = __builtin_popcount(mask);
    rep(j, n) {
      if (can[i][j] && ((mask >> j) & 1) == 0) {
        addSelf(mem[i][mask], mem[i + 1][mask | (1 << j)]);
      }
    }
  }
  cout << mem[0][0] << endl;
}
