  std::ios::sync_with_stdio(false);

  ll n;
  std::cin>>n;

  std::vector<std::vector<ll>> a(n,std::vector<ll>(n));
  rep(i,0,n)rep(j,0,n)std::cin>>a[i][j];

  std::vector<ll> memo(1ll<<n,-1);

  memo[0]=1;

  auto dfs=[&](auto f,ll bit,ll now)->ll{
    if(memo[bit]!=-1)return memo[bit];

    memo[bit]=0;
    rep(i,0,n){
      if(a[now][i]&&(bit&(1ll<<i))){
        memo[bit]+=f(f,bit^(1ll<<i),now+1);
        memo[bit]%=MOD;
      }
    }
    return memo[bit];
  };

  std::cout<<dfs(dfs,(1ll<<n)-1,0)<<"\n";

  return 0;
}

