#include <bits/stdc++.h>
using namespace std;
#define ll long long int
const int sz=22;
const ll MOD=1e9+7;
ll dp[sz][(1<<22)]; // represents total ways to pair men with women when men from
 // i to N are present to match with j subset of women. Subset is represented using
 // bitmasking where every bit in integer j represnts whether women is present(1) or
 // not(1) 

// Dp with Bistmasking
ll solve(vector<vector<int>>& compat,int i,int womenSubset,int men){
    if(i==men+1){
        if(womenSubset==0)
            return 1;
        else
            return 0;
    }
    if(dp[i][womenSubset]!=-1)
        return dp[i][womenSubset];
    ll ans=0;
    for(int women=0;women<men;women++){
        bool available=(((1<<women)&womenSubset)==0)?0:1;
        if(available and compat[i][women+1]){
            ans=ans+solve(compat,i+1,womenSubset^(1<<women),men)%MOD;
        }
    }
    return dp[i][womenSubset]=ans;
}   

int main() {
	memset(dp,-1,sizeof(dp));
    ll n=0;cin>>n;
    vector<vector<int>> compat(n+1,vector<int>(n+1,0));
    for(int i=1;i<=n;++i)
        for(int j=1;j<=n;++j)
            cin>>compat[i][j];
    ll ans=solve(compat,1,(1<<n)-1,n)%MOD;
    cout<<ans<<'\n';
    return 0;
}

