ll memo[23][1 << 23];

ll dp(int i, int bit){
    if(i == -1 && bit == 0) return memo[0][bit] = 1;
    if(i == -1) return memo[0][bit] = 0;
    if(i + 1 < __builtin_popcount(bit)) return memo[i][bit] = 0;
    if(memo[i][bit] != -1) return memo[i][bit];

    ll res = 0;
    for(int j = 0; j < n; j++){
        if((bit & (1 << j)) == 0) continue;
        if(!a[i][j]) continue;
        int nbit = bit ^ (1 << j);
        res += dp(i - 1, nbit);
        res %= MOD;
    }

    return memo[i][bit] = res;

}

