int dp[1 << N];
int ar[N][N];
int n;

inline int add (int a, int b) { return ((a%MOD) + (b%MOD)) % MOD; };

void solve() {
   dp[0] = 0;

   for (int k = 0; k < n; ++k) {
      if (ar[1][k+1]) dp[1 << k] = 1;
   }

   for (int i = 2; i <= n; ++i) {
      for (int j = (1 << n)-1; j >= 1; --j) {
         if (__builtin_popcount(j) != i) continue;
         for (int k = 0; k < n; ++k) {
            if (ar[i][k+1] && (j & (1 << k))) dp[j] = add(dp[j], dp[j - (1 << k)]);
         }
      }
   }
   int total = dp[(1 << n)-1];
   cout << total << '\n';
}

