int mem[N][1 << N];

int go(int idx , int msk){
    if(idx == n)
        return 1;
    int &ret = mem[idx][msk];
    if(~ret)
        return ret;
    ret = 0;
    for(int i = 0; i < n; i++){
        if(msk & (1 << i))
            continue;
        if(yes[idx][i]){
            ret = (go(idx + 1 , msk ^ (1 << i)) + ret) % mod;
        }
    }
    return ret;
}

