using Mod = modulo<1'000'000'007>;

void solve(int N, vector<vector<int>> const &As) {
  int const nstates = 1 << N;
  vector<Mod> dp(nstates, 0);
  dp[0] = 1;
  REP(n, N) {
    std::bitset<32> S = (1 << n) - 1;
    do {
      REP(c, N) {
        auto const s = S.to_ullong();
        if (As[n][c] && !S[c]) { dp[s|(1<<c)] += dp[s]; }
      }
    } while (next_combination(N, n, S));
  }
  cout << dp[nstates-1].data() << endl;
}

