ll pop_count(ll bit){
    ll ret = 0;
    REP(i,N){
        if((bit >> i) & 1)
            ret++;
    }
    return ret;
}

void dfs(int v, ll bit){
    if(v == N){
        int num = pop_count(bit);
        B[num].push_back(bit);
        return;
    }
    dfs(v+1, bit);
    dfs(v+1, bit | (1LL << v));
}

