int n;
int memo[N][M];
bool isComp[N][N];
int solve(int i, int msk) {
    if (i == n)
        return 1;
    int &ret = memo[i][msk];
    if (~ret)
        return ret;
    ret = 0;
    for (int j = 0; j < n; ++j) {
        if (isComp[i][j] && !(msk & (1 << j))) {
            ret += solve(i + 1, msk | (1 << j));
            ret %= mod;
        }
    }
    return ret;
}


