{
	if (b == 0)
		return 1;

	cd res = fast_exp(a, b / 2);

	res = res * res;

	if (b % 2 == 1)
		res = res * a;

	return res;
}

long long fastexpon(long long a,long long b,long long mod)
{
	if(b==0)
		return 1;

	long long res=fastexpon(a,b/2,mod);

	res=(res*res)%mod;
	if(b%2==1)
		res= (res * a)%mod;

	return res;
}


