  }
  return mask;
}

inline size_t add(size_t res, size_t delta)
{ 
  return (res + delta) % 1000000007;
}

size_t solution(int i, size_t mask = 0)
{ 
  size_t res = 0; 
  for (int j = 0; j < N; ++j)
  { 
    if (v[i][j] && !(mask & (1<<j)))
    { 
      const size_t new_mask = mask | (1<<j);
      if (new_mask == MASK)
      { 
        res = add(res, 1);
        break;
      }
      if (dp[new_mask] == -1)
      { 
        dp[new_mask] = solution(i+1, new_mask);
      }
      res = add(res, dp[new_mask]);
    }
  }
  return res;
}


