int f(int i,vi v){
    int bitCnt=0;
    for(int i:v){while(i){bitCnt+=(i&1);i>>=1;}}
    if(bitCnt!=i)return 0;
    if(i==n)return 1;

    if(dp.find({i,v})!=dp.end())return dp[{i,v}];

    int ans=0;

    for(int x=0;x<n;x++){
        int yy=0;
        for(int j=0;j<i;j++)yy|=(v[j]&(1LL<<(n-1-x)));
        if(vv[i][x] && !(v[i]&(1LL<<(n-1-x))) && yy==0){
            v[i]^=(1LL<<(n-1-x));
            ans+=f(i+1,v);
            if(ans>=MOD)ans-=MOD;
            v[i]^=(1LL<<(n-1-x));
        }
    }

    return dp[{i,v}]=ans;
}

