long long dp_func(vector<vector<int>>&v, int i, int m, int &n)
{
	if(i==n)
	return 1;

	if(dp[m][i]!=-1)
	return dp[m][i];

	long long ans=0;
	for(int j=0;j<n;j++)
	{

		if(v[i][j]==1 && (m&(1<<j))==0 )
			ans = (ans + dp_func(v, i+1, m|(1<<j), n) ) % mod;

	}
	return dp[m][i] = ans;
}

