  for (ll i = (1ll<<n)-1; i >= 0; --i) {
    ll cnt = 0;
    rep(j, n) {
      if (i&(1ll<<j)) { ++cnt; }
    }
    if (cnt == n) { // fullfilled
      dp[i] = 1;
    } else {
      rep(k, n) {
        if (a[cnt][k] == 0) { continue; }
        if (!(i&(1ll<<k))) {
          ll post = i|(1ll<<k);
          dp[i] += dp[post];
        }
      }
    }
  }
  cout << dp[0] << endl;
}

