int solve(vector<vector <int> > &comp, int i , int womenSubs , int n )
{
    if(i == n+1)
	{	if(womenSubs == 0)
			return 1;
		else
			return 0;
	}
	if(dp[i][womenSubs] != -1)
		return dp[1][womenSubs];
	ll ans = 0;
	for(int w = 0; w < n; w++)
	{	bool avail = (((1<<w)&(womenSubs)) == 0) ? 0 : 1;
		if(avail && comp[i][w+1])
		{
			ans = (ans + solve(comp, i+1 , (womenSubs ^ (1<<w)), n)) % mod;
		}
	}
	return dp[i][womenSubs] = ans;
} 
