vector<vector<int> >dp;
int helper(vector<vector<int> >&pairs,int i,int ans,int n){
	if(dp[i][ans] > -1){
		return dp[i][ans];
	}
	//cout<<ans<<" "<<i<<" "<<endl;
	if(i == pairs.size()){
		if(__builtin_popcount(ans) == n){
		dp[i][ans] = 1;
		return 1;
	}
		else{
		dp[i][ans] = 0;
		return 0;
	}
	}
	else{
		int res = 0;
		for(int j=0;j<n;j++){
			if(pairs[i][j] == 1 && (ans&(1<<j)) == 0){
				ans = ans|(1<<j);
				res = (res%p + helper(pairs,i+1,ans,n)%p)%p;
				ans = ans & ~(1 << (j));	
			}
		}
		dp[i][ans] = res;
		return res;
	}
}
