  for (int S = 0; S < (1 << N); S++) {
    int i = popcount(S);

    for (int j = 0; j < N; j++) {
      if (!(S >> j & 1) && a[i][j] == 1) {
	int nextS = S | (1 << j);
	dp[nextS] += dp[S];
	dp[nextS] %= MOD;
      }
    }
  }

  cout << dp[(1 << N) - 1] << endl;

  return 0;
}

