inline int Solve(int x)
{
	if (x == 0) return 1;
	if (dp[x] != -1) return dp[x];
	int p = __builtin_popcount(x), r = 0;
	for (int y = x & g[p - 1]; y; y &= y - 1)
	{
		r += Solve(x & ~(y & -y));
		if (r >= MOD) r -= MOD;
	}
	return r;
}

