			REP(k, 0, N) {
				if (s & (1 << k)) ++cnt;
			}
			if (cnt != bits) continue;

			REP(k, 0, N) {
				if (!(s & (1 << k))) continue;
				if (!A[bits - 1][k]) continue;
				DP[s] += DP[s ^ (1 << k)];
			}
		}
	}

	cout << DP[(1 << N) - 1] << endl;
	return 0;
}

