    dp[0] = 1;
    for(int i = 0; i < (1 << n); i++){
        int cur_mask = mask[i].second;
        int man = mask[i].first;
        for(int woman = 0; woman < n; woman++){
            if(((cur_mask >> woman) & 1) || !a[man][woman])continue;
            int next_mask = cur_mask | (1 << woman);
            dp[next_mask] += dp[cur_mask]; 
            if(dp[next_mask] >= mod)dp[next_mask] -= mod; 
        }
    }
    cout << dp[(1 << n) - 1] << endl;
}

