vector<int> combination(int n,int k){
	vector<int> ans;
	int x = (1<<k)-1;
	int f = x<<(n-k);
	while(1){
		ans.push_back(x);
		if(x==f)return ans;
		x += x&-x;
		int pcount = bitset<32>(x).count();
		x|=(1<<(k-pcount))-1;
	}
}

