int solve(int id, int bit)
{
    if(dp[id][bit] != -1) return dp[id][bit];
    if(id == n) return 1;
    int ans = 0;
    for(int i = 0; i < n; i++){
        if(a[id][i] == 1 && !(bit & (1 << i))){
            ans += solve(id+1, bit|(1<<i) );
            ans %= mod;
        }
    }
    return dp[id][bit] = ans;

}

