const long long int MOD = 1e9+7;

int main(){

  // read problem
  long long int N, tmp;
  scanf("%lld", &N);

  std::vector<std::vector<long long int> > a(N);
  for(long long int i = 0; i < N; i++){
    for(long long int j = 0; j < N; j++){
      scanf("%lld", &tmp);
      a[i].push_back(tmp);
    }
  }

  // solve problem
  long long int n_S;
  std::vector<long long int> dp(1<<N);
  dp[0] = 1;
  std::vector<long long int> member_S;

  for(long long int S = 0; S < (1<<N); S++){
    // count number of members
    n_S = 0;
    for(long long int i = 0; i < N; i++){
      if((S & (1<<i)) != 0){
        n_S++;
      }
    }
    // calculate dp[S]
    for(long long int i = 0; i < N; i++){
      if((S & (1<<i)) != 0){
        dp[S] += a[n_S-1][i] * dp[S^(1<<i)];
        dp[S] = (dp[S]+MOD)%MOD;
      }
    }
  }

  std::cerr << "Answer:" << std::endl;
  std::cout << dp[(1<<N)-1] << std::endl;

  return 0;
}

