mint rec(int depth, int bit){
    if(depth == N) return 1;
    if(used[bit]) return dp[bit];
    //cout << " pre " << depth << " " << bit << endl;

    used[bit] = 1;
    for(int i = 0; i < N; i++){
        if((1 << i) & (~bit & FLAG[depth])){
            //cout << depth << " bit " << bit << " " << i << endl;
            dp[bit] += rec(depth + 1, bit | (1 << i));
        }
    }
    //cout << depth << " " << bit << " " << dp[bit] << endl;
    return dp[bit];
}

