				if (cnt == 1) dp[mask] += 1;

				else {
					dp[mask] += dp[mask - (1 << j)];
					if (dp[mask] >= MOD) dp[mask] %= MOD;
				}

			}
		}

		if (cnt == n) {
			ans += dp[mask];
			if (ans >= MOD) ans %= MOD;
		}
	}

	cout << ans;
	return 0;
}

