int64_t getPairsNum(const std::vector<std::vector<int>> &possibles) {
  const int n = static_cast<int>(possibles.size());
  std::vector<std::vector<int64_t>> dp(n);
  for (auto &row : dp) {
    row.resize(static_cast<int>(std::pow(2, n)), 0);
  }
  std::vector<std::bitset<21>> pre_bits(n);
  for (int i = 0; i < n; ++i) {
    pre_bits[i] = static_cast<unsigned long long>(1LL << i);
  }

  for (int j = 0; j < n; ++j) {
    if (possibles[0][j]) {
      dp[0][1LL << j] = 1;
    }
  }
  /*
  std::cout << "i=" << 0 << std::endl;
  for (int n = 0; n < static_cast<int>(dp[0].size()); ++n) {
    std::cout << std::bitset<21>(static_cast<unsigned long long>(n)) << ": " <<
  dp[0][n] << std::endl;
  }
    std::cout << std::endl;
    */
  for (int i = 1; i < n; ++i) {
    const auto &prev = dp[i - 1];
    auto &current = dp[i];
    for (int k = 0; k < static_cast<int>(prev.size()); ++k) {
      if (!prev[k]) continue;
      std::bitset<21> bits(static_cast<unsigned long long>(k));
      const auto count = prev[k];
      for (int j = 0; j < n; ++j) {
        //        std::cout << bits << ", " << pre_bits[j] << ", " << bits[j] <<
        //        "," << possibles[i][j] << std::endl;
        if (!bits[j] && possibles[i][j]) {
          current[(bits | pre_bits[j]).to_ulong()] += count;
        }
      }
    }
    for (auto &count : current) {
      count %= 1000000007LL;
    }
    /*
    std::cout << "i=" << i << std::endl;
    for (int n = 0; n < static_cast<int>(dp[i].size()); ++n) {
      std::cout << std::bitset<21>(static_cast<unsigned long long>(n)) << ": "
    << dp[i][n] << std::endl;
    }
    std::cout << std::endl;
    */
  }
  return dp.back().back();
}

