const int N = 22;
const int MOD = 1e9 + 7;
const int MASK = (1 << 21) + 5;

bitset <MASK> vis[N];
int n, a[N][N], f[N][MASK];

int call (int at, int mask) {
  if (at == n) return 1;
  if (vis[at][mask]) return f[at][mask];
  vis[at][mask] = 1;
  for (int i = 0; i < n; ++i) {
    if (mask & 1 << i) continue;
    if (!a[at][i]) continue;
    f[at][mask] += call(at + 1, mask | 1 << i);
    if (f[at][mask] >= MOD) f[at][mask] -= MOD;
  }
  return f[at][mask];
}

