int add(int& a, int b) {
    return (a + b) % mod;
}

int solve(int ind, int mask) {

    if(ind == n && mask == (1 << n)-1) {
        return 1;
    } else if(dp[ind][mask] != -1) {
        return dp[ind][mask];
    }

    int ans = 0;

    for(int i = 0; i < n; ++i) {
        if(can[ind][i] && !(mask & (1 << i))) {
            ans = add(ans, solve(ind+1, mask | (1 << i)));
        }
    }

    dp[ind][mask] = ans;
    return ans;
}

