const int N = 21, M = 1e9 + 7;


int dp[1 << N][N];
int mt[N][N];

list<int> pos[1 << N];


void smain()
{
    for (int i = 0; i < (1 << N); ++i)
        for (int j = 0; j < N; ++j)
            if ((i & (1 << j)) == 0)
                pos[i].push_back(j);

    int n;
    cin >> n;

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            cin >> mt[i][j];

    for (int i = 0; i < n; ++i)
        if (mt[0][i])
            dp[1 << i][0] = 1;

    for (int i = 1; i < n; ++i)
    {
        for (int j = 0; j < (1 << n); ++j) {
            dp[j][i] += dp[j][i - 1];

            if (dp[j][i] >= M)
                dp[j][i] -= M;

            for (int k : pos[j]) {
                if (mt[i][k] == 0)
                    continue;

                dp[j | (1 << k)][i] = (dp[j | (1 << k)][i] + dp[j][i - 1]);

                if (dp[j | (1 << k)][i] >= M)
                    dp[j | (1 << k)][i] -= M;
            }
        }
    }

    int ans = 0;
    for (int i = (1 << n) - 1; i < (1 << n); ++i)
        ans = (ans + dp[i][n - 1]) % M;

    cout << ans;
}

