size_t mod = 1e9 + 7;

int num_bits(int mask) {
    int res = 0;
    while (mask) {
        ++res;
        mask = (mask & (mask - 1));
    }
    return res;
}

int main() {
    int n; cin >> n;
    vector<vector<int>> m(n, vector<int>(n));
    for (int i = 0; i < n; ++i) for (int j = 0; j < n; ++j) cin >> m[i][j];
    vector<size_t> res(1 << n);
    for (int row = 0; row < n; ++row) {
        if (m[row][n - 1]) {
            res[1 << row] = 1;
        }
    }
    vector<vector<int>> masks(n + 1);
    for (int i = 0; i < (1 << n); ++i) {
        masks[num_bits(i)].push_back(i);
    }
    for (int col = n - 2; col >= 0; --col) {
        vector<size_t> new_res(1 << n);
        for (int row = 0; row < n; ++row) {
            if (m[row][col] == 0) continue;
            for (int mask : masks[n - 1 - col]) {
                if ((mask & (1 << row)) == 0) {
                    new_res[mask | (1 << row)] = (new_res[mask | (1 << row)] + res[mask]) % mod;
                }
            }
        }
        size_t wtf = 0;
        for (auto x : new_res) wtf += x;
        res.swap(new_res);
    }
    size_t ans = 0;
    for (auto x : res) ans = (ans + x) % mod;
    cout << ans << endl;
}

