	int &ret = dp[ind][mask];
	if(ret != -1) 
		return ret;

	ret = 0;
	for(int j = 0; j < 21; j++) {
		if(mat[ind][j] && ((mask >> j) & 1) == 0) {
			ret += f(ind - 1, mask | (1 << j));
			ret = mod(ret);
		}
	}

	return ret;
}

