const long long MOD = 1000000007;

void solve(long long N, std::vector<std::vector<int>> a) {
  vector<unordered_map<int, int64>> dp(N);
  for (auto i : a[0]) {
    dp[0][1 << i] = 1;
  }
  for (int i = 1; i < N; ++i) {
    for (auto [state, cnt] : dp[i - 1]) {
      for (auto j : a[i]) {
        int sj = 1 << j;
        if (state & sj) continue;
        dp[i][state | sj] += cnt;
        dp[i][state | sj] %= MOD;
      }
    }
  }
  int64 ans = 0;
  for (auto [state, cnt] : dp[N - 1]) {
    ans = (ans + cnt) % MOD;
  }
  cout << ans << endl;
}

