#define MOD 1000000007
using namespace std;

void f(int mask, vector<vector<int>> &compat, ll &count) {
    int k = __builtin_popcount(mask);   // no. of men already assigned
    // base case: all men assigned
    if (k >= compat.size()) {
        count = (count + 1) % MOD;
        return;
    }

    for (int j = 0; j < compat.size(); j++) {
        if (!(mask & (1 << j))) {
            if (compat[k][j]) {
                // if jth woman is compatible with kth man

                int newmask = (mask | (1 << j));
                f(newmask, compat, count);
            }
        }
    }
}

