int countSetBits(int n) 
{ 
    int count = 0; 
    while (n) 
	{ 
        count += n & 1; 
        n >>= 1; 
    } 
    return count; 
} 
void solve()
{
  	int n;
  	cin>>n;
  	// Since constraints are small, we can use Bitmasks
  	int match[n][n];
  	rep(i,0,n)
  	{
  		rep(j,0,n)
  		{
  			cin>>match[i][j];
  		}
  	}
  	int dp[(1<<n)]={0};
  	// MASK IS REPRESENTED BY WOMEN
  	dp[0]=1;// Match no one

	for(int mask=0;mask<(1<<n)-1;mask++)// Iterate over mask: every possible combination of women
	{
		// Number of bits set in mask==a
		int a=countSetBits(mask);
		for(int b=0;b<n;b++)// Checking bits
		{
			if(match[a][b]==1 && !(mask&(1<<b)))// Man a and Woman b can be matched, and in Mask, bth bit shouldn't be set
			{
				int m2=mask^(1<<b);// Change it to 1
				dp[m2]=(dp[m2]+dp[mask])%MOD;
			}

		}
	}
  	cout<<dp[(1<<n)-1];// 2^N-1 will have all bits in mask set to one, meaning that all women have been matched






}
