int solve(int idx, int msk) {
	if (idx == n) return msk == (1 << n) - 1;
	int& ret = dp[idx][msk];
	if (~ret) return ret;
	ret = 0;
	lop(i, n) {
		if (!can[idx][i] || (1<<i & msk)) continue;
		ret = (ret + solve(idx + 1, msk | (1 << i)) % MOD) % MOD;
	}
	return ret;
}

