int dfs(ll mask, int len) {
    if (mp.count(mask)) return mp[mask];
    ll row = mask >> n, col = mask & ((1 << n) - 1);
    int x = -1, y = -1;
    REP(i, n) if (row & (1 << i)) x = i;
    REP(j, n) if (col & (1 << j)) y = j;
    if (len == 1) {
        mp[mask] = a[x][y];
        return a[x][y];
    }
    row ^= 1 << x;
    int res = 0;
    REP(j, n) if ((col & (1 << j)) && a[x][j]) {
        ll m = (row << n) | (col ^ (1 << j));
        add(res, dfs(m, len - 1));
    }
    mp[mask] = res;
}

