ll DP[(int)(5*1e7)];
ll POW[23];

int rec(bitset<23> B, int cnt, int idx){
    if(cnt == N) return DP[idx] = 1;
    if(DP[idx] != 0) return DP[idx];

    ll res = 0;
    for(int i = 0; i < N; i++){
        if(A[cnt][i] == 1 && !B[i]) {
