int N;
int a[MAX][MAX];

long long memo[1 << MAX];

long long dfs( int i, int bit )
{
	if( i == N ) {
		return 1;
	}
	if( memo[bit] >= 0 ) {
		return memo[bit];
	}
	long long res = 0;
	for( int j = 0; j < N; j++ ) {
		if( a[i][j] && ( bit & (1 << j)) == 0 ) {
			res = ( res + dfs( i + 1, bit | (1 << j) ) ) % MOD;
		}
	}
	return memo[bit] = res;
}

