struct hash_pair { 
    template <class T1, class T2> 
    size_t operator()(const pair<T1, T2>& p) const
    { 
        auto hash1 = hash<T1>{}(p.first); 
        auto hash2 = hash<T2>{}(p.second); 
        return hash1 ^ hash2; 
    } 
};
unordered_map<pair<vector<bool>,int>,int,hash_pair>dp;
int helper(vector<vector<int> >&pairs,int i,vector<bool>&taken){
	if(dp.find(make_pair(taken,i)) != dp.end()){
		return dp[{taken,i}];
	}
	if(i == pairs.size())
	return 1;
	int ans = 0;
	for(int j=0;j<pairs[i].size();j++){
		if(pairs[i][j] == 1 && !taken[j]){
			taken[j] = true;
			ans = (ans%p + helper(pairs,i+1,taken)%p)%p;
		//	cout<<i<<" "<<ans<<" ";
			taken[j] = false;
		}
	}
	dp[{taken,i}] = ans;
	return ans;
}
