using namespace std;

int N;
size_t MASK;
vector<vector<int>> v;
vector<vector<int>> dp;

size_t get_mask()
{ 
  size_t mask = 0;
  for (int i = 0; i < N; ++i)
  { 
    mask |= (1 << i);
  }
  return mask;
}

inline size_t add(size_t res, size_t delta)
{ 
  return (res + delta) % 1000000007;
}

size_t solution(int i, size_t mask = 0)
{ 
  size_t res = 0; 
  for (int j = 0; j < N; ++j)
  { 
    if (v[i][j] && !(mask & (1<<j)))
    { 
      const size_t new_mask = mask | (1<<j);
      if (new_mask == MASK)
      { 
        res = add(res, 1);
        break;
      }
      if (dp[i+1][new_mask] == -1)
      { 
        dp[i+1][new_mask] = solution(i+1, new_mask);
      }
      res = add(res, dp[i+1][new_mask]);
    }
  }
  return res;
}

