int count_ways(vector<int> &v, int idx, int n, int mask, vector<int> &dp) {
    if (idx == n) return 1;
    if (dp[mask] != -1) return dp[mask];
    int total = 0, bit = 1;
    for (int i = 0; i < n; ++i) {
        if (!(bit & mask) && (bit & v[idx])) {
            total += count_ways(v, idx + 1, n, mask | bit, dp);
            total %= MOD;
        }
        bit <<= 1;
    }
    dp[mask] = total;
    return total;
}

