Mint solve(int p, int f) {
    if (p == n) return Mint(1);
    if (vis[p][f]) return dp[p][f];
    vis[p][f] = true;
    Mint sm = 0;
    for (int a = 0; a < n; a++) {
        if (f & (1<<a)) continue;
        if (!g[p][a]) continue;
        sm += solve(p + 1, f | (1<<a));
    }
    return dp[p][f] = sm;
}

