ll dp[1<<23];

ll f(const grid &g,int bit){
  if(dp[bit]!=-1LL) return dp[bit];
  dp[bit]=0LL;
  int cnt = __builtin_popcount(bit);
  for(int i = 0; i < 25;i++){
    if((bit&(1<<i))&&g[i][cnt-1]==1){
      int bitt=bit&(~(1<<i));
      dp[bit]+=f(g,bitt);
      dp[bit]%=mod;
    }
  }
  dp[bit]%=mod;
  return dp[bit];
}

