	dp[0] = 1;
	//マッチング済の女性の集合について全探索
	for (int S = 1; S < (1LL << N); S++) {
		//popcnt(n): Sの立っているbitの数、n-1人のマッチングが済んでいることを表すので次の男のindexはn-1
		int nextMan = _popcnt64(S);

		//n-1の男性とマッチングできる女性について全探索
		rep(i, N) {
			//今見てる集合でマッチング済となっており、n-1の男性とマッチングできるなら
			if ((BIT(i) | S) && a[nextMan - 1][i]) {
				//その女性がまだマッチングしていなかった場合の数を加算
				dp[S] += dp[S ^ BIT(i)];
			}
		}
	}

	cout << dp[(1 << N) - 1] << "\n";

	return 0;
}

