{
    cin>>n;
    F(ll, i, 0, n - 1){
        F(ll, j, 0, n - 1){
            cin>>arr[i][j];
        }
    }
    vector<vector<ll> > dp(n, vector<ll>(1 << n, -1));
    cout<<NumberOfways(0, 0, dp);
}

