using namespace std;

const ll mod = 1e9+7;
ll dp[22][(1<<22)];

int fun( vector< vector<ll>>& comp, ll N, ll i, ll woman_bit)
{
    //Base case
    if(i == N+1)
    {
        if(woman_bit == 0)
        return 1;
        return 0;
    }

    //Lookup
    if(dp[i][woman_bit] != -1)
    return dp[i][woman_bit];

    //Rec case
    ll ans = 0;
    for(ll w=0;w<N;w++)
    {
        bool is_avail = ( ((1<<w) & woman_bit) == 1) ? 1 : 0;

        if(is_avail && comp[i][w+1])
        {
            ans += fun( comp,N,i+1, (woman_bit ^ (1<<w)));
            ans %= mod;
        }
    }
    return dp[i][woman_bit] = ans;
}

