int dynamic(int bitmask, int pos, int count)
{
    if (pos == n)
    {
        if (count == n)
            return 1;
        else
            return 0;
    }
    if (dp[bitmask][pos] != -1)
        return dp[bitmask][pos];
    int ans = 0;
    for (int i = 0; i < n; i++)
