lli mod = 1000000007;
int n;


lli calc(int index, lli mask,vector<vector<lli> > &dp,vector<vector<int> > &arr)
{
    if(n == index)
    {
        if(mask == ((1<<n)-1))
            return 1;
        else
            return 0;
    }
    if(dp[index][mask] != -1)
        return dp[index][mask];
    lli ans = 0;
    for(int i=0;i<n;i++)
    {
        if(arr[index][i] == 1 && (mask&(1<<i))==0)
        {
            ans = (ans%mod + calc(index+1, (mask|(1<<i)),dp,arr)%mod)%mod;
        }
    }
    dp[index][mask] = ans;
    return ans;
}


