int32_t a[MAX_N + 5][MAX_N + 5], dp[MAX_N + 5][(1 << MAX_N) + 5];

int main() {
	std::ios_base::sync_with_stdio(false);
	std::cin.tie(nullptr);

    int32_t n;
    std::cin >> n;

    for(int32_t i = 0; i < n; i++) {
        for(int32_t j = 0; j < n; j++) {
			std::cin >> a[i][j];
		}
    }
	int32_t ans = 0;
	for(int32_t i = 0; i < n; i++) {
        if(a[0][i] == 1) {
			dp[0][(1 << i)] = 1;

			if(n == 1) {
				ans++;
			}
        }
	}

	if(n == 1) {
		std::cout << ans << '\n';
		return 0;
	}

    for(int32_t i = 1; i < n; i++) {
		for(int32_t j = 0; j < (1 << n); j++) {
			if(__builtin_popcount(j) != i + 1) {
				continue;
			}

			for(int32_t p = 0; p < n; p++) {
				if((j & (1 << p)) != 0 && a[i][p] == 1) {
					dp[i][j] = ((int64_t) dp[i][j] + dp[i - 1][(j ^ (1 << p))]) % MOD;
				}
			}

			if(i == n - 1) {
				ans = ((int64_t) ans + dp[i][j]) % MOD;
			}
		}
    }

    std::cout << ans << '\n';
}

