// 状態stateにおいて男k~男(N-1)でペアを組むときの組み方
ll q(int state, int k) {
    if (dp[state][k] != -1) return dp[state][k];
    if (k == N-1) {
        rep(j,N) {
            if (A[k][j] == 1 && !(state & (1<<j))) return 1; //全員がペアを組めた
        }
        return 0;
    }
    ll sum = 0;
    rep(j,N) {
        int res = state;
        if (A[k][j] == 1 && !(res & (1<<j))) {
            res |= (1<<j); //j番目にフラグを立てる
            sum += q(res, k+1);
        }
    }
    dp[state][k] = sum % mod;
    return dp[state][k];
}

