ModInt dfs(int i, int s) {
    if (i == n) return (s == (1<<n) - 1) ? 1 : 0;
    if (done[i][s]) return dp[i][s];
    for(int j = 0; j < n; j++) {
        if (a[i][j] == 0 || s & (1 << j)) continue;
        dp[i][s] += dfs(i + 1, s | (1 << j));
    }
    done[i][s] = true;
    return dp[i][s];
}

