void solve() {
	ll N;
  	scanf("%lld", &N);
	vector<vector<ll>> a(N,vector<ll>(N));
	rep(i, N) rep(j, N) scanf("%lld", &a[i][j]);

	vector<Modint> dp(1LL<<N,0);
	vector<bool> checked(1LL<<N,false);
	auto f=[&](auto&& f, ll bit)->Modint{
		ll index=__builtin_popcount(bit);
		if(index==N)return 1;
		if(checked[bit])return dp[bit];
		Modint t=0;
		rep(i,N){
			if(bit & 1LL<<i)continue;
			if(a[index][i]){
				ll x=bit|(1LL<<i);
				t+=f(f,x);
			}
		}
		checked[bit]=true;
		return dp[bit]=t;
	};

	Modint ans=f(f,0);

	printf("%lld\n", ans);
}

