int solve(int rowmask,int i)
{
      if(rowmask==done&&i==n)
      return 1;
      if(dp[i][rowmask]!=-1)
      return dp[i][rowmask];
      int safe = d[i]&(~rowmask);
      int ans = 0;
      while(safe)
      {
          int p = safe&(-safe);
          safe = safe-p;
          ans = (ans%mod+solve(rowmask|p,i+1)%mod)%mod;
      }
      return dp[i][rowmask] = ans;    
}
