//mask represents a subset of women,e.g:- 010010 represents that the 2nd and 5th women are paired.

//dp[i][mask] tells the total no. of possible pairings considering the first i men
//with a subset of size i of women represented by mask.

//Answer will be dp[n][(1<<n)-1] as we have to pair all n men with all n women.
int dp[N][1<<21]; 

int can[N][N]; //can[i][j] is 1 if ith man is permitted to pair up with the jth woman,otherwise 0.

void add_self(int &a,int b)
{
    a+=b;

    if(a>=mod)
    a-=mod;
}

int main()                  
{
    int n;

    scn(n);

    rep(i,0,n)
    {
        rep(j,0,n)
        scn(can[i][j]);
    }

    dp[0][0]=1; //1 way to match no men with no women

    for(int i=1;i<=n;i++)
    {
        for(int mask=0;mask<(1<<n);mask++)
        {
            int set_bits=__builtin_popcount(mask);

            //check if no. of women in this candidate subset 
            //is equal to i(i.e the no of men to match) or not.
            if(set_bits!=i) 
            continue;

            //ith men should be compatible to pair with jth women
            //and jth women should be a part of the current candidate subset
            //represented by mask.
            for(int j=0;j<n;j++)
            if(can[i-1][j] and mask&(1<<j))
            {
                int temp_mask=mask^(1<<j);

                add_self(dp[i][mask],dp[i-1][temp_mask]);
            }
        }
    }

    ll ans=dp[n][(1<<n)-1];

    printf("%lld ",ans);
}

