long long n, grid[mxN][mxN], dp[21][mxV];

long long recurse(int i, int mask)
{
    if (i < 0)
        return 1;
    if (dp[i][mask] != -1)
        return dp[i][mask];

    long long ways = 0;
    for (int j = 0; j < n; j++)
    {
        if (grid[i][j] == 1 && ((mask & (1 << j)) > 0))
        {
            int tmp = mask ^ (1 << j);
            ways += recurse(i - 1, tmp);
            ways %= MOD;
        }
    }
    dp[i][mask] = ways;
    return ways;
}

