int main() {
  // O: looks like just a n^2*2^n bitmask DP
  // n*2^n states: dp[i][ii] = processed the first i men,
  // ii is bitmask of women left unpaired
  // n transitions

  cin.tie(0);
  cin.sync_with_stdio(0);
  int n; cin >> n;
  vector<vector<int> > adj(n);
  for(int i = 0; i<n; ++i) {
    for(int j = 0; j<n; ++j) {
      int is_pair; cin >> is_pair;
      if(is_pair == 1) {
        adj[i].push_back(j);
      }
    }
  }

  long long MOD = 1e9+7;
  vector<vector<long long> > dp(n+1, vector<long long>(1<<n));
  for(int i = 0; i<=n; ++i) {
    for(int j = 0; j<(1<<n); ++j) {
      dp[i][j] = 0;
    }
  }
  dp[0][0] = 1;
  for(int i = 0; i<n; ++i) {
    for(int j = 0; j<(1<<n); ++j) {
      if(dp[i][j] == -1) continue;
      for(int l = 0; l<adj[i].size(); ++l) {
        // for all possible pairings for i...
        int k = adj[i][l];
        if((j >> k) & 1) {
          // make sure they're not already taken
          continue;
        }
        dp[i+1][j+(1<<k)] = (dp[i+1][j+(1<<k)] + dp[i][j]) % MOD;
      }
    }
  }
  cout << dp[n][(1<<n) - 1] << endl;
}

