int dfs(int index, int state) {
	if (index == n) return 1;
	int& ret = dp[index][state];
	if (ret != -1) return ret;
	ret = 0;
	for (int i = 0; i < n; i++) {
		if (f[index][i] == 1 && !(state & (1 << i))) {
			ret += dfs(index + 1, state | (1 << i));
			ret %= MOD;
		}
	}
	return ret;
}

