typedef long long ll;
const int MAXN = 21;
const int MOD = 1000000000 + 7;
int N;
int memo[MAXN][1<<MAXN];
int can[MAXN];
vector<int> bit_on[1<<MAXN];

int dp(int u, int bm) {
    if(u == N) return 1;
    int& ans = memo[u][bm];
    if(ans == -1) {
        ans = 0;
        int cpbm = bm & can[u];
        for(const int& x : bit_on[cpbm]) {
            ans = (ans + dp(1 + u, bm & ~(1 << x)));
            if(ans >= MOD) ans -= MOD;
        }
    }
    return ans;
