   // cout<<n<<" "<<m<<endl;

   if(n == N) return m == lim;
   if (dp[n][m] == 0) return dp[n][m];

   for(int i=0;i<N;i++) {
      // cout<<ar[n][i]<<endl;
      if (ar[n][i] && !((1 << i)&m)) {
         // cout<<n<<" "<<i<<endl;
         dp[n][m] += sol(n+1,m | (1 << i));
      }
   }
   dp[n][m] %= MOD;
   return dp[n][m];
}

