const int MOD = 1000000000 + 7;

int N;
int v[21][21];
int dp[21][1 << 21 + 5];

int solve(const int i, const int j)
{
    if (dp[i][j] != -1)
    {
        return dp[i][j];
    }

    if (i == N)
    {
        return dp[i][j] = 1;
    }

    int ans = 0;
    for (int k = 0; k < N; k += 1)
    {
        if (not v[i][k] or not(j & (1 << k)))
        {
            continue;
        }
        ans = (ans + solve(i + 1, j ^ (1 << k))) % MOD;
    }
    return dp[i][j] = ans;
}

