        arr2d<modint> dp(N, 1 << N, -1);
        RecursiveFunction rec = [&] (auto const& self, int m, int w) -> modint {
            if (m == N) {
                if (w == 0)
                    return 1;
                return 0;
            }
            if (dp(m, w) != -1) {
                return dp(m, w);
            }
            modint tot = 0;
            for (int i = 0; i < N; i++) {
                int woman = 1 << i;
                bool available = ((woman & w) != 0);
                if (available && a(m, i) == 1)
                    tot += self(m + 1, w ^ woman);
            }
            return dp(m, w) = tot;
        };
        out.printLine(rec(0, (1 << N) - 1));
    }
};


