mint dfs(int used) {
  int idx = __builtin_popcount(used);
  if (idx == N)
    return 1;
  if (visited[used])
    return dp[used];

  mint ans = 0;
  rep(j, N) {
    if (used & (1 << j))
      continue;
    if (A[idx][j]) {
      ans += dfs(used + (1 << j));
    }
  }
  visited[used] = true;
  return dp[used] = ans;
}

