using namespace std;

map<pair<int, int>, ll> memo;
typedef std::vector<std::vector<int>> graph;

bool match[21][21] = {};

ll rec(int m, int w)
{
  if (m == 0 && w == 0)
    return 1;
  auto p = make_pair(m, w);
  if (memo.find(p) != memo.end())
    return memo[p];

  int tmpM = m;
  int tmpW = w;
  int loop = 0;
  ll count = 0;
  while (tmpM != 0)
  {
    if ((tmpM & 1) == 1)
    {
      int innerLoop = 0;
      while (tmpW != 0)
      {
        if ((tmpW & 1) == 1)
        {
          if (match[loop][innerLoop])
          {
            int man = (m & (~(1 << loop)));
            int woman = (w & (~(1 << innerLoop)));
            count = (count + rec(man, woman)) % MOD;
          }
        }
        tmpW >>= 1;
        innerLoop++;
      }
    }
    tmpM >>= 1;
    loop++;
  }
  memo[p] = count;
  return memo[p];
}

