  if (k > n - i) return 0;
  if (k == 0) {
    return calculate(init_k, mask);
  } else {
    return (build_mask(n, init_k, mask, i + 1, k) +
            build_mask(n, init_k, mask | (1 << i), i + 1, k - 1)) %
           M;
  }
}

