using namespace std;

#define MAXN 21
long long MM =(1e9+7);


int A[MAXN+1][MAXN+1];


int number_1_bit(int set) {
  int count = 0;
  while (set != 0) {
    count += (set & 1);
    set = set >> 1;
  }

  return count;
}

int main() {
  // task O
  assert( (1 << 1) == 2);

  assert( number_1_bit(7) == 3 );
  assert( number_1_bit(8) == 1 );
  assert( number_1_bit(0) == 0 );
  assert( number_1_bit(0b101010100) == 4 );
  assert( number_1_bit(0b001010100) == 3 );

  int N;
  cin >> N;
  assert(N > 0 && N <= 21);
  // count from 0 -> N-1
  for(auto i=0;i<N; i++) {
    for(auto j=0;j<N; j++) cin >> A[i][j];
  }

  vector<int> F( (1<<N) + 1, 0);

  F[0] = 1; // there is a way to match two empty sets

  for (int subset = 1; subset < (1 << N); subset++) {
    auto size = number_1_bit(subset);
    // matching subset (women) with the set {0 .. |subset|-1} (men)

    for (auto i=0; i<N; i++) { // consider matching (size-1)-th man <-> i-th bit woman
      if(  subset & (1<<i) ) { // in the subset
        if ( A[size-1][ i ] == 1) {  // a match, consider a sub problem, disable i-th bit
          auto sub = subset - (1<<i);
          F[subset] = (F[subset] + F[sub]) % MM;
        }
      }
    }
  }

  cout << F[ (1<<N) - 1] << endl;
  return 0;
}

