void solve(int N, vector<vector<int>> const &As) {
  int const nstates = 1 << N;
  vector<Mod> dp(nstates, 0);
  dp[0] = 1;
  REP(n, N) {
    vector<int> v(N, 0); REP(i, n) { v[N-1-i] = 1; }
    do {
      int S = 0;
      REP(i, N) { S <<= 1; S += v[N-1-i]; }
      REP(c, N) {
        if (As[n][c] && !v[c]) {
          dp[S|(1<<c)] += dp[S];
        }
      }
    } while (next_permutation(begin(v), end(v)));
  }
  cout << dp[nstates-1].data() << endl;
}

