ll mod_pow(ll a, ll b)
{
	if (b == 0)
		return 1LL;

	ll res = mod_pow(a, b >> 1);
	res = (res * res) % mod;
	if (b & 1LL)
		res = (res * a) % mod;

	return res;
}

const int N = 21 + 5;
const int SZ = 2100000;

int n;
int a[N][N];
int dp[SZ];

int solve(int mask)
{
	if (mask == (1 << n) - 1)
		return 1;

	int idx = 1;
	for (int i = 1; i <= mask; i *= 2)
		if (mask & i)
			idx++;

	int &memo = dp[mask];
	if (memo != -1)
		return memo;

	memo = 0;
	for (int i = 1; i <= n; i++)
	{
		int temp = 1 << (i - 1);
		// cerr << "temp : " << bitset<32>(temp) << " mask : " << mask << "\n";
		if (a[idx][i] == 1 && (mask & temp) == 0)
		{
			// cerr << "entry\n";
			mask ^= temp;
			memo += solve(mask);
			memo %= mod;
			mask ^= temp;
		}
	}
	// cerr << "idx : " << idx << " memo : " << memo << "\n";
	return memo;
}

