        for(int j = 0; j < (1 << n); j++){
            if(pop_count(j) != i) continue;
            for(int k = 0; k < n; k++){
                int mask = 1 << k;
                if((j & mask) || a[k] == 0) continue;
                dp[j | mask] += dp[j];
                dp[j | mask] %= MOD;
            }
        }
    }
    cout << dp[(1 << n) - 1] << endl;
    return 0;
}

