bool check(const int i,const int mask){
    int n_mask = 1<<i;
    n_mask = n_mask&mask;
    if(n_mask>0){
        return 1;
    }
    return 0;
}

void seti(const int i,int &mask){
    int n_mask = 1<<i;
    mask = n_mask^mask;
}

ll func(int i,int mask){
    if(i==n){
        return 1LL;
    } 
    if (dp[i][mask]==0){
        ll ans = 0;
        for(int j = 0; j < n; j++){
            if(arr[i][j]==1 && check(j,mask)){
                seti(j,mask);
                ans= (ans + func(i+1,mask))%mod;
                seti(j,mask);
            }
        }
        dp[i][mask] = ans;
        return ans;
    }
    else{
        return dp[i][mask];
    }

}

