    int dp[1<<n+1];
    memset(dp, 0, sizeof(dp));
    dp[0]=1;
    for(int mask=0;mask<=(1<<n)-1;mask++){
        int y = countsetbits(mask);
        for(int i=0;i<n;i++){
            if((mask&(1<<i)) == 0 && like[y][i]){
                dp[mask|(1<<i)] += dp[mask];
            }
        }
    }
    cout << dp[(1<<n)-1];
}

