ll modpow(ll x, ll n, const ll &p)
{
	ll ret = 1;
	while (n > 0)
	{
		if (n & 1)
		{
			(ret *= x) %= p;
		}
		(x *= x) %= p;
		n >>= 1;
	}
	return ret;
}
template <class T>
T modinv(T a, const T &p)
{
	T b = p, u = 1, v = 0;
	while (b)
	{
		T t = a / b;
		a -= t * b;
		swap(a, b);
		u -= t * v;
		swap(u, v);
	}
	u %= p;
	if (u < 0)
	{
		u += p;
	}
	return u;
}
template <class T>
T math_P(T m, T n)
{
	T ret = 1;
	for (T i = m; i > m - n; i--)
	{
		ret *= i;
	}
	return ret;
}
template <class T>
T math_C(T m, T n)
{
	T ret = math_P(m, n);
	for (T i = 2; i <= n; i++)
	{
		ret /= i;
	}
	return ret;
}
ll extended_euclidean(ll u, ll v)
{
	ll r0 = u;
	ll r1 = v;
	ll s0 = 1;
	ll s1 = 0;
	ll t0 = 0;
	ll t1 = 1;
	while (r1 != 0)
	{
		ll q = r0 / r1;
		ll r = r0 - q * r1;
		ll s = s0 - q * s1;
		ll t = t0 - q * t1;
		r0 = r1;
		s0 = s1;
		t0 = t1;
		r1 = r;
		s1 = s;
		t1 = t;
	}
	if (t0 < 0)
	{
		return t0 + u;
	}
	else
	{
		return t0;
	}
}
ll math_C_mod(ll n, ll c, const ll &p)
{
	ll upe = 1;
	ll dow = 1;
	for (ll i = 1; i < c + 1; ++i)
	{
		upe = upe * n % p;
		dow = dow * i % p;
		n -= 1;
	}
	return (upe * extended_euclidean(p, dow)) % p;
}
template <class T>
T math_gcd(T a, T b)
{
	if (b == 0)
	{
		return a;
	}
	else
	{
		return math_gcd(b, a % b);
	}
}
template <class T>
T math_lcm(T a, T b) { return a / math_gcd(a, b) * b; }
