ll dp[1 << 21];//dp[i][j]: i番目(1-idx 0は初期条件で計算上の便宜)の男のマッチングまでして、女がjのようなbitの余り方をしてる
//bitが立ってると、マッチング済、そうでなければ使用可能

int main() {
	cin >> N;
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < N; j++) {
			cin >> kankei[i][j];
		}
	}
	dp[0] = 1;

	for (int i = 1; i < (1 << N); i++) {
		int bitcnt = 0;
		for (int j = 0; j < N; j++)if (i & (1 << j))bitcnt++;
		for (int j = 0; j < N; j++) {
