ll f(ll i, ll X, ll n){
    if(i > n){
        if(X == 0) return 1;
        return 0;
    }

    if(dp[i][X] != -1) return dp[i][X] % mod;

    ll ans = 0;
    for(ll z=0;z<n;z++){
        bool avail = (X & (1 << z)) != 0;

        if(avail and a[i][z+1] == 1){
            // setting that bit to 0
            ans = (ans + f(i+1, X ^ (1 << z), n) % mod) % mod;
        }
    }

    return dp[i][X] = ans % mod;
}

