int cal(int pos,int mask)
{

  if(mask+1==(1<<n))
    return 1;
  if(pos==n)
    return 0;
  if(dp[pos][mask]!=0)
    return dp[pos][mask];
  int ways=0;
  for(int i=0;i<n;i++)
