    if(a[pos][i]==1&&(mask&1<<i)==0)
    {
      ways+=(cal(pos+1,mask|1<<i)%1000000007);
      ways%=1000000007;
    }  
  }
  dp[pos][mask]=ways;
  return dp[pos][mask];
}
