int rec(int m, int w) {
	if (m == N) {
		if (w == 0) {
			return 1;
		}
		return 0;
	}
	if (dp[m][w] != -1) {
		return dp[m][w];
	}
	ll tot = 0;
	for (int i = 0; i < N; i++) {
		int woman = 1 << i;
		bool okay = ((w & woman) == 0)? false : true;
		if (okay && a[m][i]) {
			tot = (tot + rec(m + 1, w ^ woman)) % mod;
		}
	}
	return dp[m][w] = tot;
}

