int64_t solve(vector<vector<int>>& compatible,int index_men, int64_t women_subset,int n)
{
 if(index_men == n)
 {
   if(women_subset == 0)
    return 1;
   else
    return 0;
 }

 if(dp[index_men][women_subset] !=-1)
   return dp[index_men][women_subset];

 int64_t ans=0;
 int i=0;
 int64_t  temp = women_subset;

 while(temp)
 {
  if( (temp && (1<<i)) && compatible[index_men][i])
  ans =(ans + solve(compatible,index_men+1,women_subset^(1<<i),n))%MOD;
  temp>>=1;
  i++;
 }
 return dp[index_men][women_subset] = ans;
}

