int solve(int idx, int mask)
{
	if (idx > n)
		return 1;

	int &memo = dp[idx][mask];
	if (memo != -1)
		return memo;

	memo = 0;
	for (int i = 1; i <= n; i++)
	{
		int temp = 1 << (i - 1);
		// cerr << "temp : " << bitset<32>(temp) << " mask : " << mask << "\n";
		if (a[idx][i] == 1 && (mask & temp) == 0)
		{
