                if (A[i][j] && !(s & (1LL << j))) {
                    dp[s | (1L << j)] += dp[s];
                    dp[s | (1L << j)] %= MOD;
                }
            }
        }
    }
    cout << dp[(1 << N) - 1] % MOD << '\n';
}

