int calc(int idx ,int mask){

	if(idx == n){

		if(mask != complete)
			return 0;

		return 1;

	}


	if(dp[idx][mask] != -1)
		return dp[idx][mask];

	int ways = 0;
	for(int i =0 ; i < n ; i++){
		int val =1<<i;
