ll ans = 0; 
int n;
vi poss[21];

void recur(int index) {

	// cout<<index<<' '<<part.size()<<'\n';

	if(part.size() == n) {
		ans++;
		if(ans > MOD) 
			ans -= MOD;
		return;
	}

	if(index >= n)
		return;


	cfi(poss[index], it) {
		if(part.count(*it))
			continue;

		part.insert(*it);
		recur(index + 1);
		part.erase(part.find(*it));
	}

}

