vector<optional<m64>> dp;

m64 dfs(i64 depth, i64 used) {
    if (depth == n) return used == (1 << n) - 1;
    if (dp[used]) return *dp[used];

    m64 res = 0;
    for (i64 i = 0; i < n; i++) {
        if ((used >> i) & 1) continue;
        if (!a[depth][i]) continue;
        res += dfs(depth + 1, used | (1 << i));
    }
    return dp[used].emplace(res);
}

