int compute(bitset<21> bt,int id,int val){ 
	if(dp[val][id]!=-1){ 
		return dp[val][id]; 
	} 

	if(id==n-1){ 
		for(int i=0;i<n;i++){ 
			if(!bt.test(i) and a[i][id]==1){
				return dp[val][id]=1;
			} 
		}
