		if(!bt.test(i) and a[i][id]==1){ 
			bt.set(i);
			val+=1<<i;
			s=add(s,compute(bt,id+1,val));
			bt.reset(i); 
			val-=1<<i; 
		}
	}
	return dp[val][id]=s; 
}



