vector<vector<int> > can;

int calc(int at, int mask) {
	if (at == n)
		return mask == (1 << n) - 1;
	int &res = dp[at][mask];
	if (res != -1)
		return res;
	res = 0;
	for (int w : can[at])
		if (((mask >> w) & 1) == 0)
			res = (res + calc(at + 1, mask | (1 << w))) % M;
	return res;
}

