	dp[0][0] = 1;
	function<int(int, int)> solve = [&](int boys, int girls) {
		if (dp[boys][girls] != -1) {
			return dp[boys][girls];
		}
		int res = 0;
		for (int girl = 0; girl < n; girl++) if (girls & (1 << girl)) if (a[boys - 1][girl]) {
			res = add(res, solve(boys - 1, girls ^ (1 << girl)), MOD);
		}
		return dp[boys][girls] = res;
	};
	cout << solve(n, (1 << n) - 1) << "\n";
}

