inline int add(int a, int b, int mod = mod) {
  a += b;
  if(a >= mod) a -= mod;
  if(a < 0) a += mod;
  return a;
}

int rec(int cur, int mask) {
  if(cur == n) return 1;
  int& cm = dp[cur][mask];
  if(cm != -1) return cm;
  cm = 0;
  for(int i = 0; i < n; ++i) {
    if(arr[cur][i] && !(mask & (1 << i))) {
      cm = add(cm, rec(cur + 1, mask ^ (1 << i)));
    }
  }
  return cm;
}

