	dp[0][0] = 1;

	int N; cin >> N;
	for (size_t i = 1; i <= N; i++) {
		ull mask = 0;
		for (size_t j = 0; j < N; j++) {
			ull val; cin >> val;
			mask |= val << j;
		}
		inp[i] = mask;
	}

	ull MASK = 1 << N;
	for (size_t i = 1; i <= N; i++) {
		for (size_t mask = 0; mask < MASK; mask++) {
