				for (size_t bit = 0; bit <= N; bit++) {
					if ((1 << bit) & inp[i] && !((1 << bit) & mask)) {
						dp[i][(1 << bit) | mask] = (dp[i][(1 << bit) | mask] + dp[i - 1][mask]) % MOD;
					}
				}
			}
		}
	}
	cout << dp[N][(1 << N) - 1] << endl;
