    for (int mask = 1; mask < 1 << n; ++mask) {
        int i = __builtin_popcount(mask) - 1;
        for (int j = 0; j < n; ++j)
            if (((mask >> j) & 1) && compat[i][j] == '1')
                dp[mask] += dp[mask ^ (1 << j)];
    }
