                msk= (msk| 1<< idx);
        };

        auto clearbit= [=](int idx, int &msk) {
                msk= msk & ~(1 << idx);
        };

        function<int(int, int)> calc= [&](int idx, int msk)->int{
                if (idx== n) {
                        if (msk!= val) return 0;
                        else return 1;
                }

                int &ret= dp[idx][msk];
                if (ret!= -1) return ret;
                ret= 0;

                for (int j= 0; j< n; j++) {
                        if (v[idx][j]&& ((msk&(1<< j))== 0)) {
                                setbit(j, msk);
                                ret= (ret+ calc(idx+ 1, msk))% mod;
                                clearbit(j, msk);
                        }
                }

                return ret% mod;
        };
        cout << calc(0, 0)% mod;
}

