	for(int b = 0; b < max_bitmask; b++) {
		int hombre = __builtin_popcount(b);
		for (int mujer = 0; mujer < n; mujer ++) {
			if (match[hombre][mujer] && available(b, mujer)) {
				dp[b ^ (1<<mujer)] += dp[b]; dp[b ^ (1<<mujer)] %= mod;
			}
		}
	}
	cout << dp[max_bitmask - 1] << "\n";
	return 0;
}

