int dd(int x) {
	if (x == 0) return 1;
	if (dp[x]>=0) return dp[x];
	vector<int> v;
	int rt = 0;
	int tmp = x;
	int m = 0;
	int cnt = 0;
	while (tmp > 0) {
		if (tmp % 2) {
			m += tmp % 2;
			v.push_back(cnt);
		}
		cnt++;
		tmp /= 2;
	}
	while (!v.empty()) {
		int cur = v.back();
		v.pop_back();
		if (arr[m][cur + 1]) {
			if (dp[x - idx[cur]]<0) rt = (rt + dd(x - idx[cur])) % INF; 
			else rt = (rt + dp[x - idx[cur]]) % INF;
		}
	}
	dp[x] = rt;
	return rt;
}

