	const int MOD = 1000000007;
	int n, r;
	char p;
	cin >> n;
	int upbound = (1 << n);
	g = vector<int>(n);
	for (int i = 0; i < n; ++i)
		for (int j = 0; j < n; ++j) {
			cin >> p;
			if (p == '1')
				g[i] |= (1 << j);
		}
	Q.emplace(upbound - 1);
	while (!Q.empty())
	{
		auto x = Q.front();
		Q.pop();
		if (!x) continue;
		todo.emplace_back(x);
		p = __builtin_popcount(x);
		for (int y = x & g[p - 1]; y; y &= y - 1)
			Q.emplace(x & ~(y & -y));
	}
	sort(todo.begin(), todo.end());
	auto last = unique(todo.begin(), todo.end());
	todo.erase(last, todo.end());
	dp[0] = 1;
	for (auto x : todo) {
		p = __builtin_popcount(x), r = 0;
		for (int y = x & g[p - 1]; y; y &= y - 1)
		{
			r += dp[x & ~(y & -y)];
			if (r >= MOD) r -= MOD;
		}
		dp[x] = r;
	}
	cout << dp[upbound - 1];
}

