ll dfs(int rest, int line) {
    if (done[rest]) {
        // cout << "memo" << endl;
        return dp[rest];
    }
    if (line == n - 1) {
        for (int j = 0; j < n; j++) 
            if (a[line][j] == 1 && rest & 1<<j) return 1;
            return 0;
    }
    done[rest] = true;
    ll res = 0;
    for (int i = 0; i < n; i++) {
        if (rest & 1<<i && a[line][i] == 1) {
            rest ^= 1<<i;
            res += dfs(rest, line+1);
            res %= MOD;
            rest ^= 1<<i;
        }
    }
    // cout << res << endl;
    return dp[rest] = res;
}

