int go(int mask) {
	if (mask == 0) return 1;
	int &res = dp[mask];
	if (res != -1) return res;
	int qwe = n - __builtin_popcount(mask);
	int asd = mask & musk[qwe];
	res = 0;
	while (asd > 0) {
		int bit = bt[asd & -asd];
		res = add(res, go(mask ^ (1 << bit)));
		asd -= (1 << bit);
	}
	return res;
}

