int128_t dp[1 << MAX_N] = {};

int128_t calc(std::bitset<MAX_N> bit) {
    if (bit.count() == N) {
        return 1;
    }
    if (dp[bit.to_ulong()] != -1) {
        return dp[bit.to_ulong()];
    }

    int128_t ret = 0;
    rep (i, 0, N - 1) {
        if (!bit.test(i) && a[bit.count()][i] == 1) {
            std::bitset<MAX_N> next = bit;
            next.set(i);
            ret += calc(next);
        }
    }
    ret %= MOD;
    dp[bit.to_ulong()] = ret;
    return ret;
}

