ll m = 1000000007;
ll f(ll s,ll n){
  ll j = __builtin_popcount(s);
  if(s == (1<<n)-1){return 1;}
  if(dp[s]!=-1){return dp[s];}
//   cout<<j<<"\n";
  ll ans = 0;
  rep(i,0,n-1){
      if( (s & 1<<i)==0 && arr[i][j]==1){
          ans = (ans + f((s | 1<<i),n)%m)%m;
      }
  }
  dp[s] = ans;
  return ans;
}

