int n;
ll ds(int id, int s) {
	if(id == n) {return 1;}
	if(dp[s] != -1) {return dp[s];}
	ll re = 0;
	for(int i=0;i<n;i++) {
		if(cp[id][i] && !(s & (1<<i))) {
			re += ds(id+1,s|(1<<i));
		}
	}
	return dp[s] = re%MD;
}
