long long int nn;
long long int mod = 1000000007;
long long int f(int l, int wbit, vector<vector<long long int>>& dp, vector<vector<long long int>>& a){
	int ind = nn-l;
	if(ind==nn)return 1;
	// cout<<"l wbit "<<l<<" "<<wbit<<endl;
	if(dp[l][wbit]!=-1){return dp[l][wbit]%mod;}
	long long int x = 0;

	for(int j=0;j<nn;j++){
		if(a[ind][j]){
			if(wbit & (1<<j)){
				// cout<<"j "<<j<<endl;
				x += (f(l-1, wbit-pow(2,j), dp, a))%mod;
				x = x%mod;
			}
		}
	}

	dp[l][wbit] = x%mod;
	return x;
}
