int go(int ind, int mask){
  if(ind >= n) return 1;
  int &x = dp[ind][mask];
  if(x!=-1)return x;
  int ans = 0;
  for(int i = 0; i < n; i++){
    if(mask&(1ll<<i)){
      if(Data[ind]&(1ll<<i)){
        ans += go(ind+1, mask^(1ll<<i));
        ans%=mod;
      }
    }
  }
  return (x = ans);
}

