ll ways(vector<vector<ll>>&v,string state,ll i){
	if(i==v.size())
		return 1;
	if(dp.find(state)==dp.end()){
		ll ans=0;
		for(ll j=0;j<state.length();j++){
			if(state[j]=='1'){
				state[j]='0';
				if(v[i][j])
					ans=(ans+ways(v,state,i+1))%M;
				state[j]='1';			
			}
		}	
		dp[state]= ans;
	}
	return dp[state];
}

