int bitcount(int v, int n) {
  int cnt = 0;
  rep(i, n) {
    cnt += bool(v & (1 << i));
  }
  return cnt;
}

long long mod(long long v, long long M) {
  if (v >= M) {
    return v % M;
  }
  return v;
}

