    a[i] = tmp;
  }

  long long ok = (1 << n) - 1;
  long long dp[1 << n];
  long long M = 1'000'000'000 + 7;

  rrep(state, (1 << n) - 1) {
    if (state == ok) {
      dp[state] = 1;
      continue;
    }

    long long cnt = 0;
    int i = bitcount(state, n);
    rep(index, n) {
      int p = 1 << index;
      if (a[i][index] && !(state & p)) {
        cnt = mod(cnt + dp[state + p], M);
      }
    }
    dp[state] = mod(cnt, M);
  }

  out(dp[0]);
}

