	dp[0][0]=1;

	for(int i=1;i<n+1;i++)
	{
		for(int j=0;j<(1<<n);j++)
		{
			if(dp[i-1][j]>0)
			{
				bool female[21];
				//int cnt=0;
				fill(female,female+21,false);
				for(int bit=0;bit<n;bit++)
				{
					int t=((1<<bit)&j);
					if(t>0)
					{
						female[bit]=true;
						//cnt++;
					}
				}
				dp[i][j]+=dp[i-1][j];
				dp[i][j]%=MOD;
				for(int k=0;k<n;k++)
				{
					if(female[k] || a[i-1][k]==0)
						continue;
					int t=j+(1<<k);
					dp[i][t]+=dp[i-1][j];
					dp[i][t]%=MOD;
				}
			}
		}
	}


	ans=dp[n][(1<<n)-1];
	ans%=MOD;
	if(ans<0)
		ans+=MOD;
	cout<<ans<<endl;
	return 0;
}

