#include <stdio.h>
#include <stdlib.h>
#include <bits/stdc++.h>
using namespace std;
typedef long long int lli;
int getbit(vector<int> &A, int i, int j){
	return A[i]&(1<<j);
}
void setbit(vector<int> &A, int i, int j){
	A[i] = A[i]|(1<<j);
	return;
}
void unset(int & N, int i){
	N = N&(~(1<<i));
}
pair<int,int> dfs(int i, int N, vector<int> &A, int &Men, vector<vector<lli> > &M){
	pair<int, int> p;
	if(i==N) { p.first=1; p.second=1;return p;}
	if(Men==0) {p.first=0; p.second=0; return p;}
	pair<int, int> temp, c;
	p.second = 0;
	c.first = i;
	c.second = Men;
	if(M[i][Men]!=-1)
	{p.first = M[i][Men]; p.second = 1; return p;}

	for (int k = 0; k <N ; ++k)
	{
		if(getbit(A, i, k) and (Men & (1<<k)))
		{
			Men = Men&(~(1<<k));
			temp = dfs(i+1, N, A, Men, M);
			if(temp.second)
				{	p.first += temp.first; p.first%=1000000007; p.second = 1;}
			Men = Men|(1<<k);
		}
	}
	M[i][Men] = p.first%1000000007;
	return p;
}

int main(int argc, char const *argv[])
{
