    		if(x)
    			setbit(A, i, j);
    	}
    }
    int Men = INT_MAX;
    for (int i = N; i <32 ; ++i)
    {
    	unset(Men, i);
    }
    vector<vector<lli> > M(N, vector<lli> ((1<<21), -1));
    cout<<dfs(0, N, A, Men, M).first;
    return 0;
}

