int const mod = 1e9 + 7;
int const maxn = 21;

vector<int> v[maxn];
int dp[maxn][1<<maxn];

int solve(int mask, int x) {
    if (x == -1) {
        return mask == 0;
    }

    int &d = dp[x][mask];

    if (d != -1) {
        return d;
    }

    d = 0;

    for (int i : v[x]) {
        if ((1<<i)&mask) {
            d += solve(mask^(1<<i), x-1);

            if (d >= mod) d -= mod;
        }
    }

    return d;
}

