int popcount(int v) {
    int r = 0;
    while (v > 0) {
        r += v % 2;
        v >>= 1;
    }
    return r;
}

auto solve() {
    int N;
    cin >> N;

    const int MOD = 1e9 + 7;

    vvi a = vvi(N, vi(N, 0));
    REP(i, N) {
        REP(j, N) {
            cin >> a[i][j];
        }
    }

    int S = (1 << N);
    vvll dp = vvll(N + 1, vll(S, 0));
    dp[0][0] = 1;

    unordered_map<int,vi> grp;
    REP(s,S) {
        grp[popcount(s)].push_back(s);
    }

    REP(i, N) {
        for(auto&&s:grp[i]) {
            REP(j, N) {
                if (a[i][j] == 1) {
                    dp[i + 1][s | (1 << j)] += dp[i][s] ;
                    dp[i + 1][s | (1 << j)] %= MOD;
                }
            }
        }
    }

    return dp[N][S-1];
}


