	vector<int> dp(1 << n);
	const int M = 1000000007;
	dp[0] = 1;
	for (int mask = 1; mask < (1 << n); ++mask) {
		int bc = 0;
		for (int i = 0; i < n; ++i)
			bc += !((mask >> i) & 1);
		for (int i = 0; i < n; ++i) {
			if (g[bc][i] && ((mask >> i) & 1)) {
				dp[mask] += dp[mask ^ (1 << i)];
				if (dp[mask] >= M)
					dp[mask] -= M;
			}
		}
	}
	printf("%d\n", dp[(1 << n) - 1]);
	return 0;
}

