int dp[N][1 << N];
int dfs(int i, int mask) {
    if (i == n) return 1;
    int& ans = dp[i][mask];
    if (ans >= 0) return ans;
    ans = 0;
    for (int j = 0; j < n; j++) if (mat[i][j] && (!((mask >> j) & 1))) {
        ans += dfs(i + 1, mask | (1 << j));
        if (ans >= MOD) ans -= MOD;
    }
    return ans;
}

