//------------------------------------------------------------------------------
int num_of_bits(int bits)
{
    bits = (bits & 0x55555555) + (bits >> 1 & 0x55555555);
    bits = (bits & 0x33333333) + (bits >> 2 & 0x33333333);
    bits = (bits & 0x0f0f0f0f) + (bits >> 4 & 0x0f0f0f0f);
    bits = (bits & 0x00ff00ff) + (bits >> 8 & 0x00ff00ff);
    return (bits & 0x0000ffff) + (bits >>16 & 0x0000ffff);
}

//------------------------------------------------------------------------------
const int N_MAX = 21;
const int MOD = 1e9+7;
const int S_MAX = 1 << 21;

int N;
int a[N_MAX][N_MAX];

int S;
int dp[S_MAX];

void solve() {
  S = 1 << N;
  dp[0] = 1;
  for (int s = 0; s < S - 1; s++) {
    int i = num_of_bits(s);
    REP(j, N) {
      if (a[i][j] > 0 && (s >> j & 1) == 0) {
        int s2 = s | 1 << j;
        dp[s2] = (dp[s2] + dp[s]) % MOD;
      }
    }
  }
  printf("%d\n", dp[S - 1]);
}

void input() {
  scanf("%d", &N);
  REP(i, N) REP(j, N) scanf("%d", &a[i][j]);
}

int main() {
  input();
  solve();
  return 0;
}

