ll solve(ll n,ll seq)
{
    if(n==0) {
        if(seq==0)
            return dp[n][seq]=1;
        return dp[n][seq]=0;
    }
    if(dp[n][seq]!=-1)
        return dp[n][seq];

    ll sm=0;
    for(ll j=0;j<22;j++) {
