vector<vector<int>> a;
int N;

int rec(int S,int v){
    // cerr << "S=" << bitset<8>(S) <<" v=" << v<< endl;
    if(dp[S][v] >= 0){
        return dp[S][v];
    }
    if(S == (1<<N) -1){
        dp[S][v] = 1;
        return 1;
    }
    if(v == N){
        return 0;
    }
    long long retVal = 0;
    for(int i=0;i<N;i++){
        if(a[v][i] == 0){
            continue;
        }
        if((S >> i) &1 == 1){
            continue;
        }
        int nextS = S | (1 << i);
        if(dp[nextS][v+1] >=0){
            retVal += dp[nextS][v+1];
        }else{
            retVal += rec(nextS,v+1);
        }
        retVal %= MOD;
    }

    dp[S][v] = retVal;
    return retVal;
}


