void solve() {
    int n;
    cin >> n;

    vector< vector<int> > graph(n, vector<int>(n));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int x;
            cin >> x;
            graph[i][j] = x;
        }
    }

    vector<int> dp(1 << n); // dp[mask] denotes the number of ways to match [mask] subset
    dp[0] = 1; // 1 way to match when no women are paired
    // mask denotes the subset of women who are available. 0 means not paired

    for (int mask = 0; mask < (1 << n)-1; mask++) {
        int man = __builtin_popcount(mask);
        for (int woman = 0; woman < n; woman++) {
            if ((graph[man][woman]) && !(mask & (1 << woman))) {
                // man and woman are compatible and woman is free
                int mask2 = mask ^ (1 << woman);
                dp[mask2] += dp[mask];
                if (dp[mask2] >= MOD)
                    dp[mask2] -= MOD;
            }
        }
    }

    cout.precision(20);
    cout << dp[(1<<n) - 1]%MOD << endl;
}


