using namespace std;
#define ll long long int
#define M 1000000007

ll matching(vector<vector<bool>> &arr, int n, int i, int mask, ll *dp){
    if(i == n)
        return 1;
    if(dp[mask] != -1)
        return dp[mask];
    ll ans = 0;
    for(int j=0; j<n; j++){
        if(!(mask&(1<<j)) and arr[i][j]){
            ans = (ans + matching(arr, n, i+1, mask|(1<<j), dp))%M;
        }
    }
    dp[mask] = ans;
    return ans;
}

