  auto dp = new uint32_t[PN];
  dp[0] = 1;
  for (uint32_t i = 1; i < pn; ++i) {
    auto b = bitcnt(i) - 1;
    dp[i] = 0;
    for (uint32_t j = 0; j < n; ++j) {
