int fun( vector<vector<int>>& comp, int i, int woman_bit, int N)
{
    //Base case
    if(i == N+1)
    {
        if(woman_bit == 0)
            return 1;
            return 0;
    }

    //Lookup
    if(dp[i][woman_bit] != -1)
        return dp[i][woman_bit];

    //Rec case
    ll ans = 0;
    for(int w = 0; w < N; w++)
    {
