bool compatible[22][22];
int n;

ll dp[22][(1<<22)];

ll recursion(int i, int mask) {
	if(dp[i][mask] != -1) return dp[i][mask];


	if(i == 0 && __builtin_popcount(mask) == 1) {
		for(int j=0;j<n;j++)
			if(mask&(1<<j))
				return dp[i][mask] = compatible[0][j];
	}
	else if(i == 0) return dp[i][mask] = 0;

	if(i+1 != __builtin_popcount(mask)) return dp[i][mask] = 0;

	dp[i][mask] = 0LL;
	for(int j=0;j<n;j++) {
		if(mask&(1<<j) && compatible[i][j]) {
			dp[i][mask] += recursion(i-1, mask^(1<<j));
			dp[i][mask] %= mod;
		}
	}
	return dp[i][mask];
}

