            for (int j = 0; j < n; j++) {
                if (state >> j & 1 & a[i][j]) dp[i + 1][state] += dp[i][state ^ (1 << j)];
            }
        }
    }
    cout << dp[n][(1 << n) - 1] << '\n';
    return 0;
}

