#define rep(i, n) for(UL i = 0; i < (n); i++)

struct Problem {
public:

	bool ok[21][21];
	ULL dp[1 << 21] = {};

	void Solve() {
		UL N; scanf("%u", &N);
		rep(i, N) rep(j, N) {
			UL a; scanf("%u", &a);
			ok[i][j] = a;
		}
		dp[0] = 1;
		for (UL i = 1; i < (1 << N); i++) {
			UL p = i;
			p = (p & 0x55555555) + (p >> 1 & 0x55555555);
			p = (p & 0x33333333) + (p >> 2 & 0x33333333);
			p = (p & 0x0f0f0f0f) + (p >> 4 & 0x0f0f0f0f);
			p = (p & 0x00ff00ff) + (p >> 8 & 0x00ff00ff);
			p = (p & 0x0000ffff) + (p >> 16 & 0x0000ffff);
			rep(j, N) {
				if (i & (1u << j)) if (ok[p - 1][j])
					dp[i] += dp[i - (1u << j)];
			}
			dp[i] %= 1000000007;
		}
		printf("%llu", dp[(1 << N) - 1]);
	}
};

int main() {
	unique_ptr<Problem> p(new Problem());
	p->Solve();
	return 0;
}

