	if (cnt == n)
		return 1;
	if (memo[mask] != -1)
		return memo[mask];
	for (int j = 0; j < n; j++) {
		if ((mask & (1 << j)) || (a[cnt][j] == 0))
			continue;
		sum += dp(mask | (1 << j), cnt + 1);
		sum %= bigmod;
	}
	memo[mask] = sum;
	return sum;
}

