int N;

int solve(vector<vector<int>>& A, int n, int mask, vector<vector<int>>& dp) {

  if(n == 0) { return 1;}

  if(dp[n][mask] != -1) {
    return dp[n][mask];
  }

  int ans = 0;

  for(int j = 0; j < N; j++) {
    if( (mask & (1 << j)) && A[N-n][j]) {
      ans += solve(A, n-1, mask & ( ~ (1 << j)), dp);
      ans %= MOD;
    }
  }

  dp[n][mask] = ans;
  return ans;

}
