			return 1;
		}
		if(women_num == n){
			return 0;
		}
		ll ans = 0;
		for(int men =  0;men < n; ++men){
			if(((mask >> men) & 1 )== 0 && comp[men][women_num] == 1){
					ans += dp(mask | (1 << men), women_num+1,comp,target,n,save);
					ans %= MOD;
				}
			}
		save[mask][women_num] = ans%MOD;
		return ans%MOD;
	}

