            a[i][j] = tmp == 1;
        }
    }

    vector<vector<Mod<MOD>>> dp(N + 1, vector<Mod<MOD>>((1 << N), 0));
    dp[0][0] = 1;
    for (int i = 1; i <= N; i++)
    {
        for (int j = 0; j < (1 << N); j++)
        {
            bitset<32> b(j << 1);
            if (b.count() != i)
            {
                continue;
            }
            for (int k = 1; k <= N; k++)
            {
                if (!b[k])
                {
                    continue;
                }
                if (a[i][k])
                {
                    dp[i][j] += dp[i - 1][((j << 1) - (1 << k)) >> 1];
                }
            }
        }
    }
    cout << dp.back().back() << endl;
}

