int dp[22][(1<<21)];
int get(int p,int mask)
{     
      int &cache = dp[p][mask];
      if( p == n and mask == 0 ) return cache  = 1;
      if( p == n and mask > 0 )  return cache  = 0;
      if( cache != -1 ) return cache;
      int ways = 0;
      loop(j,0,n)
      {
            if( mat[p][j] == 1 and (x>>j)&mask ) 
            {
                  ways += get(p+1, mask^(x>>j));
                  // bug(mask, mask^(x>>j));
                  ways %= M;
            }
      }
      return cache = ways;
}


