const int MOD = 1e9 + 7;
int n, adj[25][25];
int dp[22][(1 << 22)];

int solve(int id, int bitmask) {
	if (bitmask == (1 << n) - 1) return 1;
	if (dp[id][bitmask] != -1) return dp[id][bitmask];

	int res = 0;
	for (int i = 0; i < n; i++) {
		if (adj[id][i] && !(bitmask & (1 << i))) res += solve(id + 1, bitmask | (1 << i));
		if (res > MOD) res -= MOD;
	}

	return dp[id][bitmask] = res;
}

