ll dp[22][(1<<22)];
ll n;

ll fun(ll i,ll a[][21],ll women_subset){
  if(i==n){                       // when no man is left 
    if(women_subset==0)return 1;  // when no woman is also not left
    else return 0;
  }

  if(dp[i][women_subset]!=-1)return dp[i][women_subset];

  ll ans = 0;
  for(int j=0;j<n;j++){
    ll cond = ((women_subset&(1<<j))?1:0);    // finding the jth bit of women_subset to know about the woman taken or not
    if(cond and a[i][j]==1)
    ans = (ans + fun(i+1,a,women_subset ^ (1<<j)))%mod;   // through xor operation we are taking that woman and making its bit = 0 in women_subset
  }

  return dp[i][women_subset]=ans;
}






