int N;

ll ff(ll n) {
	if(n<100)cout << "n=" << n << endl;
	if (dp[n] != 0) return dp[n];
	if (n == 0)return dp[n] = 1;
	int num = 0;
	for (int i = 0; i < N; i++) {
		if (n & (1 << i))num++;
	}

	int temp;
	for (int i = 0; i < N; i++) {
		if ((1 << i) & n) {
			if (rlt[num-1][i]) {
				temp = n ^ (1 << i);
				dp[n] += ff(temp);
				dp[n] %= DIV;
			}
		}
	}

	return dp[n]%=DIV;
}


