int solve(int i,int wset){
    if(i == (n+1)){
        if(wset == 0)
            return 1;
        else
            return 0;
    }

    if(dp[i][wset] != -1)
        return dp[i][wset];

    int ans = 0;
    for(int j=0;j<n;j++){
        bool available = (((1<<j)&(wset)) == 0) ? 0 : 1;
        if(available && compatible[i][j]){
            ans = (ans + solve(i+1, (wset^(1<<j)) ) ) % mod;
        }
    }
    dp[i][wset] = ans;

    return ans;
}

