struct Solver
{
    int N;
    vector< vector<int> > a;
    vector< vector<int> > masks;
    vector<long long> ways;

    void addSelf(long long& x, long long y) {
        x += y;

        if (x >= modulo) {
            x -= modulo;
        }
    }

    long long solve(int _N, vector< vector<int> >& _a) {
        N = _N;
        a = _a;

        masks.resize(N + 1);

        for (int i = 0; i < two(N); ++i) {
            int bits = __builtin_popcount(i);
            masks[bits].push_back(i);
        }

        ways.resize(two(N));
        ways[0] = 1;

        for (int i = 0; i < N; ++i) {
            for (int mask : masks[i]) {
                for (int j = 0; j < N; ++j) {
                    if (a[i][j] && !(mask & two(j))) {
                        addSelf(ways[mask | two(j)], ways[mask]);
                    }
                }
            }
        }

        return ways[two(N) - 1];
    }
};

