void solve() {
    int n, M = 1e9 + 7;
    cin >> n;

    vector<vector<int>> a(n, vector<int>(n));

    for (auto& i : a)
        for (auto& j : i) cin >> j;

    vector<int> dp(1 << n), cnt(1 << n);
    dp[0] = 1;

    queue<int> q;
    q.push(0);

    while (!q.empty()) {
        int msk = q.front(), i = cnt[msk];
        q.pop();

        if (i == n) break;

        for (int j = 0; j < n; ++j) {
            if (a[i][j] && !(msk & (1 << j))) {
                if (!cnt[msk | (1 << j)]) {
                    q.push(msk | (1 << j));
                    cnt[msk | (1 << j)] = cnt[msk] + 1;
                }
                dp[msk | (1 << j)] = (dp[msk | (1 << j)] + dp[msk]) % M;
            }
        }
        dp[msk] = 0;
    }
    cout << dp[(1 << n) - 1] << '\n';
}

