#define ll long long int
#define MOD 1000000007
using namespace std;

unordered_map<int,unordered_map<int,ll> > mp;

// Returns the number of ways to make the given sum by taking
// exactly one element from each rows
ll Solve(int row, int sum, int size, int arr[][21]){

	// If the given sum is negative, return 0
	if(sum < 0){return 0;}
	if(row < 0){
		if(sum == 0){return 1;}
		else{return 0;}
	}

	// If the given row has been calculated
	if(mp.find(row) != mp.end() && mp[row].find(sum) != mp[row].end()){return mp[row][sum];}

	ll ans = 0;
	for(int i=0 ; i<size ; i++){
		// If the current visited element is 1,
		// simply 
		if(arr[row][i] == 1){
			ll num = (1<<i);
			ans = (ans%MOD + Solve(row-1, sum-num, size, arr)%MOD)%MOD;
		}
	}
	mp[row][sum] = ans%MOD;
	return ans%MOD;
}


