	for(int i=0; i<N; i++){
		for(int j=0; j<N; j++){
			cin >> A[i][j];
		}
	}
	dp[0] = 1;
	for(int mask=1; mask<(1<<N); mask++){
		vector<int> ones = getOnes(mask, N);
		int man = ones.size()-1;
		//cout << mask<<" "<< man << ones.size() << endl;
		for(int woman: ones){
			if(A[man][woman]==1){
				int newMask = (mask & ~(1<<woman));
				dp[mask] = (dp[mask] + dp[newMask]) % mod; 
			}
		}
	}
	/*for(int i=0; i<(1<<N); i++){
	    cout << dp[i] << " ";
	}
	cout << endl;*/
	cout << (dp[(1<<N)-1]) % mod << endl;
}

