constexpr long long int mod = 1000000007;
long long int s(const std::vector<std::vector<bool>> &prefer, std::vector<long long int> &memo, const int current = 0, const Flag flag = Flag()) {
	if (current >= prefer.size()) return 1l;
	else if (memo[flag.index] >= 0) {
		return memo[flag.index];
	}else {
		memo[flag.index] = 0;
		for (auto i = 0; i < prefer.size(); ++i) {
			if (!flag(i) && prefer[current][i]) {
				memo[flag.index] += s(prefer, memo, current + 1, flag.use(i));
			}
		}
		memo[flag.index] %= mod;

		return memo[flag.index];
	}
}
