int ways(int mask, int woman, int n, vector<vector<int> > &match, vector<vector<int> > &dp) {
    if (woman == n)
        return 1;
    if (dp[woman][mask] != -1)
        return dp[woman][mask];
    int currWays = 0;
    for (int man = 0; man < n; man++) {
