bool flg[21][1 << 21];

mint calc(ll i, ll s){
    if(i >= a.size()){
        return 1;
    }
    if(flg[i][s]){
        return dp[i][s];
    }
    mint ret = 0;
    for(int j = 0; j < a.at(i).size(); ++j){
        if(a.at(i).at(j) == 0){
            continue;
        }
        if((s >> j) & 1){
            continue;
        }
        ret += calc(i + 1, s | (1 << j));
    }
    flg[i][s] = true;
    dp[i][s] = ret;
    return ret;
}

