const int mod = 1e9+7;
ll solve(int mi,
         ll mask) {
    guard(dp[mi][mask] == -1) else {
        return dp[mi][mask];
    }

    guard(mi > 0) else {
        rep(i,0,n) {
            int x = 1<<i;
            if(mask & x) {
                if(arr[mi][i]) {
                    dp[mi][mask] = 1;
                    return 1;
                } else {
                    dp[mi][mask] = 0;
                    return 0;
                }
            }
        }
    }



    var res = 0ll;
    rep(i,0,n) {
        if((1<<i & mask) != 0 && arr[mi][i] == 1) {
            res = (res + solve(mi-1, (mask - (1<<i))))%mod;
        }
    }
    dp[mi][mask] = res%mod;
    return dp[mi][mask];
}


