long long int recursive(int durum, int konum){
	if(konum==n)return 1;
	if(dp[durum][konum]!=-1)return dp[durum][konum];
	long long int cvp=0;
	for(int i=0;i<n;i++){
		if(!((durum>>i)&1)&&arr[konum][i]==1)
			cvp=(cvp+recursive(durum|(1<<i) , konum+1))%MOD;
	}
	dp[durum][konum]=cvp;
	return cvp;
}

