ll m = 1000000007;

ll solve(int pref, int subset)
{
    if (pref < 0 || subset < 0) return 0LL;
    if (!pref && !subset) return 1LL;
    if (!v[pref][subset])
    {
        v[pref][subset] = 1;
        for (int i = 1; i <= N; i++)
        {
            if (a[pref][i] && (subset & (1 << (i-1))))
            {
                dp[pref][subset] += solve(pref - 1, subset ^ (1 << (i-1)));
                if (dp[pref][subset] >= m) dp[pref][subset] -= m;
            }
        }
    }
    return dp[pref][subset];
}

