#include <bits/stdc++.h>
using namespace std;

constexpr int64_t MOD= 1'000'000'007;
constexpr bool is_FACTORIAL_STORED= false; // 階乗を配列に格納をする前処理をする/しない
constexpr int Nfac= is_FACTORIAL_STORED ? 200'007
                                        : 0;
/* 剰余環 Z/nZ */
struct mint{ // Z/nZ に関する演算(n:素数の場合は除算も)をサポートする構造体
  int64_t rep; // 出力すべき代表元 rep \in {0,1,..,MOD- 1}
  mint(int64_t x=0): rep(((x%MOD)+ MOD)% MOD){}
  mint operator-() const { return mint(-rep);}
  mint& operator+=(const mint& x){
    rep+= x.rep; 
    if(rep>= MOD) rep-= MOD;
    return *this;
  }
  mint& operator-=(const mint& x){
    rep-= x.rep;
    if(rep< 0) rep+= MOD;
    return *this;
  }
  mint& operator*=(const mint& x){
    rep*= x.rep; rep%= MOD;
    return *this;
  }
  mint operator+(const mint x) const {
    mint ans(*this);
    ans+= x;
    return ans;
  }
  mint operator-(const mint x) const {
    mint ans(*this);
    ans-= x;
    return ans;
  }
  mint operator*(const mint x) const {
    mint ans(*this);
    ans*= x;
    return ans;
  }
  bool operator==(const mint x) const {
    return rep==x.rep;
  }
  bool operator!=(const mint x) const {
    return rep!=x.rep;
  }

  mint pow(int64_t d) const{
    assert(d >= 0); // ここで引っかかったら this.pow(d)= 0 or this.pow(-d).inv() のどちらかを選べ
    assert(!(*this==0 && d==0)); //   this.pow(d)= 0 or 1           　     のどちらかを選べ
    mint ans= 1;
    mint x= *this;
    while(d > 0){
      if(d&1){ ans*= x; }
      d >>= 1;
      x*= x;
    }

    return ans;
  }

  friend istream& operator >> (istream &is, mint& x) noexcept{
    int64_t a;
    is >> a;
    x= a;
    return is;
  }
  friend ostream& operator << (ostream &os, const mint& x) noexcept{
      return os << x.rep;
  }
  // MOD が素数(<=> Z/nZ が体)のとき
  mint inv() const{
    return pow(MOD-2);
  }
  mint& operator/=(const mint& x){
    *this *= x.inv();
    return *this;
  }
  mint operator/(const mint x) const {
    mint ans(*this);
    ans/= x;
    return ans;
  }
};
// ^^^ テンプレここまで ^^^
constexpr int Nmax= 21;
using Matrix= vector<bitset<Nmax>>;
using Index= int;

void solve(const Matrix &data, Index idx, vector<mint> *dp){
  if(dp->at(idx) != 0){ return; }
  else{
    static size_t N= data.size();
    size_t male= __builtin_popcount(idx);
    if(male==N){
      dp->at(idx)= 1;
    }
    else{
      mint ans_m= 0;
      for(size_t female=0; female<N; female++){
        if(data.at(male).test(female) && !(idx & (1<< female))){
          idx|= 1<< female;
          solve(data, idx, dp);
          ans_m+= dp->at(idx);
          idx&= ~(1<< female);
        }
      }
      dp->at(idx)= ans_m;
    }
  }
}

int main(){
  int N;
  cin >> N;

  Matrix data(N);
  int buf;
  for(int i=0; i<N; i++){
    for(int j=0; j<N; j++){
      cin >> buf;
      if(buf==1){
        data.at(i).set(j);
      }
    }
  }

  vector<mint> dp(1<<N);
  solve(data, 0, &dp);

  mint ans= dp.at(0);

  cout << ans << endl;
}

