const int mod = 1e9+7;
int n;
int dp[21][1<<21];
vector<vector<int>> a;
int ways(int man,vector<bool> woman) {

  if (man >= n) return 1;
  int num = 0;
  for(int i=0;i<n;i++) {
    if (woman[n-1-i]) {
      num += 1 << i;
    }
  }
  auto &res = dp[man][num];
  if (res != -1) return res;
  res = 0;
  for(int i=0;i<n;i++) {
    if (a[man][i] and woman[i]) {
      woman[i] = false;
      res = (res + (long long) ways(man+1,woman)) % mod; 
      woman[i] = true;
    }
  }
  // cerr << "res for man: " << man << " " <<  res << '\n';
  return res;
}
int solve() {
  cin >> n;
  memset(dp,-1,sizeof dp[0][0] * 21 * (1<<21));
  a.resize(n,vector<int>(n));
  for(auto &e: a) for(auto &c: e) cin >> c;
  vector<bool> woman(n,true);
  return ways(0,woman);
}
