const int N = 21;
const ll mod = 1000000007;

int memo[N][1 << N], comb[N][N], n;
bool vis[N][1 << N];

ll dp(int id, int mask){
    if(id == n){
        if(mask == (1 << n) - 1) return 1;
        return 0;
    }
    if(vis[id][mask]) return memo[id][mask];
    vis[id][mask] = true;

    ll ans = 0;
    for(int i = 0; i < n; i++)
        if((mask & (1 << i)) == 0 && comb[id][i])
            ans = (ans + dp(id + 1, mask | (1 << i))) % mod;

    return memo[id][mask] = ans;

}


