//mask represents a subset of women,e.g:- 010010 represents that the 2nd and 5th women are paired.

//dp[i][mask] tells the total no. of possible pairings considering the first i men
//with a subset of size i of women represented by mask.

//Answer will be dp[n][(1<<n)-1] as we have to pair all n men with all n women.
int dp[N][1<<21]; 

int can[N][N]; //can[i][j] is 1 if ith man is permitted to pair up with the jth woman,otherwise 0.

int main()                  
{
    int n;

    scn(n);

    rep(i,0,n)
    {
        rep(j,0,n)
        scn(can[i][j]);
    }

