    for(int i=1;i<=n;i++)
    {
        for(int mask=0;mask<(1<<n);mask++)
        {
            int set_bits=__builtin_popcount(mask);

            //check if no. of women in this candidate subset 
            //is equal to i(i.e the no of men to match) or not.
            if(set_bits!=i) 
            continue;

            //ith men should be compatible to pair with jth women
            //and jth women should be a part of the current candidate subset
            //represented by mask.
            for(int j=0;j<n;j++)
            if(can[i-1][j] and mask&(1<<j))
            {
                int temp_mask=mask^(1<<j);

                dp[i][mask]=(dp[i][mask]+dp[i-1][temp_mask])%mod;
            }
        }
    }

    ll ans=dp[n][(1<<n)-1];

    printf("%lld ",ans);
}

