inline int add (int a, int b) { return ((a%MOD) + (b%MOD)) % MOD; };

void solve() {
   for (int i = 1; i <= n; ++i) {
      for (int j = 0; j < (1 << n); ++j) {
         dp[i][j] = 0;
      }
   }

   for (int k = 0; k < n; ++k) {
      if (ar[1][k+1]) dp[1][1 << k] = 1;
   }

   for (int i = 2; i <= n; ++i) {
      for (int j = 0; j < (1 << n); ++j) {
         if (__builtin_popcount(j) != i) continue;
         for (int k = 0; k < n; ++k) {
            if (ar[i][k+1]) dp[i][j] = add(dp[i][j], dp[i-1][j - (1 << k)]);
         }
      }
   }
   int total = 0;
   for (int j = 0; j < (1 << n); ++j) {
      if (__builtin_popcount(j) != n) continue;
      total = add(total, dp[n][j]);
   }
   cout << total << '\n';
}

