const int MAX_N = 21;
const int MOD = 1000000007;
ll dp[(1<<MAX_N)];
int a[MAX_N][MAX_N];
int n;

int dfs(int k){
    if(dp[k]!=-1)return dp[k];

    int flag[n] = {};
    int count = 0;
    int kk = k;
    rep(i,n){
        flag[i] = kk%2;
        count += flag[i];
        kk /= 2;
    }
    if(count == 1){
        int x;
        rep(i,n){
            if(flag[i]==1){
                x = i;
                break;
            }
        }
        if(a[0][x]==1){
            dp[k] = 1;
        }else{
            dp[k] = 0;
        }
        return dp[k];
    }else{
        dp[k] = 0;
        rep(i,n){
            if(flag[i]==0)continue;
            if(a[count-1][i]==0)continue;
            dp[k] += dfs(k - (1<<i));
            dp[k] %= MOD;
        }
        return dp[k];
    }
}

