const int MAX_SIZE = 22;
int memo[MAX_SIZE][1<<22];
int visited[1<<22];
int N;
VV(int) a;


int main() {

    cin >> N;
    a.resize(N+1);
    for(auto i = 1; i<=N; i++){
        a[i].resize(N+1);
    }

    for(auto i = 1; i<=N; i++){
        for(auto j = 1; j<=N; j++){
            cin >> a[i][j];
        }
    }

    // dp[i+1][mask] = SUM(dp[i][x] s.t. (mask & x) == x)

    queue<int> x;


    for(auto i = 0; i<N; i++){
        auto mask = 1<<i;

        if (a[1][i+1] == 0) continue;
        memo[1][mask] = 1;
        x.push(1<<i);
        visited[1<<i] = 1;

    }
    x.push(-1);

    for(auto i = 2; i<=N; i++){

        while(x.front() !=-1){

            auto from = x.front();
            x.pop();

            for(auto j = 0; j<N; j++){

                if (a[i][j+1] == 0) continue;
                auto temp = (1<<j) + from;
                if ((from >> j)%2 == 1) continue;
                memo[i][temp] += memo[i-1][from];
                memo[i][temp] %=MOD;
                if (visited[temp] == 0) x.push(temp);
                visited[temp] = 1;
            }
        }


        x.pop();
        x.push(-1);

    }
    cout << memo[N][(1<<N)-1] << endl;



    return 0;
}

