int n;
int cal(int pos,int mask)
{

  if(mask+1==(1<<n))
    return 1;
  if(pos==n)
    return 0;
  if(dp[pos][mask]!=0)
    return dp[pos][mask];
  int ways=0;
  for(int i=0;i<n;i++)
  {
    if(a[pos][i]==1&&(mask&pow(2,i))==0)
    {
      ways+=(cal(pos+1,mask|pow(2,i))%1000000007);
      ways%=1000000007;
    }  
  }
  dp[pos][mask]=ways;
  return dp[pos][mask];
}
