int n;
vector<VI> a;
VL memo;
ll solve(int bit) {
    if (bit == (1 << n) - 1)return 1LL;
    if (memo[bit] != -1)return memo[bit];

    int k = 0;
    FOR(i, 0, n)if(bit & (1 << i))++k;

    ll ret = 0;
    FOR(i, 0, n) {
        if (bit & (1 << i))continue;
        if (a[k][i] == 0)continue;
        (ret += solve(bit | (1 << i))) %= mod;
    }

    return memo[bit] = ret;
}

