int full;
int dfs(int mask, int i, vector<vector<int>>& v, vector<vector<long long int>>& dp)
{
    int n = v.size();

    if(mask == full)
        return 1;

    if(i >= n)
        return 0;

    if(dp[mask][i])
        return dp[mask][i];

    for(int j=0; j<n; j++)
        if(v[i][j] && !(mask & 1<<j))
            dp[mask][i] = (dp[mask][i] + dfs(mask|(1<<j), i+1, v, dp))%mod;

    return dp[mask][i];
}
