		}
	}

	dp.assign((1 << n), 0);


	dp[0] = 1;
	for (int mask = 0; mask < (1 << n); mask++)
	{
		int j = bitcount(mask);

		for (int i = 0; i < n; i++)
		{
			if (!(mask & (1 << i)) && g[j][i])
			{
				int newmask = mask + (1 << i);
				dp[newmask] += dp[mask];
				dp[newmask] %= mod;
			}
		}
	}

	cout << dp[(1 << n) - 1];
}

