ull dp[MAX_N + 1][MAX_MASK];
ull inp[MAX_N + 1];

int main() {
	ios_base::sync_with_stdio(false);
	for (size_t i = 0; i <= MAX_N; i++) {
		for (size_t j = 0; j < MAX_MASK; j++) {
			dp[i][j] = 0;
		}
	}
	dp[0][0] = 1;

	int N; cin >> N;
	for (size_t i = 1; i <= N; i++) {
		ull mask = 0;
		for (size_t j = 0; j < N; j++) {
			ull val; cin >> val;
			mask |= val << j;
		}
		inp[i] = mask;
	}

	ull MASK = 1 << N;
	for (size_t i = 1; i <= N; i++) {
		for (size_t mask = 0; mask < MASK; mask++) {
			if (__builtin_popcount(mask) == i - 1) {
				for (size_t bit = 0; bit <= N; bit++) {
					if ((1 << bit) & inp[i] && !((1 << bit) & mask)) {
						dp[i][(1 << bit) | mask] = (dp[i][(1 << bit) | mask] + dp[i - 1][mask]) % MOD;
					}
				}
			}
		}
	}
	cout << dp[N][(1 << N) - 1] << endl;
	return 0;
}

