  // 集合 S := すでにペアになった (マッチングが完了した) 女性の集合
  vector<vector<long long>> dp(N+1, vector<long long>(1 << N, 0));
  dp.at(0).at(0) = 1;
  for (int i = 0; i < N; i++) {
    for (int S = 0; S < (1 << N); S++) {
      if (__builtin_popcount(S) == i) {
        for (int j = 0; j < N; j++) {
          if (!(S & (1 << j))) {
            if (A.at(i).at(j) == 1) {
              dp.at(i+1).at(S | (1 << j)) += dp.at(i).at(S);
              dp.at(i+1).at(S | (1 << j)) %= MOD;
            }
          }
        }
      }
    }
  }
  cout << dp.at(N).at((1 << N) - 1) << endl;
}

