// f : women's flags
// m : man's id
ll rec(ll f, ll m){
  if(dp[f][m]!=-1) return dp[f][m];

  if(m>=N) return 1;
  // if(f==0) return 1;

  // mの男を誰に当てるか
  ll sum=0;
  rep(i, N){
    if(A[m][i]==1 && f>>i&1){
      // ペア候補
      ll new_f = f ^ (1LL<<i);
      sum += rec(new_f, m+1);
      sum %= mod;
    }
  }
  return dp[f][m] = sum;
}

