ll dfs(set<int> male, set<int> female)
{
    if (male.size() == 1) {
        if (a[*(male.begin())][*(female.begin())] == 1) return 1;
        else return 0;
    }
    else if (dp.find(make_pair(male, female)) != dp.end()) {
        return dp[make_pair(male, female)];
    }
    else {
        ll nCouples = 0;
        auto targetM = male.begin();
        set<int> resMale = male;
        resMale.erase(*targetM);
        for (auto itrF = female.begin(); itrF != female.end(); ++itrF) {
            if (a[*targetM][*itrF] == 1) {
                set<int> resFemale = female;
                resFemale.erase(*itrF);
                nCouples = (nCouples + dfs(resMale, resFemale)) % MOD;
            }
        }
        dp[make_pair(male, female)] = nCouples;
        return nCouples;
    }
}


