bool compatible[N][N];
int n;
ll memo[N][(1 << 21) + 500];
const ll m = 1e9 + 7;

ll add(ll a , ll b) {
    return ((a % m) + (b % m)) % m;
}

ll dp(int curr , int mask) {
    if (curr >= n) return 1;
    ll &sol = memo[curr][mask];
    if (sol != -1) return sol;
    ll sum = 0;
    for (int i = 0 ; i < n ; i++)
        if (compatible[curr][i] && (mask & (1 << i)) == 0)
            sum = add(sum , dp(curr + 1 , mask | (1 << i)));
    return sol = sum;
}

