#define MD 1000000007

int dp[2097157], P[25];
int N, A[25][25];
int U[25], n;

int solve()
{
    int h = 0;
    for (int i = 0; i < n; i++) h += P[U[i]];
    if (dp[h] != -1) return(dp[h]);
    int c = N - n;
    if (c == N)
    {
        dp[h] = 1;
        return(1);
    }
    int res = 0;
    for (int i = 0; i < n; i++) if (A[c][U[i]])
    {
        if (i < n - 1)
        {
            int tmp = U[i];
            U[i] = U[n - 1];
            n--;
            res = (res + solve()) % MD;
            U[i] = tmp;
            n++;
        }
        else
        {
            n--;
            res = (res + solve()) % MD;
            n++;
        }
    }
    dp[h] = res;
    return(res);
}

