ll solve1(vector<vi> &a, ll id, ll mask, ll n) {

	if (mask == done) {
		return 1;
	}
	if (id == n) {
		return 0;
	}

	if (dp[id][mask] != -1) {
		return dp[id][mask];
	}
	ll ans = 0;
	for (ll i = 0; i < n; i++) {
		bool ava = ((1 << i)&mask);
