int findways(vector<int> &dp, int male, int mask, vector<vector<int>> &check)
{
  //cout << "mask " << std::bitset<5>(mask)<<endl;
  if (mask == 0)
    return 1;
  if (dp[mask] != 0)
    return dp[mask];
 // int male = __builtin_popcount(mask);       // ith male
  for (int female = 0; female < n; ++female) // ith female
    if (check[male - 1][female] && (mask & (1 << female)))
    {
      int new_mask = mask ^ (1 << female);

      dp[mask] = add(dp[mask], findways(dp, male - 1,  new_mask, check));
    }
  return dp[mask];
}

