#define MAX_N (21)
#define NUM_MOD (1000000007)

using namespace std;

int dps[1 << MAX_N];

void init(int N) {
  for (int S = 0; S < (1 << N); S++) {
    dps[S] = -1;
  }
}

int calc_num_ways(int S, const vector<vector<int>> &adj_lists) {
  const int N = adj_lists.size();
  if (S == (1 << N) - 1) {
    return 1;
  }
  if (dps[S] < 0) {
    int i = 0;
    for (int k = 0; k < N; k++) {
      if (S & (1 << k)) {
        i++;
      }
    }
    int dp = 0;
    for (int j : adj_lists[i]) {
      if ((S & (1 << j)) == 0) {
        dp = (dp + calc_num_ways(S | (1 << j), adj_lists)) % NUM_MOD;
      }
    }
    dps[S] = dp;
  }
  return dps[S];
}

int main() {
  // read inputs
  int N, ass[MAX_N][MAX_N];
  scanf("%d", &N);
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      scanf("%d", &ass[i][j]);
    }
  }

  // create graph
  vector<vector<int>> adj_lists(N, vector<int>());
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      if (ass[i][j]) {
        adj_lists[i].push_back(j);
      }
    }
  }

  // solve
  init(N);
  printf("%d\n", calc_num_ways(0, adj_lists));
}

