ll f(int mask, vector<vector<int>> &compat, vector<int> &dp) {
    int k = __builtin_popcount(mask);   // no. of men already assigned
    // base case: all men assigned
    if (k >= compat.size())
        return 1;

    if (dp[mask] != -1)
        return dp[mask];

    int res = 0;
    for (int j = 0; j < compat.size(); j++) {
        if (!(mask & (1 << j))) {
            if (compat[k][j]) {
                // if jth woman is compatible with kth man
                int newmask = (mask | (1 << j));
                res = ((res % MOD) + (f(newmask, compat, dp) % MOD)) % MOD;
            }
        }
    }
    dp[mask] = res % MOD;
    return dp[mask];
}

