void allot_person(int& mask,int p)
{
    int z = (1<<p);
    mask |= z;
}

void unallot_person(int& mask,int p)
{
    int z = (1<<p);
    mask ^= z;
}

bool check_allot(int mask,int p)
{
    int z = (1<<p);
    mask &= z;
    return mask;
}

ll solve(vector<vector<bool>>& G,int& alloted,int woman,int n,unordered_map<ll ,unordered_map<ll,ll>>& memo)
{
    //cout<<woman<<endl;

    if (memo.find(alloted) != memo.end() && memo[alloted].find(woman) != memo[alloted].end())
    {
        return memo[alloted][woman];
    }

    if (alloted == pow(2,n) - 1) return 1;
    if (woman == n) return 0;

    ll ans = 0;

    //allot

    for (int man=0;man<n;++man)
    {
        //cout<<"M"<<man<<endl;
        if (G[man][woman] && !check_allot(alloted,man))
        {
            //cout<<"GOT_IN"<<endl;
            allot_person(alloted,man);
            ans += solve(G,alloted,woman+1,n,memo);
            ans %= MOD;
            unallot_person(alloted,man);
        }
    }

    memo[alloted][woman] = ans;
    ans %= MOD;

    return ans;

}


