int calc(int m) {
    if (m == 0)
        return 1;

    if (calced[m])
        return dp[m];

    int num = -1;
    forn(i, n) num += (m & (1 << i)) != 0;

    forn(i, n)
        if (a[num][i] && (m & (1 << i)))
            dp[m] = (dp[m] + calc(m ^ (1 << i))) % mod;
    calced[m] = true;
    return dp[m];
}

