int go(int id, int taken){
    if(id >= n)
        return 1;
    int &ways = dp[id][taken];
    if(~ways)
        return ways;
    ways = 0;
    for(int i = 0; i < n; i++) if((taken >> i & 1) == 0){
        if(comp[id][i])
            ways = (ways + go(id + 1, taken | (1 << i))) % mod;
    }
    return ways;
}

