int rec(int S, int V, int n){
	if(DP[V][S] >= 0){
		return DP[V][S];
	}

	if(!a[n][V]){
		DP[V][S] = 0;
		return 0;
	}
	else if(n == N-1){
		DP[V][S] = 1;
		return DP[V][S];
	}

	int sum = 0;
	int nextS = S | (1 << V);
	for(int i = 0; i < N; i++){
		if(i != V && !(S >> i & 1)){
			sum += rec(nextS, i, n+1);
			sum %= mod;
		}
	}

	DP[V][S] = sum;
	return DP[V][S];
}

int calc(){
