int dd(int x) {
	if (x == 0) return 1;
	if (dp[x] >= 0) return dp[x];
	int v[22];
	int rt = 0;
	int tmp = x;
	int m = 0;
	int cnt = 0;
	while (tmp > 0) {
		if (tmp % 2) {
			v[m] = cnt;
			m += tmp % 2;
		}
		cnt++;
		tmp /= 2;
	}
	for (int i = 0; i < m; i++) {
		int cur = v[i];
		if (arr[m][cur + 1]) {
			if (dp[x - idx[cur]] < 0) rt = (rt + dd(x - idx[cur])) % INF;
			else rt = (rt + dp[x - idx[cur]]) % INF;
		}
	}
	dp[x] = rt;
	return rt;
}

