using Mat=vector<vector<int>>;
const int pri=1000000007;

int det(Mat M){
	int N=M.size();
	if(N==1) return M[0][0];
	int ans=0;
	for(int i=0;i<N;i++){
		Mat P(N-1,vector<int>(N-1));
		int now=0;
		for(int j=0;j<N;j++){
			if(j==i)continue;
			for(int k=1;k<N;k++){
				P[now][k-1]=M[j][k];
			}
			now++;
		}
		ans+=M[i][0]*det(P)%pri;
		ans%=pri;
	}
	return ans;
}

