ll cal(ll mask){
  if (mask == 0) return 1;
  if (dp[mask] != -1) return dp[mask];

  ll ct = 0;
  REP (i,n) if ((1<<i)&mask) ct++;

  ll ret = 0;
  REP1 (i,n) if ((1<<(i-1))&mask && d[ct][i]) add(ret,cal(mask^(1<<(i-1))));
  return dp[mask] = ret;
}
