using namespace std;
int dp[2100000][25];
int allMask, n;
int countWays(int mask, int women, vector<vector<int>> &men){
    if(mask == allMask) return 1;
    if(women > n) return 0;
    if(dp[mask][women] != -1) return dp[mask][women];
    int ways = 0;
    for(int i = 0; i < men[women].size();++i){
        if(((mask & (1 << (men[women][i] - 1))) == 1)) continue;
        else
            ways = (ways % mod7 + countWays(mask | (1 << (men[women][i] - 1)), women + 1, men) % mod7) % mod7;
    }
    dp[mask][women] = ways;
    return ways;
}
