size_t get_mask()
{ 
  size_t mask = 0;
  for (int i = 0; i < N; ++i)
  { 
    mask |= (1 << i);
  }
  return mask;
}

size_t add(size_t res, size_t delta)
{ 
  return (res + delta) % 1000000007;
}

size_t solution(int i, size_t mask = 0)
{ 
  size_t res = 0;
  { 
    for (int j = 0; j < N; ++j)
    { 
      if (v[i][j] && !(mask & (1<<j)))
      { 
        if ((mask | (1<<j)) == MASK)
        { 
          res = add(res, 1);
          continue;
        }
        if (dp[i+1][mask | (1<<j)] == -1)
        { 
          dp[i+1][mask | (1<<j)] = solution(i+1, mask | (1<<j));
        }
        res = add(res, dp[i+1][mask | (1<<j)]);
      } 
    }
  }
  return res;
}

