ll ipow(ll a, ll b){
    ll res = 1;
    while(b > 0){
        if(b%2 == 1)res*=a;
        b /= 2;
        a *= a;
    }
    return res;
}

ll f(vector<vector<ll>>& dp, vector<vector<int>>& A, int N, int male, int bits){
    if(dp[male][bits] != -1)return dp[male][bits];
    // cout<<male<<" "<<bits<<endl;
    if(male == N){
        dp[male][bits] = 1;
        return dp[male][bits];
    }
    dp[male][bits] = 0;
    for(int i = 0;i < A[male].size();i++){
        int female = A[male][i];
        if((bits>>female) & 1){
            dp[male][bits] = (dp[male][bits] + f(dp,A,N,male+1,bits-(1<<female))) % MOD;
        }
    }
    return dp[male][bits];
}

