    }
  }
  vector<vector<mint>> dp(N+1,vector<mint>(1 << N));
  dp[0][0] = 1;
  for (int i = 0, m = 1 << N; i < N; i++) {
    for (int j = 0; j < m; j++) {
      if (__builtin_popcount(j) == i) {
        for (int k = 0; k < N; k++) {
          if (a[i][k] && !(j & 1 << k)) {
            dp[i+1][j | 1 << k] += dp[i][j];
          }
        }
      }
    }
  }
  cout << dp[N].back().x;
}

