	memset(dp, 0, sizeof(dp));
	for (int i = 0; i <= n; i++)
	{
		for (int w = 0; w <= W; w++)
		{
			if (i == 0)
				dp[i][w] = 1;
			else
			{
				for (int j = 0; j < n; j++)
