ll cal(ll curr,ll mask)
{
    if(curr==n+1)
    {
        if((mask+1)==(1<<curr))
            return 1;
        return 0;
    }

    if(curr>n)  
        return 0;


    ll &ret=dp[curr][mask];
    if(ret!=-1)
        return ret;

    ll cnt=0;
    for(int i=1;i<=n;i++)
    {
        if((1<<i)&mask)
            continue;
        if(mat[curr][i]==1)
        {
            cnt+=cal(curr+1,(mask|(1<<i)));
            cnt%=mod;
        }
    }
    return ret=cnt;
}

