ll solve(ll idx, ll mask) {

	if(idx == n)
		return mask == (1 << n) - 1;

	if(dp[idx][mask] != -1)
		return dp[idx][mask];

	ll ans = 0;
	ll new_mask;

	for(int i = 0; i < n; i++) {
		if(!(mask&(1<<i)) && arr[idx][i]) {

			new_mask = mask | ( 1 << i);
			ans += solve(idx + 1, new_mask);
			ans %= mod;
		}
	}

	return dp[idx][mask] = ans;
}


