#include <bits/stdc++.h>
using namespace std;

const int N = 21;
const int MOD = 1e9 + 7;

int dp[1 << N];
int arr[N][N];
int n;

void read() {
  cin >> n;
  for (int i = 0 ; i < n ; i++)
    for (int j = 0 ; j < n ; j++)
      cin >> arr[i][j];
}

int work() {
  dp[(1 << n)-1] = 1;
  for (int bm = (1 << n)-2 ; bm >= 0 ; bm--) {
    int pos = __builtin_popcount(bm);

    for (int i = 0 ; i < n ; i++) {
      if (arr[pos][i] == 1 && (bm & (1 << i)) == 0) {
        dp[bm] = (dp[bm] + dp[bm | (1 << i)]) % MOD;
      }
    }
  }
  return dp[0];
}

int main() {
  read();
  cout << work() << endl;
  return 0;
}

