int rec(int i, int j, int k){
    //cout << i << " " << j << " " << k << endl;
    if(DP[i][j][k] != -1) return DP[i][j][k];
    if(i == 0){
        //cout << i << " " << j << " " << k << endl;
        if(A[i][k] == 1 && j != k) return DP[i][j][k] = 1;
