int solve(void)
{
    vector<vi> dp(1LL << n, vi(n + 1, 0));

    dp[0][0] = 1;
    for (int mask = 1; mask < (1LL << n); ++mask)
    {
        for (int i = 1; i <= n; ++i)
        {
            for (int j = 1; j <= n; ++j)
