ll ways(ll pos, ll mask){
  if(pos>n and mask==((1<<(n))-1)){
    return 1;
  }
  if(dp[pos][mask]!=-1)return dp[pos][mask];
  ll ans=0;
  rep(i, 1, n, 1){
    if(adj[pos][i]==1 and !((mask>>(i-1))&1)){
      mask|=(1<<(i-1));
      ans+=ways(pos+1, mask)%MOD;
      ans%=MOD;
      mask^=(1<<(i-1));
    }
  }
  return dp[pos][mask]=ans;
}

