                }

                // 相性もよく、まだペア確定していない場合はdpに記憶
                dp[p|(1<<k)] += dp[p];
                dp[p|(1<<k)] %= mo;
            }
        }
    }
    std::cout << dp.back() << std::endl;

    return 0;
}

