constexpr ll N_MAX = 21;

void solve() {
	ll N;
  	scanf("%lld", &N);
	vector<vector<ll>> a(N,vector<ll>(N));
	rep(i, N) rep(j, N) scanf("%lld", &a[i][j]);

	vector<vector<Modint>> dp(N+1,vector<Modint>(1LL<<N,0));
	auto f=[&](auto&& f, ll index, ll bit)->Modint{
		if(index==N)return 1;
		if(dp[index][bit]>0)return dp[index][bit];
		Modint t=0;
		rep(i,N){
			if(bit & 1LL<<i)continue;
			if(a[index][i]){
				ll x=bit|(1LL<<i);
				t+=f(f,index+1,x);
			}
		}
		return dp[index][bit]=t;
	};

	Modint ans=f(f,0,0);

	printf("%lld\n", ans);
}

signed main() {
	solve();
	return 0;
}

