long long helper(const vector<vector<int>>& match, vector<unordered_map<int, long long>>& dp, int states, int idx) {
	if (idx >= match.size()) return 1;
	auto dp_itr = dp[idx].find(states);
	if (dp_itr != dp[idx].end()) return (*dp_itr).second;
	long long total = 0;
	for (int i = 0; i < match.size(); i++) {
		if (match[idx][i] == 0) continue;
		if (states & (1 << i)) continue;
		total = (total + helper(match, dp, states | (1 << i), idx + 1)) % 1000000007;
	}
	return dp[idx][states] = total;
}

int main (int argc, char* argv[]) {
