long long mask, mod = 1e9+7;
int n;
long long count(vector<vector<long long> > &dp,int msk, int p, vector<vector<bool> > &v){
    if(msk == mask){
      //  cout<<"dddddd "<<endl;
        return 1;
    }
    if(dp[msk][p] != -1)
        return dp[msk][p];
    long long ans=0;
    for(int a=0; a<n; a++){

        long long tt = (msk & (1<<a));
       // cout<<p<<" "<<tt<<endl;
        if(tt==0 && v[a][p]){
       //     cout<<"sdfsd "<<endl;
            ans += count(dp,(msk|(1<<a)),p+1,v);
        }
    }
    ans = ans%mod;
    dp[msk][p] = ans;
    return ans;
}

