        int tt;
        cin>>tt;
        if(tt)
            v[a][b] = true;
    }
   }
   mask = (1<<n)-1;

   std::vector<vector<long long> > dp(mask+2, vector<long long> (n+2, -1));
   long long ans = count(dp,0,0,v);
   cout<<ans<<endl;
   return 0;
}

