//correct approach . dp[i][j] represents the num of ways we can paint the i ka subtree including itself with j restrictions . 
long long int solve_correct(int u,bool constraint,int pr){
   //we will pass the parent every tiue . 

    if(dp[u][constraint]!=-1){
        return dp[u][constraint] ; 
    }

    long long int ans = 0 ; long long int v1 = 1 ;
    for(auto p:tree[u]){
        if(p!=pr){
            v1 = (v1*solve_correct(p,0,u))%MOD ; 
        }
    }
    ans=(ans+v1)%MOD ;
    if(!constraint){
        long long int v2 = 1 ; 
         for(auto p:tree[u]){
             if(p!=pr){
                 v2 = (v2*solve_correct(p,1,u))%MOD ; 
             }
         }
    ans = (ans+v2)%MOD ;
    }

  return dp[u][constraint] = ans ; 

}
