mi solve(int i, bm mask) {
  if (i == n) return 1;
  if (!vis[i][mask.v]) {
    for (int j = 0; j < n; ++j) {
      if (a[i][j] && mask[j] == 0) {
        dp[i][mask.v] += solve(i+1, mask.set(j));
      }
    }
    vis[i][mask.v] = 1;
  }
  return dp[i][mask.v];
}

