      int new_mask = mask ^ (1 << female);

      dp[mask] = (dp[mask] + findways(dp, new_mask, check)) % mod;
    }
  return dp[mask];
}

int main()
{
  scanf("%d", &n);
  vector<vector<int>> check(n, vector<int>(n));
  vector<int> dp(1 << n, 0);
  for (auto &x : check)
    for (auto &y : x)
      cin >> y;
  cout << findways(dp, (1 << n) - 1, check) << endl;

  return 1;
}

