int my_popcount(int T) {
	T -= (T >> 1) & 0x55555555;
	T = (T & 0x33333333) + ((T >> 2) & 0x33333333);
	T = (T + (T >> 4)) & 0x0F0F0F0F;
	T = (T * 0x01010101) >> 24;
	return T;
}

void solve(void) {
	dp.resize(N + 1, vi(1 << N));
	dp[0][0] = 1;
	for (int S = 1; S < (1 << N); ++S) {
		int i = my_popcount(S);
		for (int j = 0; j < N; ++j) {
			if (((S >> j) & 1) == 1 && A[i - 1][j] == 1)
				dp[i][S] = (dp[i][S] + dp[i - 1][S^(1 << j)]) % MOD;
		}
	}
}

