                int fix = en[uu];
                for(long long int k: f[fix]) {
                    if(k>=n/2)continue;
                    if(pw[k]&u) {
                        dp[u][uu]+=dp[u-pw[k]][uu-pw[fix]];
                    }
                    dp[u][uu]%=mod;
                }
            }
        }
    }
    dp2[0][0]=1;
    for(int i = 1 ; i <= (n + 1) / 2 ; i++ ) {
        for(int u: v2[i]) {
            for(int uu: v3[i]) {
                int fix = en[uu];
                for(long long int k: f[fix]) {
                    if(k<n/2)continue;
                    int k1 = k - (n/2);
                    if(pw[k1]&u)dp2[u][uu]+=dp2[u-pw[k1]][uu-pw[fix]];
                    dp2[u][uu]%=mod;
                }
            }
        }
