const int MOD = 1e9+7;

int N;
int a[21][21]; // [boy-index][girl-index]
int dp[21][2100000]; // [boy-index][paired girls bitmap] => # of possible pairs
bool done[21][2100000];

LL solve(int boyIndex, const int pairedGirls = 0)
{
    LL ret = dp[boyIndex][pairedGirls];
    if (!done[boyIndex][pairedGirls]) {
        for (int girlIndex = 0, girlBit = 1; girlIndex < N; ++girlIndex, girlBit *= 2) { 
            if ((pairedGirls & girlBit) == 0 && a[boyIndex][girlIndex]) {
                //! if the girl is not paired yet and the boy and the girl are in good match,
                if (boyIndex == N-1) {
                    ++ret;
                } else {
                    ret = (ret + solve(boyIndex+1, pairedGirls|girlBit)) % MOD;        
                }
            }
        }
        dp[boyIndex][pairedGirls] = ret;
        done[boyIndex][pairedGirls] = true;
    }
    return ret;
}

