ll N, a[21][21], dp[2100000];
bool flg[2100000];

ll saiki(ll woman, ll bit) {
	if (bit == 0) return 1;
	if (flg[bit]) return dp[bit];
	flg[bit] = true;
	ll num = 0;
	rep(i, N) {
		if ((bit & (1 << i)) == 0) continue;
		if (a[i][woman - 1] == 0) continue;
		(num += saiki(woman - 1, bit - (1 << i)))%= mod;
	}
	return dp[bit] = num;
}

