using namespace std;
const int MAXN=30;
const long long int MOD=1e9+7;
const long long int MAXK=2500000;

vector<int> combinazioni[MAXN];
long long int dp[MAXN][MAXK];
int N;

long long int solve(int index, bitset<MAXN> b){
	int disponibili = b.to_ulong();
	if(index==N)
		dp[index][disponibili]=1;
	if(dp[index][disponibili]!=-1)
		return dp[index][disponibili];	
	dp[index][disponibili]=0;
	for(auto elem : combinazioni[index])
		if(!b[elem]){
			b[elem]=true;
			dp[index][disponibili]=(dp[index][disponibili]+solve(index+1,b))%MOD;
			b[elem]=false;
		}
	return dp[index][disponibili];
}

int main(){
