				combinazioni[i].push_back(j);
		}
	for(int i=0;i<=N;i++)
		for(int j=0;j<=valore;j++)
			dp[i][j]=-1;
	bitset<MAXN> b;
	b.reset();
	cout<<solve(0,valore);
}

