    static long dp[];
    static long M=(long)1e9+7;
    static long solve(int i,int mask)
    {
        if(i==n)
        {
            //System.out.println(mask);
            if(mask==((1<<n)-1))
                return 1;
            else
                return 0;
        }
        //System.out.println(i);
