                    ans[N-1][left]=1;
                    return 1;//If they are compatible return 1
                }
                else{
                    ans[N-1][left]=0;
                    return 0;//If the last 2 aren't compatible return 0
                }
            }
        }
    }
    for(int i=0;i<n;i++){
        if(left & (1ll<<i)){//If the ith women is left
