  if (dp[y][mask] != -1) return dp[y][mask];

  int ans = 0;
  for (int i = 0; i < n; i++) {
    if (mat[i][y] == 1 && ((mask & (1 << i)) == 0)) {
      mask ^= (1 << i);
      int ret = solve(y + 1, mask, mat, n);
      add(ans, ret);
      mask ^= (1 << i);
    } 
  }

  return dp[y][mask] = ans;     
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  int n;
  cin >> n;
  vector <vector <int>> mat(n, vector <int>(n));
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      cin >> mat[i][j];
    } 
  }
  dp.resize(n);
  for (int i = 0; i < n; i++) {
    int total = (1 << n);
    dp[i].resize(total);
    fill(dp[i].begin(), dp[i].end(), -1);
  } 

  int mask = 0;
  int ans = solve(0, mask, mat, n);
  cout << ans << '\n';
  return 0;
}

