namespace solver {
  using namespace std;
  typedef long long ll;

  static const int MAX = 21;
  int N, dp[MAX+1][1<<MAX];
  bool as[MAX][MAX];

  void init() {
    cin >> N;
    rep(i, N) rep(j, N) {
      cin >> as[i][j];
    }
  }

  void solve() {
    int U = (1 << N) - 1;
    dp[N][U] = 1;
    REPCM(i, N-1, 0) {
      int S = (1 << i) - 1;
      while(S <= U) {
        rep(j, N) if(as[i][j]) if(!((S>>j)&1)) {
          dp[i][S] += dp[i+1][S | (1 << j)];
          dp[i][S] %= MOD_1_000_000_007;
        }
        if(S!=0) {
          int x = S & -S;
          int y = S + x;
          S = ((S & ~y) / x >> 1) | y;
        } else S = U+1;
      }
    }
    cout << dp[0][0] << "\n";
  }
}

