map<tuple<grid,int,int>,bool> m;
map<tuple<grid,int,int>,ll> dp;
ll f(grid g,int x,int y){
  if(x==1) {
    if(g[x-1][x-1]==1)return 1LL;
    else return 0;
  }
  tuple<grid,int,int> tup=make_tuple(g,x,y);
  if(m[tup]) return dp[tup];
  m[tup]=true;
  grid t(x-1);
  for(int i = 0; i < x-1; i++){
    for(int j = 0; j < x; j++){
      if(j==y) continue;
      t[i].push_back(g[i][j]);
    }
  }
  for(int i = 0; i < x-1; i++){
    if(t[x-2][i]==1) {
      dp[tup]+=f(t,x-1,i);
      dp[tup]%=mod;
    }
  }
  return dp[tup];
}

