ll solve(int i,ll b, int n)
{
	if(dp[i][b]!=-1)
		return dp[i][b];

	if(i==n-1)
	{
		for(int j=0;j<n;j++)
		{
			if((((1<<j)&b)==0) && (c[i][j]==1))
			{
				dp[i][b] =1;
