    for(int i=0; i<N; i++)
    {
        int mask = 0;

        for(int j=0; j<N; j++)
        {
            int x;
            cin >> x;

            mask |= (1 << j) * x;
        }

        A[i] = mask;
    }

    dp[0][0] = 1;
    int prev = 0, curr = 1;

    for(int i=0; i<N; i++, swap(curr, prev))
    {
        for(int j=0; j<(1<<N); j++)
        {
            for(int k=0; k<N; k++)
                if((A[i] & (1 << k)) && (j & (1 << k)))
                {
                    dp[curr][j] += dp[prev][j ^ (1 << k)];
