using t_mat = vector<vector<int>>;

int count_matchings(const t_mat& mat) {
    int n = mat.size();
    vector<vector<int>> masks_with_size(n+1);
    for (int mask = 0; mask < (1 << n); ++mask) {
        int ones = 0;
        for (int i = 0; i < n; ++i) {
            if (mask & (1<<i)) {
                ++ones;
            }
        }
        masks_with_size[ones].push_back(mask);
    }
    vector<vector<ll>> dp(n+1, vector<ll>(1<<n));
    dp[0][0] = 1;
    for (int i = 1; i <= n; ++i) {
        for (auto mask : masks_with_size[i-1]) {
            for (int j = 0; j < n; ++j) {
                if (mask & (1<<j)) continue;
                if (!mat[i-1][j]) continue;
                int new_mask = mask | (1<<j);
                dp[i][new_mask] += dp[i-1][mask];
                dp[i][new_mask] %= MOD;
            }
        }
    }
    return dp[n][(1<<n)-1];
}

int main() {
