    t_mat mat(n, vector<int>(n));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> mat[i][j];
        }
    }
    auto res = count_matchings(mat);
    cout << res << endl;

    return 0;
}

