#include<bits/stdc++.h>
using namespace std;
#define int long long

const int N = 21;
int dp[N + 1][(1 << N) + 1];
int a[N + 1][N + 1];
#define pb push_back
vector <int> adj[N];
const int MOD = 1e9 + 7;

int recur(int id, int n, int mask, int totMask)
{
    //cout << id << " " << mask << "\n";

    if(id == n)
    {
        if(mask == totMask)
            return 1;
        return 0;
    }

    if(dp[id][mask] != -1)  
        return dp[id][mask] % MOD;

    int ways = 0;

    for(auto i : adj[id])
    {
        if(mask & (1 << i))
            continue;

        ways += recur(id + 1, n, mask | (1 << i), totMask);
    }
    return dp[id][mask] = ways % MOD;
}

