        {
            cin >> a[i][j];
            //cout << a[i][j] << "\n";
            if(a[i][j] == 1)
            {
                adj[i].pb(j);
            }
        }
    }

    int totMask = (1 << n) - 1;
    memset(dp, -1, sizeof(dp));

    cout << recur(0, n, 0, totMask) << "\n";
}

