ll solve(int **arr, int i, int mask, int n){
	// base case
	if(i == -1){
		if(mask == pow(2, n) - 1)
			return 1;
		else
			return 0;
	}

	if(dp[i][mask] != -1)
		return dp[i][mask];

	// rec case
	ll ans = 0;
	for(int j=0; j<n; j++){
