    tree<T, null_type, less<T>, rb_tree_tag, tree_order_statistics_node_update>;

void solve() {
    int n, M = 1e9 + 7;
    cin >> n;

    vector<vector<int>> a(n, vector<int>(n));

    for (auto& i : a)
        for (auto& j : i) cin >> j;

    vector<int> dp(1 << n), p2(n + 1), cnt(1 << n);
    for (int i = 0; i <= n; ++i) p2[i] = 1 << i;
    dp[0] = 1;

    queue<int> q;
    q.push(0);

    while (!q.empty()) {
        int msk = q.front(), i = cnt[msk];
        q.pop();

        if (i == n) break;
        if (!dp[msk]) continue;

        for (int j = 0; j < n; ++j) {
            if (a[i][j] && !(msk & p2[j])) {
                q.push(msk | p2[j]);
                cnt[msk | p2[j]] = cnt[msk] + 1;
                dp[msk | p2[j]] = (dp[msk | p2[j]] + dp[msk]) % M;
            }
        }
        dp[msk] = 0;
    }
    cout << dp[p2[n] - 1] << '\n';
}

