            for (int k = 0; k < N; k++) {
                if (((a[i]>>k)&1) == 0) continue;
                if ((j>>k)&1) continue;
                int next = j | (1<<k);
                dp[next] += dp[j];
                if (dp[next] > MOD) dp[next] %= MOD;
            }
        }
    }
    cout << dp[(1<<N) - 1] << endl;
}

