ll calc(int index,int mask,int& size,vector<vector<int>>& pairs,int& n){
  if(mask==size){
    return 1;
  }
   if(index>=n) return 0;
   if(dp[mask][index]!=-1) return dp[mask][index];
   ll res=0;
   for(int i=0;i<n;i++){
