int a[MAXN][MAXN];
int dp[32][MAXMASK];
int n;

int calc(int pos, int mask) {
    int &y = dp[pos][mask];
    if(y != -1) return y;
    if(pos == 0) return y = 1;
    y = 0;
    for(int i=0; i<n; ++i) {
        if((mask&(1<<i)) and a[pos][i+1]) {
            y += calc(pos-1, mask - (1<<i));
            if(y >= MOD) y -= MOD;
        }
    }
    return y;

}

