ll recur(int pos, int mask) {
    if(pos == n) {
        if(__builtin_popcount(mask) == n)
            return 1;
        return 0    ;
    }

    ll &ret = dp[pos][mask];
    if(ret != -1)
        return ret;

    ret = 0;
    for(int i = 0; i < n; ++i)
        if(G[pos][i] and not (mask & (1 << i))) {
            ret = ret + recur(pos+1, mask | (1 << i));
            if(ret > MOD)
                ret %= MOD;
        }

    return ret;
}


