vector <vector <int>> dp;

int solve(int y, int mask, vector <vector <int>> &mat, int n) {
  if (y == n) return 1;

  if (dp[y][mask] != -1) return dp[y][mask];

  int ans = 0;
  for (int i = 0; i < n; i++) {
    if (mat[i][y] == 1 && ((mask & (1 << i)) == 0)) {
      mask ^= (1 << i);
      int ret = solve(y + 1, mask, mat, n);
      add(ans, ret);
      mask ^= (1 << i);
    } 
  }

  return dp[y][mask] = ans;     
}

