ll dp(int mask, int women, vector<vector<bool>>&comp, int n, vector<vector<ll>>&save){
	if(mask == (1<<n) -1) return 1;
	else if(women >= n) return 0;
	else if(save[mask][women] != -1) return save[mask][women];

	ll res = 0;
	for(int bit = 0; bit < n; ++bit){
		if(((mask >> bit) & 1) == 0 && comp[bit][women]){
			res += dp(mask|(1<<bit), women + 1, comp, n,save);
			res %= MOD;
		}
	}
	save[mask][women] = res;
	return res;
}


