lli findAll(int x, int w, int n){
    if(x == n){
        return 1;
    }

    if(dp[x][w] != -1){
        return dp[x][w];
    }

    lli ans = 0;
    for(int i = 0; i < n; i++){
        bool avail = (((1<<i)&w) == 0) ? false : true;
        if(avail and mat[x][i]){
            ans += findAll(x + 1, (w^(1<<i)), n);
            ans %= MOD;
