ll recur(ll mask,int level,ll max_mask,int n){
    if(dp[mask][level] != -1) return dp[mask][level];
    if(mask == max_mask && level == n){
        return 1;
    }
    if(level  == n)
        return 0;
    ll ans = 0;
    for (int i = 0; i < n; ++i)
    {
        if(a[level][i] && ((1 << i) & mask) == 0){
            ans += recur(mask | (1 << i),level + 1,max_mask,n);
            ans %= mod;
        }   
    }   
    dp[mask][level] = ans;
    return ans;
}
