    {
        return 1;
    }
    if(m.find(make_pair(visit,ind))!=m.end())
      return m[make_pair(visit,ind)];

    int var=0;
    for(int i=0;i<n;i++)
    { if(arr[ind][i]==1 && visit[i]=='0')
        { visit[i]='1';
        //cout<<ind+1<<" "<<i+1<<endl;
            var=( (var%mod)+(solve(arr,n,visit,ind+1,m)%mod) )%mod;

            visit[i]='0';
        }
    }

     m[make_pair(visit,ind)]=var;
     return var;
}
