ll calc(ll men, ll mask){
	if(mask==0)return 1;
	if(dp[men][mask]!=-1)return dp[men][mask];
	ll temp=mask;
	ll shift=0;
	ll ans=0;
	while(temp>0){
		bool bit = temp&1;
		if(bit){
			if(a[men][shift+1]){
				ll newmask = mask^(1ll<<shift);
				ans=(ans+calc(men-1,newmask))%hell;	
			}
		}
		temp>>=1;
		shift++;
	}
	return dp[men][mask]=ans;
}


