    vector<vector<mint>> dp1(N / 2 + 1, vector<mint>(1 << N, 0));
    vector<vector<mint>> dp2((N + 1) / 2 + 1, vector<mint>(1 << N, 0));
    dp1[0][0] = 1;
    rep(i, 0, N / 2) rep(j, 0, 1 << N) {
        if (dp1[i][j] == 0) continue;
        rep(k, 0, N) {
            if ((j >> k) & 1 || !A[i][k]) continue;
            dp1[i + 1][j | (1 << k)] += dp1[i][j];
        }
    }
    dp2[0][0] = 1;
    rep(i, 0, (N + 1) / 2) rep(j, 0, 1 << N) {
        if (dp2[i][j] == 0) continue;
        rep(k, 0, N) {
            if ((j >> k) & 1 || !A[N / 2 + i][k]) continue;
            dp2[i + 1][j | (1 << k)] += dp2[i][j];
        }
    }
    mint ans = 0;
    rep(mask1, 0, 1 << N) {
        int mask2 = ((1 << N) - 1) ^ mask1;
        ans += dp1[N / 2][mask1] * dp2[(N + 1) / 2][mask2];
    }
    cout << ans << endl;
    return 0;
}

