            if(dp[i][j] == 0)continue;
            for(LL b : bit[i+1]){
                if((j & b) != 0)continue;
                dp[i+1][j | b] += dp[i][j];
                dp[i+1][j | b] %= MOD;
            }
        }
    }

    PUTS(dp[n-1][(1 << n)-1]);
}

