int M=1e9+7;

int solve(vector<vector<int>>& grid){
	int n=grid.size();
	vector<int> dp(1<<n);
	dp[0]=1;
	for (int mask=0;mask<(1<<n)-1;mask++){
		int a = __builtin_popcount(mask);
		for (int b=0;b<n;b++){
			if (grid[a][b] and !(mask & (1<<b))){
				int m2=mask^(1<<b);
				dp[m2]=(dp[m2]%M+dp[mask]%M)%M;
			}
		}
	}
	return dp[(1<<n)-1];
}

