long long Magic(int i, int check)
{
    if(i==n) return 1;
    if(d[i][check]) return F[i][check]; d[i][check]=1;
    long long res = 0;
    for(int j=0; j<n; j++)
    {
        if((check>>j)&1) continue;
        if(A[i][j])
            res = (res+Magic(i+1, check^(1<<j)))%1000000007;
    }
    return F[i][check]=res;
}

