	cin >> N;
	vector<vector<int>> good;   //男性、相性のいい人
	good.resize(N+1);
	for (int n = 1; n <= N; n++) {
		for (int girl = 0; girl < N; girl++) {
			int g;
			cin >> g;
			if (g == 1)good[n].push_back(girl);
		}
	}
	vector<vector<long long>> DP;
	vector<int> order((1<<N),0);
	for (int code = 0; code < (1 << N); code++) order[code] = code;
	sort(order.begin(), order.end(), [=](int code1, int code2) {
		int c1 = 0;
		for (int n = 0; n < N; n++) {
			if ((code1 & (1 << n)))c1++;
		}
		int c2 = 0;
		for (int n = 0; n < N; n++) {
			if ((code2 & (1 << n)))c2++;
		}
		return c1 < c2;
	});
	DP.resize(N + 1, vector<long long>((1 << N), 0));
	DP[0][0] = 1;
	for (int counter = 0,code = order[counter]; counter < (1 << N)-1; counter++) {
		code = order[counter];
		int n = 0;
		for (int c = 0; c < N; c++) {
			if ((code & (1 << c)))n++;
		}
		DP[n][code] %= MOD;
		for (int girl : good[n+1]) {
			if ((code & (1 << girl)))continue;   //すでに取られているので
			DP[n+1][(code | (1 << girl))] += DP[n][code];
		}
	}
	cout << DP[N][(1 << N) - 1]%MOD << endl;
	return 0;
}

