#include <bits/stdc++.h>

using namespace std;

using ll = long long;

constexpr int MAX_N = 22, MOD = 1e9 + 7;
int n;
bool a[MAX_N][MAX_N];
int dp[1 << MAX_N];

int Solve(int v, int s) {
    if (v == n) return 1;
    if (dp[s] != 0) return dp[s];

    int res = 0;
    for (int u = 0; u < n; ++u) {
        if (a[v][u] && !(s >> u & 1))
            res = (res + Solve(v + 1, s | (1 << u))) % MOD;
    }
    return dp[s] = (res % MOD);
}

