class Bits {
public:
  inline static bool included(ll S, ll v) {
    return ((S&(1<<v))>>v) == 1;
  }

  inline static ll add(ll S, ll v) {
    return S&(1<<v);
  }

  inline static ll remove(ll S, ll v) {
    return S&(~(1<<v));
  }

  inline static ll all(ll num) {
    ll a = 0;
    for (ll v=0; v<num; v++) {
      a |= (1<<v);
    }
    return a;
  }

