	if (end <= l || r <= beg) return 0;
	if (l <= beg && end <= r) return seg[i];
	sll med = (beg + end) / 2;
	sll vl = segf_(l, r, beg, med, i * 2);
	sll vr = segf_(l, r, med, end, i * 2 + 1);
	return smax(vl, vr);
}
