ll dp[21][ (1<<21) ];

ll cal(int x,int k){
	if (dp[x][k]!=-1) return dp[x][k];
	ll val = 0;
	for(int i=0;(1<<i) <= k;i++){
		if(!(k>>i&1)) continue;
		if(mx[x][i]==0) continue;
		if (x==n-1){
			val=1;
			break;
		}
		val += cal( x+1 , ( k&(~(1<<i)) ) ) ;
		if (val>mod) val-=mod;
	}
	return dp[x][k]=val;
}
