typedef long long int int64;

int popcnt(int n){
  int sum=0;
  while(n){
    sum+=n&1;
    n>>=1;
  }
  return sum;
}

void run(void){
  const int mod=1000000000+7;
  int n;
  scanf("%d",&n);
  int *a=(int *)calloc(n*n,sizeof(int));
  int i;
  for(i=0;i<n*n;i++) scanf("%d",a+i);
  int *dp=(int *)calloc(1<<n,sizeof(int));
  dp[0]=1;
  for(i=1;i<(1<<n);i++){
    int k=popcnt(i)-1;
    int local=0;
    int j;
    for(j=0;j<n;j++){
      if(((i>>j)&1)==0) continue;
      if(a[k*n+j]){
	local=(local+dp[i^(1<<j)])%mod;
      }
    }
    dp[i]=local;
  }
  printf("%d\n",dp[(1<<n)-1]);
}

int main(void){
  run();
  return 0;
}

