#define DIVISOR 1000000007

int main(void) {
    int num = get_int();
    int i, j;
    char arr[NUM_MAX+1];
    char graph[NUM_MAX+1][NUM_MAX+1];
    static uint64_t dp[NUM_MAX+1][1<<NUM_MAX];
    for(i = 1; i <= num; i++) {
        fget_array(&arr[1], num);
        for(j = 1; j <= num; j++) {
            graph[i][j] = arr[j];
        }
    }

    for(i = 0; i < num; i++) {
        dp[1][1<<i] = graph[1][i+1];
    }


    int pat, bit;
    for(pat = 1; pat < (1<<num); pat++) {
        int cnt = __builtin_popcount(pat);
        if(cnt==1) continue;
        for(bit = 0; bit < num; bit++) {
            if(!(pat & (1<<bit))) continue;
            if(!graph[cnt][bit+1]) continue;
            int npat = pat & (~(1<<bit));
            dp[cnt][pat] = (dp[cnt][pat] + dp[cnt-1][npat])%DIVISOR;
        }
#ifdef DEBUG
        printf("dp[%d][%d] = %llu\n", cnt, pat, dp[cnt][pat]);
#endif
    }
    printf("%llu\n", dp[num][(1<<num)-1]);
    return 0;
}

