typedef unsigned int uint;

static inline uint popcnt(uint n){
  uint s=n;
  s=(s&0x55555555)+((s&0xAAAAAAAA)>>1);
  s=(s&0x33333333)+((s&0xCCCCCCCC)>>2);
  s=(s&0x0F0F0F0F)+((s&0xF0F0F0F0)>>4);
  s=(s&0x00FF00FF)+((s&0xFF00FF00)>>8);
  s=(s&0x0000FFFF)+((s&0xFFFF0000)>>16);
  return s;
}

void run(void){
  const uint mod=1000000007;
  uint n;
  scanf("%u",&n);
  uint *a=(uint *)calloc(n,sizeof(uint));
  uint i,j;
  for(i=0;i<n;i++){
    for(j=0;j<n;j++){
      uint x;
      scanf("%u",&x);
      if(x) a[i]|=1<<j;
    }
  }
  uint *dp=(uint *)calloc(1<<n,sizeof(uint));
  dp[0]=1;
  for(i=1;i<(1<<n);i++){
    uint k=popcnt(i)-1;
    uint local=0;
    for(uint bit=a[k]&i;bit;bit-=bit&-bit){
      local+=dp[i^(bit&-bit)];
      if(local>=mod) local-=mod;
    }
    dp[i]=local;
  }
  printf("%d\n",dp[(1<<n)-1]);
}

int main(void){
  run();
  return 0;
}

