typedef int32_t i32;
typedef int64_t i64;

#define ALLOC(size,type) ((type*)calloc((size),sizeof(type)))

i32 popcnt (i32 bit) {
  i32 cnt = 0;
  while (bit > 0) {
    cnt += bit & 1;
    bit >>= 1;
  }
  return cnt;
}

void run (void) {
  i32 n;
  scanf ("%" SCNi32, &n);
  i32 *bit = ALLOC (n, i32);
  for (i32 i = 0; i < n; ++i) {
    for (i32 j = 0; j < n; ++j) {
      i32 b;
      scanf ("%" SCNi32, &b);
      bit[i] |= b << j;
    }
  }
  i32 *dp = ALLOC (1 << n, i32);
  const i32 mod = 1000000007;
  dp[0] = 1;
  for (i32 i = 1; i < (1 << n); ++i) {
    i32 v = popcnt (i) - 1;
    i32 b = bit[v] & i;
    i64 sum = 0;
    for (i32 j = 0; j < n; ++j) {
      if ((b >> j) & 1) {
        sum += dp[i ^ (1 << j)];
      }
    }
    dp[i] = sum % mod;
  }
  printf ("%" PRIi32 "\n", dp[(1 << n) - 1]);
}

int main (void) {
  run();
  return 0;
}

