    int[] power_two = new int[N+1];
    power_two[0] = 1;
    for (int i=1; i<=N; i++) {
      power_two[i] = power_two[i-1]*2;
    }

    int maxState = power_two[N];
    long[][] dp = new long[N+1][maxState];

    dp[0][0] = 1;

    for(int i=1; i<=N; i++) {
      for (int j=0; j<maxState; j++) {
        if (Integer.bitCount(j) != i) continue;
        int now = j & B[i-1];

        for (int k=0; k<N; k++) {
          if (now % 2 == 1) {
            dp[i][j] += dp[i-1][j-power_two[k]];
            dp[i][j] %= MOD;
          }
          now /= 2;
        }
      }
    }

