class Main{
	static int n,mat[][];
	static long ans;
	static StringBuilder allset;
	static long dp[][];
	public static void main(String[] args) throws IOException{
		BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
		int t=1;
//		Integer.parseInt(br.readLine().trim());
		OutputStream outputStream =System.out;
        PrintWriter out =new PrintWriter(outputStream);
		StringBuilder printans=new StringBuilder();
		while(t-->0)
		{
			StringTokenizer tok=new StringTokenizer(br.readLine()," ");
			n=Integer.parseInt(tok.nextToken());

			mat=new int[n][n];
			for(int i=0;i<n;i++) {
				tok=new StringTokenizer(br.readLine()," ");
				for(int j=0;j<n;j++)
					mat[i][j]=Integer.parseInt(tok.nextToken());
			}
			dp=new long[n+1][1<<n];
			memset();
			System.out.println(call(0,0));
		}

	}
	static long call(int i,int mask) {

		if(i==n) {

			if((mask&1<<n+1)==0)return 1;


			return 0;
		}
		if(dp[i][mask]!=-1)return dp[i][mask];
		long ans=0;
		for(int j=0;j<n;j++) {
			if((mask & (1<<j))==0 && mat[i][j]==1) {
				mask|=(1<<j);
				ans+=call(i+1,mask);
				mask^=(1<<j);
			}


		}
		dp[i][mask]=ans%mod;
		return ans%mod;
	}
	static void memset() {
		for(int i=0;i<dp.length;i++) {
			Arrays.fill(dp[i], -1);
		}
	}
	static int mod=(int)1e9+7;
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.HashSet;
import java.util.Scanner;
import java.util.ArrayList;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author vdewansa
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        OMatching solver = new OMatching();
        solver.solve(1, in, out);
        out.close();
    }

    static class OMatching {
        final int MOD = 1_000_000_000 + 7;

        int add(int a, int b) {
            int res = a + b;
            if (res >= MOD) {
                res -= MOD;
            }
            return res;
        }

        int setOf(int elem) {
            return 1 << (elem - 1);
        }

        boolean contains(int set, int elem) {
            return ((set >> (elem - 1)) & 1) != 0;
        }

        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int N = in.nextInt();
            ArrayList<HashSet<Integer>> a = new ArrayList<>();
            a.add(new HashSet<>());
            for (int i = 1; i <= N; i++) {
                HashSet<Integer> s = new HashSet<>();
                for (int j = 1; j <= N; j++) {
                    if (in.nextInt() > 0) {
                        s.add(j);
                    }
                }
                a.add(s);
            }
            int[][] ways = new int[N + 1][setOf(N + 1)];
            ways[0][0] = 1;
            for (int i = 1; i <= N; i++) {
                for (int j : a.get(i)) {
                    for (int oldS = 0; oldS < ways[i].length; oldS++) {
                        if (!contains(oldS, j)) {
                            int newS = oldS | setOf(j);
                            ways[i][newS] = add(ways[i][newS], ways[i - 1][oldS]);
                        }
                    }
                }
            }
            out.println(ways[N][setOf(N + 1) - 1]);
        }

    }
}

import java.util.*;
import java.io.*;
import java.lang.*;
public class Main
{
    static int n;
    static int m[][];
    static long dp[];
    static long M=(long)1e9+7;
    static long solve(int i,int mask)
    {
        if(i==n)
        {
            //System.out.println(mask);
            if(mask==((1<<n)-1))
                return 1;
            else
                return 0;
        }
        //System.out.println(i);
        if(dp[mask]!=-1)
            return dp[mask]%M;
        //dp[mask]=solve(i+1,mask);
        dp[mask]=0;
        for(int j=0;j<n;j++)
        {
            if(m[i][j]==0)
                continue;
            if((mask&(1<<j))==0)
            {
                dp[mask]=(dp[mask]%M+solve(i+1,(mask|(1<<j)))%M)%M;
            }
        }
        return dp[mask]%M;
    }
    public static void main(String args[])throws Exception
    {
        try
        {
            InputReader in = new InputReader(System.in);
            PrintWriter out = new PrintWriter(System.out);
            n=in.ni();
            m=new int[n][n];
            dp=new long[1<<n];
            Arrays.fill(dp,-1);
            for(int i=0;i<n;i++)
            {
                for(int j=0;j<n;j++)
                    m[i][j]=in.ni();
            }
            out.println(solve(0,0)%M);
            out.close();
        }
        catch(Exception e){
            return;
        }
    }
    static class InputReader {

        private final InputStream stream;
        private final byte[] buf = new byte[8192];
        private int curChar, snumChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (snumChars == -1)
                throw new InputMismatchException();
            if (curChar >= snumChars) {
                curChar = 0;
                try {
                    snumChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (snumChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int ni() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public long nl() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int[] nextIntArray(int n) {
            int a[] = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = ni();
            }
            return a;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public String nextLine() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndOfLine(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

    }
}

