           for(int i = 0; i < dp.length; i++){
               Arrays.fill(dp[i],-1);
           }

           StringTokenizer token;

           for(int i = 0; i < n; i++){
              int j = 0;
              token =  new StringTokenizer(br.readLine().trim()," ");
              while(token.hasMoreTokens()){
                  arr[i][j++] = Integer.parseInt(token.nextToken());
              }

           }


      System.out.println(solve(arr,0,0));
    }
}

