// mask :  on mean person x we can choose , off means person x is already choosen by some id s
// s is id of tshirt
long recur(int s,int mask){
    if(s<0 & mask > 0) return 0;
    if(mask==0) return 1 ;
    if(dp[s][mask]!= -1) return dp[s][mask];




    long ans = 0;
    for(int i=0;i<n;++i){
        if(adj[s][i]==1 && ((mask&(1<<i))>0) ){
            ans = (ans + recur(s-1, mask^(1<<i)))%mod;
        }
    }   
   // ans = (ans + recur(s-1,mask))%mod ;

    return dp[s][mask] = ans ;
}


long pow(long a, long b) {
    long result = 1;
    while (b > 0) {
        if (b % 2 == 1) result = (result * a) % mod;
        b /= 2;
        a = (a * a) % mod;
    }
    return result;
}

