import java.util.*;
import java.io.*;
public class Main {
    public static long dp[][];
    public static int mod = 1000000007;
    public static long solve(long arr[][] , int i , int womenSubset , int n){
        if(i == n+1){
             if(womenSubset == 0) return 1;
             else return 0;
        }

        if(dp[i][womenSubset] != -1) return dp[i][womenSubset];

        long ans = 0;
        for(int women = 0 ; women < n ; women++){
            boolean avail = ((1<<women)&womenSubset) == 0 ? false : true;
            if(avail && arr[i][women + 1] == 1){
                ans += solve(arr , i + 1 , (womenSubset^(1<<women)) , n)%mod;
            }
        }
        return dp[i][womenSubset] = ans;
    }
    public static void main(String args[]) {
        Scanner s = new Scanner(System.in);
        int n = s.nextInt();
        long arr[][] = new long[n+1][n+1];
        dp = new long[n+1][1<<n];

        for(int i = 1; i <= n ; i++){
            for(int j = 1 ; j <= n ; j++){
                arr[i][j] = s.nextInt();
            }
        }
        for(int i = 0 ; i < n+1 ; i++){
            for(int j = 0 ; j < dp[0].length ; j++){
                dp[i][j] = -1;
            }
        }
        System.out.println(solve(arr , 1 , (1<<n)-1 , n));
    }
}

import java.io.*;
import java.util.*;
import java.math.*;

public class Main {
    static int mod = (int) (1e9 + 7);
    static int total;
    static int n;
    static int[][] mapping;
    static Long[][] store;

    public static void solve() {
        n = in.nextInt();
        total = (1 << n) - 1;

        mapping = new int[n][n];
        store = new Long[(int) Math.pow(2, n)][n + 1];

        for (int i = 0; i < n; i += 1) {
            for (int j = 0; j < n; j += 1) {
                mapping[i][j] = in.nextInt();
            }
        }

        long result = calc(0, 0, store) % mod;

        out.println(result);
    }

    private static long calc(int mask, int i, Long[][] store) {
        if (mask == total)
            return 1;
        if (i == n)
            return 0;

        if (store[mask][i] != null)
            return store[mask][i];

//        long ans = calc(mask, i + 1, store);

        long ans = 0;

        for (int j = 0; j < mapping[i].length; j += 1) {
            if ((mask & (1 << j)) == 1)
                continue;

            if (mapping[i][j] == 1)
                ans += calc(mask | 1 << j, i + 1, store) % mod;
        }

        store[mask][i] = ans % mod;
        return store[mask][i];
    }


    public static InputReader in = new InputReader();
    public static PrintWriter out;

    public static void main(String[] args) {
        out = new PrintWriter(System.out);
        solve();
        out.close();
    }


    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        /**
         * When you call next(), that entire line will be skipped.
         * No flushing buffers.
         * Doesn't work when you want to scan the remaining line.
         *
         * @return entire line
         */
        public String nextLine() {
            String str = "";
            try {
                str = reader.readLine();
                tokenizer = null;
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
            return str;
        }
    }
}

