    static class CLinovaAndKingdom {

        final int MAXN = (int) (1 << 21) + 10;
        final long mod = (long) (1e9) + 7;
        long dp[] = new long[MAXN];
        int a[][] = new int[21][21];
        int n;
        int allmask;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
        	n = in.nextInt();
        	for (int i = 0; i < n; i++) {
        		for (int j = 0; j < n; j++) a[i][j] = in.nextInt();
