        int N = in.nextInt();
        boolean[][] rel = new boolean[N][N];
        for(int i = 0; i < N; i++) for(int j = 0; j < N; j++) rel[i][j] = (in.nextChar() == '1');

        ArrayList<ArrayList<Integer>> bitList = new ArrayList<>();
        for(int i = 0; i <= N; i++) bitList.add(new ArrayList<Integer>());
        for(int i = 0; i < (1<<N); i++) bitList.get(Integer.bitCount(i)).add(i);

        long[][] dp = new long[N+1][1<<N];
        dp[0][0] = 1;
        for(int i = 1; i <= N; i++){
            for(int j : bitList.get(i-1)){
                for(int k = 0; k < N; k++){
                    if((1&(j>>k)) == 0 && rel[i-1][k]){
                        dp[i][(j | (1<<k))] += dp[i-1][j];
                        dp[i][(j | (1<<k))] %= MOD;
                    }
                }
            }
        }
        out.println(dp[N][((1<<N)-1)]);
    }

