    static int solve(int m,int i,int dp[][],int mat[][],HashMap<Integer,List<Integer>> map,int mask)
    {
         if (m==mask)
             return 1;
         if (i>=mat.length)
             return 0;

         if(dp[m][i]!=0)
             return dp[m][i];
         int ans=0;
         for(int j: map.get(i))
         {
             if ( (m & (1<<j)) == 0)
             {
                 ans+= solve(m|(1<<j),i+1,dp,mat,map,mask);
                 if(ans>mod)
                     ans-=mod;
             }
             else
             {
                 continue;
             }

         }
         dp[m][i] = ans;
         return ans;
    }




