        return n & ~(1l << bit);
    }

    public static int clear(int n, int bit) {
        return n & ~(1 << bit);
    }

    public static long clear(long n, int from, int to) {
        return n & ~(LONG_MASK[to - from] << from);
    }

    public static int clear(int n, int from, int to) {
        return n & ~(INT_MASK[to - from] << from);
    }

