	static long call(int i,int mask) {

		if(i==n) {

			if((mask&1<<n+1)==0)return 1;


			return 0;
		}
		if(dp[i][mask]!=-1)return dp[i][mask];
		Long ans=0l;
		for(int j=0;j<n;j++) {
			if((mask & (1<<j))==0 && mat[i][j]==1) {
				mask|=(1<<j);
				ans+=call(i+1,mask);
				mask^=(1<<j);
			}


		}
		dp[i][mask]=ans%mod;
		return ans%mod;
	}
	static void memset() {
		for(int i=0;i<dp.length;i++) {
			Arrays.fill(dp[i], -1);
		}
	}
