public class Solution{
	static int n;
	static int[][] matrix;
	static int mod=(int)1e9+7;
	static int dp[][];
	public static int solve(int i,int mask){
		if(i==n){

			if(mask==0)
				return 1;
			return 0;
		}
		if(dp[i][mask]!=-1){
			return dp[i][mask];
		}
		int ans=0;

		for(int j=0;j<n;j++){
			int avai=mask&(1<<(j));
			if(matrix[i][j]==1&&avai!=0){
				ans=(ans+solve(i+1,mask&(~(1<<j))))%mod;

			}
		}
		return dp[i][mask]=ans;

	}
