    static class OMatching {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();
            long mod = (long) 1e9 + 7, ans = 0;
            int[][] grid = new int[n][n];
            long[][] dp = new long[n][n];
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n; j++)
                    grid[i][j] = in.nextInt();
