    }

    static class OMatching {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            final int MOD = (int) 1e9 + 7;

            int n = in.nextInt();
            char[][] a = new char[n][n];
            for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) a[i][j] = in.nextCharacter();

            int[] dp = new int[1 << n];
            dp[0] = 1;
            for (int mask = 0; mask < (1 << n) - 1; mask++) {
                int boy = Integer.bitCount(mask);
                for (int girl = 0; girl < n; girl++) {
                    if (((mask >> girl) & 1) == 0 && a[boy][girl] == '1') {
                        int newState = mask ^ (1 << girl);
                        dp[newState] += dp[mask];
                        if (dp[newState] >= MOD) dp[newState] -= MOD;
                    }
                }
            }

            out.println(dp[(1 << n) - 1]);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public char nextCharacter() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            return (char) c;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

