public class Main {
  private static final long MOD = 1_000_000_007L;

  private static long solve(int n, int[][] am) {
    int limit = 1 << n;
    long[] map = new long[limit];
    map[limit - 1] = 1L;
    for (int[] as : am) {
      long[] nextMap = new long[limit];
      for (int bitset = 0; bitset < limit; bitset++) {
        if (map[bitset] == 0) {
          continue;
        }
        for (int i = 0; i < n; i++) {
          if (as[i] == 1 && ((bitset >> i) & 1) == 1) {
            int nextBitset = bitset ^ (1 << i);
            nextMap[nextBitset] = (nextMap[nextBitset] + map[bitset]) % MOD;
          }
        }
      }
      map = nextMap;
    }
    return map[0];
  }

  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int[][] am = reader.nextInt(n, n);
    out.println(solve(n, am));
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

