	public void solve() {
		int n = in.nextInt();
		int max = 1 << n;
		long[] dp = new long[max];
		boolean[][] a = new boolean[n][n];
		for (int i = 0; i < a.length; i++) {
			for (int j = 0; j < a.length; j++) {
				a[i][j] = in.nextInt() == 1;
			}
		}
		dp[0] = 1;
		for (int i = 0; i < max - 1; i++) {
			int sum = 0;
			for (int j = 0; j < n; j++) {
				if ((i & (1 << j)) > 0) {
					sum++;
				}
			}
			for (int j = 0; j < n; j++) {
				if (a[sum][j] && ((i & (1 << j)) == 0)) {
					dp[i | (1 << j)] += dp[i];
					dp[i | (1 << j)] %= mod;
				}
			}
		}
		out.print(dp[max - 1]);
	}

