/**
 *
 * Let dp[mask] be the number of ways to find graph matchings between 1,..,x to mask
 * Where x is # of bits in mask
 * For all x,v connected and v in mask
 * We get dp[mask^(1<<v)] ways 
 */
public class Main {

    static int MOD=1000000007;
    public static void main(String[] args) throws IOException {
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        int N=Integer.parseInt(br.readLine());
        boolean[][] arr=new boolean[N][N];
        for (int i = 0; i < N; i++) {
            StringTokenizer st=new StringTokenizer(br.readLine());
            for (int j = 0; j < N; j++) {
                if(Integer.parseInt(st.nextToken())==1){
                    arr[i][j]=true;
                }
            }
        }
        int[] dp=new int[1<<N];  dp[0]=1;int x=0;
        for (int mask = 1; mask < (1<<N); mask++) {
            x=-1;
            for (int j = 0; j < N; j++) {
                if((mask&(1<<j))>0){
                    x++;
                }
            }
            //Go from x to x-1
            for (int i = 0; i < N; i++) {
                if((mask&(1<<i))>0 && arr[i][x]){
                    dp[mask]+=dp[mask^(1<<i)];
                    dp[mask]%=MOD;
                }
            }
        }
        System.out.println(dp[(1<<N)-1]);
    }

}

import java.io.*;
import java.util.*;

public class Main{


	static int MOD=(int)1e9+7;
	static int n;
	static int []memo;
	static boolean [][]a;
	static int dp(int idx,int msk) {
		if(idx==n)
			return 1;
		if(memo[msk]!=-1)
			return memo[msk];
		int ans=0;
		for(int i=0;i<n;i++)
			if(a[idx][i] && ((msk & (1<<i)) ==0))
			{
				ans=ans+dp(idx+1,msk|1<<i);
				if(ans>=MOD)
					ans-=MOD;
			}
		return memo[msk]=ans;
	}
	public static void main(String[] args) throws IOException {
		Scanner sc=new Scanner();
		PrintWriter out=new PrintWriter(System.out);
		n=sc.nextInt();
		a=new boolean[n][n];
		memo=new int [1<<n];
		Arrays.fill(memo, -1);
		for(int i=0;i<n;i++)
			for(int j=0;j<n;j++)
				a[i][j]=sc.nextInt()==1;
		out.println(dp(0, 0));

		out.close();
	}

	static class Scanner
	{
		BufferedReader br;
		StringTokenizer st;
		Scanner(){
			br=new BufferedReader(new InputStreamReader(System.in));
		}
		Scanner(String fileName) throws FileNotFoundException{
			br=new BufferedReader(new FileReader(fileName));
		}
		String next() throws IOException {
			while(st==null || !st.hasMoreTokens())
				st=new StringTokenizer(br.readLine());
			return st.nextToken();
		}
		String nextLine() throws IOException {
			return br.readLine();
		}
		int nextInt() throws IOException{
			return Integer.parseInt(next());
		}
		long nextLong()  throws NumberFormatException, IOException {
			return Long.parseLong(next());
		}
		double nextDouble() throws NumberFormatException, IOException {
			return Double.parseDouble(next());
		}
	}
}

