        for(int i=0;i<n;i++) {
        	for(int j=0;j<n;j++)
        	arr[i][j]=Reader.nextInt();
        }
        for(int i=0;i<l;i++) {
        	for(int j=0;j<n;j++) {
        		dp[i][j]=-1;
        	}
        }
        Main mm=new Main();
        System.out.println(mm.dp(arr, dp,((int)Math.pow(2, n))-1,0, n));

	}
}
