        for(int i=0;i<n;i++)
         for(int j=0;j<n;j++)
         {
             mat[i][j] = f.nextInt();

         }
        int mask = (1<<n)-1;
        int dp[][]= new int[mask+1][n];
        System.out.println(solve(0,0,dp,mat,mask));



    }

    static int solve(int m,int i,int dp[][],int mat[][],int mask)
    {
         if (m==mask)
             return 1;
         if (i>=mat.length)
             return 0;

         if(dp[m][i]!=0)
             return dp[m][i];
         int ans=0;
         for(int j=0;j<mat.length;j++)
         {
             if (mat[i][j] ==1)
             {
                 if ( (m & (1<<j)) == 0)
                 {
                     ans+= solve(m|(1<<j),i+1,dp,mat,mask);
                     if(ans>mod)
                         ans-=mod;
                 }
                 else
                 {
                     continue;
                 }
             }
         }

         dp[m][i] = ans;
         return ans;
    }




