        for (int k=0; k<N; k++) {
          if (now % 2 == 1 && A[i-1][k] == 1) {
            dp[i][j] += dp[i-1][j-(int)Math.pow(2, k)];
            dp[i][j] %= MOD;
          }
          now /= 2;
        }
      }
    }

