	static long solve(int i,int mask) {
		long tr=0;
		if(i==n) {
			if(mask==(1<<n)-1) return 1;
			else return 0;
		}
		if(vis[i][mask]==1) return dp[i][mask];

		vis[i][mask]=1;
		for(int j=0;j<n;j++) {
			if(arr[i][j]==1 && ( mask &(1<<j))==0){
				tr+=solve(i+1,mask|(1<<j));
				tr%=mod;
			}
		}
		tr%=mod;
		dp[i][mask]=tr;
		return tr;
	}

