		n = ni();
		a = na(n, n);

		dp = new long[n][1 << n];

		for (int i = 0; i < n; i++)
			Arrays.fill(dp[i], -1);

		out.println(solve(0, (1 << n) - 1));
	}

	private long solve(int i, int f) {
		if (i >= n)
			return 1;
		if (dp[i][f] == -1) {
			dp[i][f] = 0;
			for (int j = 0; j < n; j++) {
				if ((f & (1 << j)) != 0 && a[i][j] == 1) {
					dp[i][f] += solve(i + 1, f & (~(1 << j)));
					dp[i][f] %= MOD;
				}
			}
		}
		return dp[i][f];
	}

