public class Main {
    public static int solve(int arr[][] , int n){
        if(arr.length == 1){
            return arr[0][0];
        }

        int ans = 0;
        for(int i = 0 ; i < n ; i++){
            if(arr[i][0] == 1){
                int arr1[][] = new int[n-1][n-1];
                for(int j = 0, l = 0; j < n ; j++ , l++){
