public class Main {

    static int N;
    static int[][] A;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        A = new int[N][];
        for (int i = 0; i < N; i++) {
            A[i] = sc.nextIntArray(N);
        }

        System.out.println(solve());
    }

    static int MOD = 1_000_000_007;

    static int solve() {
        int[] dp = new int[1 << N];
        dp[0] = 1;

        for (int i = 0; i < N; i++) {
            for (int s = 0; s < 1 << N; s++) {
                if( Integer.bitCount(s) != i ) continue;

                for (int j = 0; j < N; j++) {
                    if( A[i][j] == 0 ) continue;

                    int s1 = s | (1 << j);
                    if( s1 != s ) {
                        dp[s1] += dp[s];
                        dp[s1] %= MOD;
                    }
                }
            }
        }

        return dp[(1 << N) - 1];
    }

