public class Main {

    static long mod = (long) (1e9 + 7);

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        int n = in.nextInt();
        int[][] a = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                a[i][j] = in.nextInt();
            }
        }

        long[] dp = new long[1 << n];
        dp[0] = 1;
        for (int mask = 0; mask < (1 << n) - 1; mask++) {
            int j = countSetBits(mask);
            for (int k = 0; k < n; k++) {
                if (((mask) & (1 << k)) == 0 && a[j][k] == 1) {
                    int mask2 = mask ^ (1 << k);
                    dp[mask2] = (dp[mask2] + dp[mask]) % mod;
                }
            }
        }
        out.println(dp[(1 << n) - 1]);
        out.close();
    }

    static int countSetBits(int n) {
        int count = 0;
        while (n > 0) {
            count += n & 1;
            n >>= 1;
        }
        return count;
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

    }
}

import java.util.Scanner;

public class Main {

	static int n;
	static long[][] dp;
	static int[][] matchingArray;

	static final long DIVIDE_NUMBER = 1000000007;

	public static void main(String[] args) {

		Scanner scan = new Scanner(System.in);

		n = scan.nextInt();

		matchingArray = new int[n][n];

		for (int i = 0; i < n; i++) {

			for (int j = 0; j < n; j++) {

				matchingArray[i][j] = scan.nextInt();
			}
		}

		int allPattern = (int) Math.pow(2, n);

		dp = new long[n + 1][allPattern];

		for (int i = 0; i < n + 1; i++) {

			for (int j = 0; j < allPattern; j++) {

				dp[i][j] = Long.MAX_VALUE;
			}
		}

		dp[0][0] = 1;

		long answer = dpMethod(n, allPattern - 1);

		println(answer);
	}

	public static long dpMethod(int targetN, int pattern) {

		if (dp[targetN][pattern] != Long.MAX_VALUE) {

			return dp[targetN][pattern];

		} else {

			long result = 0;

			for (int i = 0; i < n; i++) {

				if (matchingArray[targetN - 1][i] == 1) {

					if ((pattern >>> i & 1) == 1) {

						result += dpMethod(targetN - 1, pattern ^ 1 << i);
					}
				}
			}

			result = result % DIVIDE_NUMBER;
			dp[targetN][pattern] = result;
			return result;
		}
	}

	public static void println(Object target) {
		System.out.println(target);
	}
}

