    static long form_pair_with(int man, int mask, int n, long dp[][], int arr[][]){

        if(mask == (1 << n) - 1)
            return 1l;

        if(man == n + 1)
            return mask == (1 << n) - 1 ? 1l : 0l;

        if(dp[man][mask] != -1)
            return dp[man][mask];

        long res = form_pair_with(man + 1, mask, n, dp, arr); // don't form a pair with this 'man'
        int tmp = mask;

        for(int woman = 1; woman <= n; woman++){
            if((tmp & 1) == 0 && arr[man][woman] == 1)
                res += form_pair_with(man + 1, mask | (1 << (woman - 1)), n, dp, arr);

            res %= mod;
            tmp /= 2l;
        }

        return dp[man][mask] = res;
