public class Main {
    int INF = (int)1e9;
    long MOD = 1000000007;

    long[][] dp;
    boolean[][] vis;

    long go(int[][] a, int n, int i, int m) {
        if(i==n) {
            return 1;
        }
        if(dp[m][i]!=-1) return dp[m][i];
        long rs = 0;
        for(int j=0; j<n; j++) {
            int x = (1<<j);
            if(a[i][j]==1 && (m&x)==0) {
                m = m ^ x;
                rs += go(a, n, i+1, m);
                rs %= MOD;
                m = m ^ x;
            }
        }
        // vis[m][i] = true;
        return dp[m][i] = rs;
    }

    void solve(InputReader in, PrintWriter out) throws IOException {
        int n = in.nextInt();
        int[][] a = new int[n][n];
