        dp = new long[1<<n][n];
        // vis = new boolean[1<<n][n];
        for(int i=0; i<(1<<n); i++) {
            Arrays.fill(dp[i], -1);
        }
        long rs = go(a, n, 0, 0);
        out.println(rs);
    }


