class SolO {
    int n;
    int[][] match;
    int[] dp;
    int mod = 1000000007;

    SolO(int n){
        this.n = n;
        match = new int[n][n];
        dp = new int[1<<n];
        Arrays.fill(dp, -1);
    }

    int sol(int id, int mask){
        if(id < 0)
            return 1;
        if(dp[mask] >= 0)
            return dp[mask];
        long res = 0;
        for(int i = 0; i < n; ++i){
            if((mask & (1<<i)) != 0 && match[id][i] == 1){
                res += sol(id-1, mask^(1<<i));
                if(res >= mod)
                    res-= mod;
            }
        }
        return dp[mask] = (int) res;
    }

}

