        private static void SolveCase()
        {
            const long MOD = 1000000000 + 7;

            int n = ReadInt();
            bool[,] a = new bool[n, n];
            for (int i = 0; i < n; i++)
            {
                for (int j = 0; j < n; j++)
                {
                    a[i, j] = (ReadInt() == 1);
                }
            }

            int m = (1 << n);
            long[] b = new long[m];
            b[0] = 1;
            bool[] u = new bool[m];
            List<int> cur = new List<int> { 0 };
            for (int i = 0; i < n; i++)
            {
                long[] c = new long[m];
                List<int> next = new List<int>();
                for (int j = 0; j < n; j++)
                {
                    if (a[i, j])
                    {
                        for (int l = 0; l < cur.Count; l++)
                        {
                            int k = cur[l];
                            if ((k & (1 << j)) == 0)
                            {
                                int d = k | (1 << j);
                                c[d] += b[k];
                                if (c[d] >= MOD)
                                {
                                    c[d] -= MOD;
                                }
                                if (!u[d])
                                {
                                    u[d] = true;
                                    next.Add(d);
                                }
                            }
                        }
                    }
                }

                cur = next;

                b = c;
            }

            long ans = b[m - 1];

            Writer.WriteLine(ans);
        }

