class Program
{
    static void Main(string[] args)
    {
        var N = sc.ReadInt();
        var A = new long[N];
        for (int i = 0; i < N; i++)
        {
            for (int j = 0; j < N; j++)
            {
                var s = sc.ReadStr();
                if (s == "1") A[i] += 1 << j;
            }
        }

        var dp = new long[N + 1, 1 << N];
        dp[0, 0] = 1;

        // dp[i, j] = 男性iまでをマッチングさせたときに状態jである場合の数
        // 計算量: 21*21*10^6くらい

        for (int i = 0; i < N; i++)
        {
            for (int j = 0; j < 1 << N; j++)
            {
                if (dp[i, j] == 0) continue;
                for (int k = 0; k < N; k++)
                {
                    if ((j >> k) % 2 == 0
                        && (A[i] >> k) % 2 == 1)
                    {
                        var nj = j | (1 << k);
                        dp[i + 1, nj] += dp[i, j];
                        dp[i + 1, nj] %= (int)1e9 + 7;
                    }
                }
            }
        }

        var ans = dp[N, (1 << N) - 1];
        Console.WriteLine(ans);
    }
    static Scanner sc = new Scanner();
}
