public class Solver
{
	public void Solve()
	{
		long N = GetLong();
		var a = new long[N, N];
		for(long i = 0; i < N; i++)
		{
			for(long j = 0; j < N; j++)
				a[i, j] = GetLong();
		}

		long U = leftShift(1, N);
		var dp = new MInt[N + 1, U];
		for(long i = 0; i < N; i++)
		{
			if(a[0, i] == 1)
				dp[1, leftShift(1, i)] = new MInt(1);
		}
		for(long i = 1; i < N; i++)
		{
			for(long s = leftShift(1, i) - 1; s < U; s = nextCombination((int)s))
			{
				for(long j = 0; j < N; j++)
				{
					if(!contains(s, j) && a[i, j] == 1)
						dp[i + 1, s | leftShift(1, j)] += dp[i, s];
				}
			}
		}
		WriteLine(dp[N, U - 1].Val);
	}
}

public struct MInt
{
	private const long MOD = 1000000007;
	private static MInt[] f = null;
	private static MInt[] g = null;
	public long Val { get; private set; }

	public MInt(long v)
	{
		Val = (v + MOD) % MOD;
	}

	public static void InitTable(int N) => InitTable((long)N);
	public static void InitTable(long N)
	{
		f = new MInt[N + 1];
		f[0] = new MInt(1);
		for(long i = 1; i <= N; i++)
			f[i] = f[i - 1] * i;

		g = new MInt[N + 1];
		g[N] = MPow(f[N], MOD - 2);
		for(long i = N; i > 0; i--)
			g[i - 1] = g[i] * i;
	}

	public static MInt MComb(long n, long k)
	{
		if(n < 0 || n < k)
			return new MInt(0);

		return f[n] * g[k] * g[n - k];
	}

	public static MInt operator+(MInt x, long y) => x + new MInt(y);	
	public static MInt operator+(long x, MInt y) => new MInt(x) + y;
	public static MInt operator+(MInt x, MInt y)
	{
		long tmp = x.Val + y.Val;
		if(tmp >= MOD)
			tmp -= MOD;
		return new MInt(tmp);
	}

	public static MInt operator-(MInt x, long y) => x - new MInt(y);
	public static MInt operator-(long x, MInt y) => new MInt(x) - y;
	public static MInt operator-(MInt x, MInt y)
	{
		long tmp = x.Val;
		if(tmp < y.Val)
			tmp += MOD;
		tmp -= y.Val;
		return new MInt(tmp);
	}

	public static MInt operator*(MInt x, MInt y) => new MInt((x.Val * y.Val) % MOD);
	public static MInt operator*(MInt x, long y) => x * new MInt(y);
	public static MInt operator*(long x, MInt y) => new MInt(x) * y;

	public static MInt operator/(MInt x, MInt y) => x * MPow(y, MOD - 2);
	public static MInt operator/(MInt x, long y) => x * MPow(y, MOD - 2);
	public static MInt operator/(long x, MInt y) => x * MPow(y, MOD - 2);

	public static MInt MPow(MInt x, MInt y) => MPow(x.Val, y.Val);
	public static MInt MPow(MInt x, long y) => MPow(x.Val, y);
	public static MInt MPow(long x, MInt y) => MPow(x, y.Val);
	public static MInt MPow(long x, long y)
	{
		long exp = y;
		long xx = x;
		long res = 1;
		while(exp > 0)
		{
			if((exp & 1) == 1)
				res = (res * xx) % MOD;

			xx = (xx * xx) % MOD;
			exp >>= 1;
		}
		return new MInt(res);
	}
}

public static class BinaryRepresentation
{
	/*
	* initialize: array = { 0, 1, 2, ..., N - 1 } 
	* do { ... } while(nextPermutarion(ref array));
	*/
	public static bool nextPermutation(ref int[] array)
	{
		int len = array.Length;
		int i = len - 2;
		while((i >= 0) && (array[i] > array[i + 1]))
			i--;
		if(i < 0)
			return false;

		int pivot = array[i];
		int j = i + 1;
		while((j < len - 1) && (array[j + 1] > pivot))
			j++;

		int tmp = array[i];
		array[i] = array[j];
		array[j] = tmp;

		Array.Reverse(array, i + 1, len - i - 1);

		return true;
	}

	/* 
	* nCk
	* initialize: comb = (1 << k) - 1
	* while(comb < (1 << n)) { ...; comb = nextCombination(comb); };
	*/
	public static int nextCombination(int comb)
	{
		int x = comb & -comb;
		int y = comb + x;
		return (((comb & ~y) / x) >> 1) | y;
	}

	public static int popcnt(int v) {
		v = v - ((v >> 1) & 0x55555555);
		v = (v & 0x33333333) + ((v >> 2) & 0x33333333);
		return ((v + (v >> 4) & 0xF0F0F0F) * 0x1010101) >> 24;
	}

	public static long popcnt(long v) {
		v = v - ((v >> 1) & 0x5555555555555555);
		v = (v & 0x3333333333333333) + ((v >> 2) & 0x3333333333333333);
		return ((v + (v >> 4) & 0xF0F0F0F0F0F0F0F) * 0x101010101010101) >> 56;
	}
}

