	void Solve()
	{
		var N = F;
		var a = new bool[N, N];
		for (var i = 0; i < N; i++)
		{
			var I = G;
			for (var j = 0; j < N; j++) a[i, j] = I[j] > 0;
		}
		var dp = new long[1 << N];
		dp[0] = 1;
		for (var s = 1u; s < (1 << N); s++)
		{
			var n = BitCount(s);
			for (var j = 0; j < N; j++) if ((s & (1 << j)) != 0 && a[n - 1, j]) dp[s] = (dp[s] + dp[s ^ (1 << j)]) % MOD;
		}
		WriteLine(dp[(1 << N) - 1]);
	}
	public static int BitCount(uint n)
	{
		n = (n & 0x55555555) + ((n >> 1) & 0x55555555);
		n = (n & 0x33333333) + ((n >> 2) & 0x33333333);
		n = (n & 0x0f0f0f0f) + ((n >> 4) & 0x0f0f0f0f);
		n = (n & 0x00ff00ff) + ((n >> 8) & 0x00ff00ff);
		return (int)((n & 0x0000ffff) + ((n >> 16) & 0x0000ffff));
	}
