    class EDPC_O
    {
        static int mod = 1000000007;

        public static void Main()
        {
            var n = int.Parse(Console.ReadLine());

            var a = new bool[n][];
            for (int i = 0; i < n; i++)
                a[i] = Console.ReadLine().Split(' ').Select(s => s == "1").ToArray();


            var dp = new int[n + 1, 1 << n];
            dp[0, 0] = 1;
            for (int i = 0; i < n; i++)
            {
                for (int j = 0; j < 1 << n; j++)
                {
                    for (int k = 0; k < n; k++)
                    {
                        if (!a[i][k])
                            continue;
                        int l = j | (1 << k);
                        if (l == j)
                            continue;
                        dp[i + 1, l] = (dp[i + 1, l] + dp[i, j]) % mod;
                    }
                }
            }
            Console.WriteLine((dp[n, (1 << n) - 1] + mod) % mod);
        }
    }
