namespace AtCorders
{
	public class Program
	{
		static long P = (long)(1e9 + 7);
		static void Main(string[] args)
		{
			int n = int.Parse(Console.ReadLine());
			var a = new int[n, n];
			for (int i = 0; i < n; i++) {
				var temp = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
				for (int j = 0; j < n; j++) {
					a[i, j] = temp[j];
				}
			}

			var bit = new int[n];
			for (int i = 0; i < n; i++) {
				bit[i] = 1 << i;
			}

			int max = 1 << n;
			var dp = new long[max];
			for (int i = 0; i < n; i++) {
				var dst = new long[max];
				for (int j = 0; j < n; j++) {
					if (a[i, j] == 0) {
						continue;
					}

					for (int k = 0; k < 1 << n; k++) {
						if ((bit[j] & k) != 0 || dp[k] == 0) {
							continue;
						}

						dst[k | (1 << j)] += dp[k];
						if (dst[k | bit[j]] >= P) {
							dst[k | bit[j]] -= P;
						}
					}

					dst[bit[j]] += 1;
					if (dst[bit[j]] >= P) {
						dst[bit[j]] -= P;
					}
				}

				dp = dst;
			}

			long ans = dp[max - 1];
			Console.WriteLine(ans);
		}
	}
}

