    dp[0] = 1;
    long mod = 1000000007;
    int[,] matrix = new int[n,n];//行列

    for(int i = 0; i < n; i++)//それぞれの行
    {
    	int[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),int.Parse);
