internal partial class Solver {
    public void Run() {
        var n = ni();
        var a = new int[n, n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                a[i, j] = ni();
            }
        }
        int mod = 1000000007;
        var dp = new long[1 << n]; // man bit
        dp[0] = 1;
        for (int j = 0; j < dp.Length; j++) {
            int pair = PopCount((ulong)j);
            if (pair == n) continue;

            for (int k = 0; k < n; k++) {
                if (a[pair, k] == 1) {
                    if ((j & (1 << k)) != 0) continue;
                    dp[j | (1 << k)] += dp[j];
                    dp[j | (1 << k)] %= mod;
                }
            }
        }

        cout.WriteLine(dp[(1 << n) - 1]);
    }

    private static int PopCount(ulong x) {
        x = (x & 0x5555555555555555UL) + ((x >> 1) & 0x5555555555555555UL);
        x = (x & 0x3333333333333333UL) + ((x >> 2) & 0x3333333333333333UL);
        x = (x + (x >> 4)) & 0x0f0f0f0f0f0f0f0fUL;
        x += x >> 8;
        x += x >> 16;
        x += x >> 32;
        return (int)(x & 0x7FLU);
    }

}

