namespace Contest
{
    class Program
    {
        private Scanner sc;
        private int N;
        private bool[] A;
        private long Mod = 1000000007;
        private long[] Memo;
        private int loop;
        public void Solve()
        {
            sc = new Scanner();
            N = sc.NextInt();
            A = new bool[N * N];
            loop = 1 << N;
            Memo = new long[N * loop];
            for (int i = 0; i < N; i++)
            {
                for (int j = 0; j < N; j++)
                {
                    A[ConvertA(i, j)] = sc.Next() == "1";
                }

                for (int j = 0; j < loop; j++)
                {
                    Memo[ConvertMemo(i, j)] = -1;
                }
            }
            Console.WriteLine(Calc(0, loop - 1));
        }

        /// <summary>
        /// 
        /// </summary>
        /// <param name="i">i人目見てる</param>
        /// <param name="state">残ってる女性(bit)</param>
        /// <returns></returns>
        private long Calc(int i, int state)
        {
            if (i == N) return 1;
            if (Memo[ConvertMemo(i, state)] != -1)
            {
                return Memo[ConvertMemo(i, state)];
            }

            long res = 0;
            int bit = 1;
            for (int j = 0; j < N; j++)
            {
                if ((state & bit) > 0 && A[ConvertA(i, j)])
                {
                    res += Calc(i + 1, state - bit);
                    res %= Mod;
                }

                bit <<= 1;
            }

            Memo[ConvertMemo(i, state)] = res;
            return res;
        }

        private int ConvertA(int i, int j)
        {
            return i * N + j;
        }

        private int ConvertMemo(int i, int j)
        {
            return i * loop + j;
        }


        static void Main() => new Program().Solve();
    }
}

