class Program
{
    static void Main(string[] args)
    {
        var N = sc.ReadInt();
        var A = new long[N];
        for (int i = 0; i < N; i++)
        {
            for (int j = 0; j < N; j++)
            {
                var s = sc.ReadStr();
                if (s == "1") A[i] += 1 << j;
            }
        }

        var dp = new long[1 << N];
        dp[0] = 1;
        for (int i = 0; i < 1 << N; i++)
        {
            var ai = PopulationCount(i);
            if (ai == N) continue;
            for (int j = 0; j < N; j++)
            {
                if ((A[ai] >> j) % 2 == 1 && ((i >> j) & 1) == 0)
                {
                    var ni = i | (1 << j);
                    dp[ni] += dp[i];
                    dp[ni] %= (int)1e9 + 7;
                }
            }
        }


        var ans = dp[(1 << N) - 1];
        Console.WriteLine(ans);
    }

    static int PopulationCount(long x)
    {
        var count = 0;
        for (; x > 0; x &= x - 1) count++;
        return count;
    }
    static Scanner sc = new Scanner();
}
