	public class Program
	{
		static long P = (long)(1e9 + 7);
		static void Main(string[] args)
		{
			int n = int.Parse(Console.ReadLine());
			var a = new int[n, n];
			for (int i = 0; i < n; i++) {
				var temp = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
				for (int j = 0; j < n; j++) {
					a[i, j] = temp[j];
				}
			}

			var dp = new long[1 << n];
			for (int i = 0; i < n; i++) {
				var dst = new long[1 << n];
				for (int j = 0; j < n; j++) {
					if (a[i, j] == 0) {
						continue;
					}

					for (int k = 0; k < 1 << n; k++) {
						if (((1 << j) & k) != 0 || dp[k] == 0) {
							continue;
						}

						dst[k | (1 << j)] += dp[k];
						if (dst[k | (1 << j)] >= P) {
							dst[k | (1 << j)] -= P;
						}
					}

					dst[1 << j] += 1;
					if (dst[1 << j] >= P) {
						dst[1 << j] -= P;
					}
				}

				dp = dst;
			}

			long ans = dp[(1 << n) - 1];
			Console.WriteLine(ans);
		}
	}
}

