        public static long GetAns(int n, List<List<int>> a)
        {
            return GetAns(0, 0xFFFFFF, n, a);
        }

        static Dictionary<int, long> memo = new Dictionary<int, long>();
        public static long GetAns(int i, int s, int n, List<List<int>> a)
        {
            var mod = 1000000007L;
            var ret = 0L;
            var key = s;
            if (memo.ContainsKey(key)) return memo[key];

            if (i == n - 1)
            {
                for (int j = 0; j < n; j++)
                {
                    if ((s >> j) % 2 == 1 && a[i][j] == 1)
                    {
                        ret++;
                        ret %= mod;
                    }
                }
            }
            else
            {
                for (int j = 0; j < n; j++)
                {
                    if ((s >> j) % 2 == 1 && a[i][j] == 1)
                    {
                        var newS = s ^ (1 << j);
                        ret += GetAns(i + 1, newS, n, a);
                        ret %= mod;
                    }
                }
            }

            memo[key] = ret;
            return ret;
        }
    }

