        a = Enumerable.Repeat(0, num).Select(_ => Input.ar).ToArray();
        memo = Enumerable.Repeat(-1L, (1 << num)).ToArray();
        memo[0] = 1;
        WriteLine(dfs((1 << num) - 1, 0));
