    static long dfs(int num,int c)
    {
        if (memo[num] != -1) return memo[num];
        var res = 0L;
        for (var i = 0; i < a.Length; i++)
            if ((1&num >> i) == 1 && a[c][i] == 1)
                res = (res + dfs(num ^ (1 << i), c + 1)) % Input.MOD;
        return memo[num] = res;
    }
