import "fmt"

var popcntCache [256]byte

func popcntInit() {
	for i := range popcntCache {
		popcntCache[i] = popcntCache[i>>1] + byte(i&1)
	}
}

func popcnt(mask uint) byte {
	// mask < (1<<21) so we need to check only 3 bytes
	return popcntCache[byte(mask)] + popcntCache[byte(mask>>8)] + popcntCache[byte(mask>>16)]
}

func matching(n uint, m [21][21]uint) uint32 {
	const mod = 1e9 + 7
	maxmask := uint(1) << n
	d := make([]uint32, maxmask)
	d[0] = 1

	for mask := uint(1); mask < maxmask; mask++ {
		x := popcnt(mask) - 1
		for y := uint(0); y < n; y++ {
			ymask := uint(1) << y
			if ymask&mask != 0 && m[x][y] == 1 {
				d[mask] = (d[mask] + d[mask&^ymask]) % mod
			}
		}
	}
	return d[maxmask-1]
}

func main() {
	popcntInit()
	var n, x uint
	fmt.Scan(&n)
	var m [21][21]uint
	for i := uint(0); i < n; i++ {
		for j := uint(0); j < n; j++ {
			fmt.Scan(&x)
			m[i][j] = x
		}
	}
	fmt.Println(matching(n, m))
}

