func dfs(A[][]int, i int, mask int, dp[][]int) int {
	N := len(A)
	if i == N {
		return 1
	}

	if dp[i][mask] > 0 {
		return dp[i][mask]
	}

	ans := 0
	for j:=0; j<N; j++ {
		if mask & (1<<uint(j)) != 0 {
			continue
		}
		if A[i][j] == 0 {
			continue
		}
		mask = mask | (1<<uint(j))
		ans += dfs(A, i+1, mask, dp)
		ans %= 1e9+7
		mask = mask & ^(1<<uint(j))
	}

	dp[i][mask] = ans
	return ans
}

