	 foreach(i; 0 .. n) if(m & (1<<i)) k += 1;

	 long x = 0;
	 foreach(i; 0 .. n){
		 debug writeln("m:", m, " k:", k, " i:", i, " xs:", xs);
		 if(m & (1<<i)) if(as[i][k - 1] > 0){
			 x += xs[m ^ (1<<i)];
			 x %= mod;
		 }
	 }
	 xs ~= x;
 }

 xs[(1<<n) - 1].writeln;

}

