def solve_match(match_matrix):
    size = len(match_matrix)

    combo_list = [0] * (2**size)

    combo_indexes = [[] for _ in range(size + 1)]
    for i in range(2**size):
        count = 0
        n = i
        while (n): 
            count += n & 1
            n >>= 1
        combo_indexes[count].append(i)

    for col in range(size):
        for combo in combo_indexes[col + 1]:
            if col == 0:
                for i in range(size):
                    if (combo & (1 << i)):
                        combo_list[combo] = match_matrix[i][col]
                        break
            else:
                s = 0
                cnt = 0
                for i in range(size):
                    flag = 1 << i
                    if (combo & flag) and match_matrix[i][col] == 1:
                        s += combo_list[combo & (~flag)]
                        cnt += 1
                        if cnt == col + 1:
                            break

                combo_list[combo] = s % (10**9 + 7)
    return combo_list[-1]


