def solve_match(match_matrix):
    size = len(match_matrix)
    combo_dict = {}

    r = tuple(range(size))

    for col in range(size):
        for combo in itertools.combinations(r, col + 1):
            if col == 0:
                combo_dict[combo] = match_matrix[combo[0]][col]
            else:
                s = 0
                for i, row_num in enumerate(combo):
                    if match_matrix[row_num][col] == 1:
                        s += combo_dict[combo[:i] + combo[i + 1:]]
                combo_dict[combo] = s
    return combo_dict[r]


