const P: i64 = 1_000_000_007;

fn main() {
    let N = read!(usize);
    let A = read![[i32]; N];

    // dp[m][s] = (男性 0..m と集合 s に含まれる女性を使ってできるペアの個数)
    // dp[m][s] = sum[f in 0..N] dp[m-1][s \ f]

    let mut dp = Vec::with_capacity(1 << N);
    unsafe { dp.set_len(1 << N) };
    dp[0] = 1;

    for m in 0..N {
        for s in 0..(1 << N) {
            let mut pop_count = 0;
            for i in 0..N {
                if s & (1 << i) != 0 {
                    pop_count += 1;
                }
            }
            if pop_count != m {
                continue;
            }

            for f in 0..N {
                if (s & (1 << f)) != 0 {
                    continue;
                }
                if A[m][f] == 0 {
                    continue;
                }

                dp[s | (1 << f)] += dp[s];
                dp[s | (1 << f)] %= P;
            }
        }
    }

    println!("{}", dp[(1 << N) - 1])
}

