#[derive(Copy, Clone)]
pub struct ModUsize {
    pub mod_value: usize,
    pub value: usize,
}

impl ModUsize {
    pub fn new(n: usize) -> Self {
        Self {
            mod_value: Self::mod1(),
            value: n % Self::mod1(),
        }
    }

    pub fn pow(self, n: usize) -> Self {
        if n == 0 {
            Self::new(1)
        } else if n % 2 == 0 {
            let t = self.pow(n / 2);
            t * t
        } else {
            self * self.pow(n - 1)
        }
    }

    pub fn inv(self) -> Self {
        self.pow(self.mod_value - 2)
    }

    pub fn mod1() -> usize {
        1000000007
    }

    pub fn mod2() -> usize {
        998244353
    }
}

impl Add for ModUsize {
    type Output = ModUsize;

    fn add(self, rhs: Self) -> Self::Output {
        let mut tmp = self;
        tmp.value += rhs.value;
        if tmp.value >= self.mod_value {
            tmp.value -= self.mod_value;
        }
        tmp
    }
}

impl AddAssign for ModUsize {
    fn add_assign(&mut self, rhs: Self) {
        *self = *self + rhs;
    }
}

impl Sub for ModUsize {
    type Output = ModUsize;

    fn sub(self, rhs: Self) -> Self::Output {
        let mut tmp = self;
        if tmp.value < rhs.value {
            tmp.value += self.mod_value;
        }
        tmp.value -= rhs.value;
        tmp
    }
}

impl SubAssign for ModUsize {
    fn sub_assign(&mut self, rhs: Self) {
        *self = *self - rhs;
    }
}

impl Mul for ModUsize {
    type Output = ModUsize;

    fn mul(self, rhs: Self) -> Self::Output {
        let mut tmp = self;
        tmp.value *= rhs.value;
        tmp.value %= self.mod_value;
        tmp
    }
}

impl MulAssign for ModUsize {
    fn mul_assign(&mut self, rhs: Self) {
        *self = *self * rhs;
    }
}

impl Div for ModUsize {
    type Output = ModUsize;

    fn div(self, rhs: Self) -> Self::Output {
        let mut tmp = self;
        tmp.value /= rhs.value;
        tmp.value %= self.mod_value;
        tmp
    }
}

impl DivAssign for ModUsize {
    fn div_assign(&mut self, rhs: Self) {
        *self = *self / rhs;
    }
}

impl Display for ModUsize {
    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.value)
    }
}

