#[macro_export]
macro_rules! define_mod {
	($name:ident; $e:expr) => {
		#[derive(Clone, Copy, Default, Hash, PartialEq, PartialOrd, Eq, Ord)]
		pub struct _Mod;
		pub type $name = $crate::ModP<_Mod>;
		impl $crate::Mod for _Mod {
			fn m() -> u32 { $e }
		}
	}
}

impl<M: Mod, I: Int> From<I> for ModP<M> {
	/// Assume 0 <= a < m.
	fn from(a: I) -> ModP<M> { ModP::new(a) }
}

fn run() {
	define_mod!(P; 1_000_000_007);
	let N = read!(usize);
	let a = read!([i32]; N);
	let mut dp = vec![P::new(0); 1 << N];
	dp[0] = P::new(1);
	for i in 0..N {
		for j in (0..1 << N).rev() {
			if dp[j].0 == 0 {
				continue;
			}
			for k in 0..N {
				if j >> k & 1 == 0 && a[i][k] == 1 {
					dp[j | 1 << k] += dp[j];
				}
			}
		}
	}
	println!("{}", dp[(1 << N) - 1]);
}

