pub const M: u64 = 1_000_000_007;

fn main() {
    input! {
        n: usize,
        a: [[u32;n];n]
    }

    let mut dp = vec_md![0u64;n+1;1 << n];
    dp[0][0] = 1;
    for i in 0..n {
        let mut bit = (1 << i) - 1;
        while bit < 1 << n {

            for j in 0..n {
                if bit >> j & 1 == 0 && a[i][j] == 1 {
                    dp[i+1][bit | (1 << j)] += dp[i][bit];
                    dp[i+1][bit | (1 << j)] %= M;
                }
            }
            if bit == 0 {break;}
            let x = (bit as i64 & -(bit as i64)) as usize;
            let y = bit + x;
            bit = ((bit & !y) / x >> 1) | y;
        }
    }
    println!("{}", dp[n][(1<<n)-1]);
}

