fn solve(mat: &[Vec<u8>], matched: usize, memo: &mut [Vec<Option<ModP>>]) -> ModP {
    memo[mat.len()][matched].unwrap_or_else(|| {
        let res = match mat.split_first() {
            None => modp(1),
            Some((hd, tl)) => hd.iter().enumerate()
                .filter(|&(i, &a)| a == 1 && matched & (1 << i) == 0)
                .map(|(i, _)| solve(tl, matched | (1 << i), memo))
                .sum()
        };
        memo[mat.len()][matched] = Some(res);
        res
    })
}

