const P: i64 = 1_000_000_007;

fn main() {
    let N = read!(usize);
    let A = read![[i32]; N];

    // dp[m][s] = (男性 0..m と集合 s に含まれる女性を使ってできるペアの個数)
    // dp[m][s] = sum[f in 0..N] dp[m-1][s \ f]

    let mut dp = Vec::with_capacity(1 << N);
    dp.resize(1 << N, 0);
    dp[0] = 1;

    for m in 0..N {
        for s in 0..(1 << N) {
            let mut pop_count = 0;
            for i in 0..N {
                if s & (1 << i) != 0 {
                    pop_count += 1;
                }
            }
            if pop_count != m {
                continue;
            }

            for f in 0..N {
                if (s & (1 << f)) != 0 {
                    continue;
                }
                if A[m][f] == 0 {
                    continue;
                }

                dp[s | (1 << f)] += dp[s];
                dp[s | (1 << f)] %= P;
            }
        }
    }

    println!("{}", dp[(1 << N) - 1])
}

fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    read::<String>()
        .split_whitespace()
        .map(|e| e.parse().ok().unwrap())
        .collect()
}

#[derive(Clone, Debug)]
pub struct BitSet {
    buf: Vec<bool>,
    size: usize,
}

impl BitSet {
    pub fn new(size: usize, value: u32) -> BitSet {
        let mut buf = vec![false; size];
        let mut value = value;
        for i in 0..size {
            if value % 2 == 1 {
                buf[i] = true;
            }
            value = value >> 1;
        }
        BitSet {
            buf: buf,
            size: size,
        }
    }

    pub fn as_integer(&self) -> u32 {
        let mut value = 0;
        for i in (0..self.size).rev() {
            value = value << 1;
            if self.buf[i] {
                value += 1;
            }
        }
        value
    }
}

impl std::ops::Index<usize> for BitSet {
    type Output = bool;
    fn index(&self, index: usize) -> &bool {
        &self.buf[index]
    }
}

fn main() {
    let n = read::<usize>();
    let a = (0..n).map(|_| read_vec::<usize>()).collect::<Vec<Vec<_>>>();
    let big_int = 1000_000_000 + 7;
    let mut dp = std::collections::HashMap::new();

    for i in 0..n {
        if a[0][i] == 1 {
            dp.insert(1 << i, 1);
        }
    }
    for i in 1..n {
        let mut new_dp = std::collections::HashMap::new();
        for j in 0..n {
            if a[i][j] == 0 {
                continue;
            }
            for s_idx in dp.keys() {
                BitSet::new(n, *s_idx as u32)[j];
                *new_dp.entry(*s_idx + (1 << j)).or_insert(0) += dp[s_idx];
                *new_dp.entry(*s_idx + (1 << j)).or_insert(0) %= big_int;
            }
        }
        dp = new_dp;
    }
    println!("{:?}", dp[&((1 << n) - 1)]);
}

