fn main() {
    input!{
        n: usize,
        a: [[i64; n]; n]
    }
    let m = 1000000007;
    let mut tab: Vec<i64> = vec![0; 1 << n];
    tab[0] = 1;
    for i in 1..n + 1 {
        let mut s = (1 << i) as i64 - 1;
        while s < 1 << n {
            for j in 0..n {
                if s & (1 << j) > 0 && a[i - 1][j] == 1 {
                    tab[s as usize] += tab[s as usize - (1 << j)]
                }
            }
            tab[s as usize] %= m;

            let t = s & (-s);
            let u = s + t;
            s = (s & !u) / (t << 1) | u;
        }
    }
    println!("{}", tab[(1 << n) - 1]);
}

