impl std::ops::Div for ModInt {
    type Output = Self;
    fn div(self, other: Self) -> Self {
        let mut exp = Self::modulo() - 2;
        let mut value = self.value;
        let mut ovalue = other.value;
        while exp > 0 {
            if exp % 2 == 1 {
                value = value * ovalue % Self::modulo();
            }
            ovalue = ovalue * ovalue % Self::modulo();
            exp /= 2;
        }
        ModInt { value: value }
    }
}
