    let a = (0..n).map(|_| read_vec::<usize>()).collect::<Vec<Vec<_>>>();
    let big_int = 1000_000_000 + 7;
    let mut dp = vec![vec![0u64; 1 << n]; n];

    for i in 0..n {
        if a[0][i] == 1 {
            dp[0][1 << i] = 1;
        }
    }
    for i in 1..n {
