                        continue 'comb;//
                    }
                    s_idx += 1 << elem;
                }
                dp[i][s_idx + (1 << j)] += dp[i - 1][s_idx];
                dp[i][s_idx + (1 << j)] %= big_int;
                dp[i][s_idx] %= big_int;
            }
        }
    }
