const MOD: i64 = 1000000007;

fn rec(state: usize, c: usize, a: &Vec<Vec<bool>>, dp: &mut Vec<i64>) -> i64 {
   if dp[state] != -1 {
      dp[state]
   } else {
      let mut r = 0;
      for (i, &b) in a[c].iter().enumerate() {
         if (state >> i) & 1 == 1 && b {
            r += rec(state ^ (1 << i), c + 1, a, dp);
         }
      }
      dp[state] = r % MOD;
      dp[state]
   }
}

