#[fastout]
pub fn main() {
    input! {
        n: usize,
        a: [[i32; n]; n],
    }
    let a: Vec<Vec<_>> = a
        .into_iter()
        .map(|a| a.into_iter().map(|a| a == 1).collect())
        .collect();

    let mut dp = vec![0; 1 << n];
    dp[0] = 1;
    for i in 1usize..1 << n {
        let num = i.count_ones() as usize;
        for j in 0..n {
            if ((i >> j) & 1) == 1 && a[num - 1][j] {
                dp[i] += dp[i ^ (1 << j)];
                dp[i] %= MOD;
            }
        }
    }
    println!("{}", dp[(1 << n) - 1]);
}

