const MOD: i64 = 1000000007;

fn rec(state: usize, c: usize, a: &Vec<Vec<bool>>, dp: &mut Vec<i64>) -> i64 {
   if dp[state] != -1 {
      dp[state]
   } else {
      dp[state] = a[c].iter().enumerate().fold(0, |s, (i, &b)| {
         if (state >> i) & 1 == 1 && b {
            s + rec(state ^ (1 << i), c + 1, a, dp)
         } else {
            s
         }
      }) % MOD;
      dp[state]
   }
}

