    let mut dp = vec![0u64; 1 << n];

    let mut bits = vec![vec![]; n + 1];
    for bp in 0..(1 << n) {
        let k = (bp as u32).count_ones();
        bits[k as usize].push(bp);
    }
    // println!("bits {:?}", bits);
    for i in 0..n {
        if a[0][i] == 1 {
            dp[1 << i] = 1;
        }
    }
    for i in 1..n {
        for j in 0..n {
            if a[i][j] == 0 {
                continue;
            }
            for &k in bits[i].iter() {
                if k & 1 << j != 0 {
                    continue;
                }
                // println!("{:?}", (k, 1 << j, k ^ (1 << j), 1 << n));
                dp[k ^ (1 << j)] += dp[k];
                dp[k ^ (1 << j)] %= big_int;
            }
        }
    }
    println!("{:?}", dp[(1 << n) - 1]);
}

