const M: u64 = 1000_000_007;

fn main() {
    input! { n: usize }

    let mut a = vec![0; n];
    for i in 0..n {
        for j in 0..n {
            input! { aij: usize };
            a[i] |= aij << j;
        }
    }

    println!("{}", DP::new(n, a).calc(0));
}

struct DP {
    dp: Vec<Vec<Option<u64>>>,
    n: usize,
    a: Vec<usize>,
}

impl DP {
    fn new(n: usize, a: Vec<usize>) -> DP {
        DP {
            dp: vec![vec![None; 1 << n]; n + 1],
            n: n,
            a: a,
        }
    }

    fn calc(&mut self, p: usize) -> u64 {
        let i = p.count_ones() as usize;
        if let Some(v) = self.dp[i][p] {
            v
        } else {
            let v = if i == self.n {
                1
            } else {
                let rest = self.a[i] & !p;
                let mut v = 0;
                for j in 0..self.n {
                    let b = 1 << j;
                    if rest & b == b {
                        v = (v + self.calc(p | b)) % M;
                    }
                }
                v
            };
            self.dp[i][p] = Some(v);
            v
        }
    }
}

