#[derive(Copy, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct ModInt {
    value: usize,
}
impl ModInt {
    fn new(value: usize) -> Self {
        ModInt {
            value: value % Self::modulo(),
        }
    }
    fn value(&self) -> usize {
        self.value
    }
    fn modulo() -> usize {
        1_000_000_007
    }
}
impl From<usize> for ModInt {
    fn from(value: usize) -> Self {
        ModInt { value: value }
    }
}
impl std::ops::Add for ModInt {
    type Output = Self;
    fn add(self, other: Self) -> Self {
        let mut value = self.value + other.value;
        if value > Self::modulo() {
            value -= Self::modulo();
        }
        ModInt { value: value }
    }
}
impl std::ops::Sub for ModInt {
    type Output = Self;
    fn sub(self, other: Self) -> Self {
        let mut value = self.value;
        if value < other.value {
            value += Self::modulo();
        }
        value -= other.value;
        ModInt { value: value }
    }
}
impl std::ops::Mul for ModInt {
    type Output = Self;
    fn mul(self, other: Self) -> Self {
        let value = self.value * other.value % Self::modulo();
        ModInt { value: value }
    }
}
impl std::ops::Div for ModInt {
    type Output = Self;
    fn div(self, other: Self) -> Self {
        let mut exp = Self::modulo() - 2;
        let mut value = self.value;
        let mut ovalue = other.value;
        while exp > 0 {
            if exp % 2 == 1 {
                value = value * ovalue % Self::modulo();
            }
            ovalue = ovalue * ovalue % Self::modulo();
            exp /= 2;
        }
        ModInt { value: value }
    }
}
impl std::ops::AddAssign for ModInt {
    fn add_assign(&mut self, other: Self) {
        *self = *self + other;
    }
}
impl std::ops::SubAssign for ModInt {
    fn sub_assign(&mut self, other: Self) {
        *self = *self - other;
    }
}
impl std::ops::MulAssign for ModInt {
    fn mul_assign(&mut self, other: Self) {
        *self = *self * other;
    }
}
impl std::ops::DivAssign for ModInt {
    fn div_assign(&mut self, other: Self) {
        *self = *self / other;
    }
}
impl std::fmt::Debug for ModInt {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        write!(f, "{}", self.value)
    }
}
impl std::fmt::Display for ModInt {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        write!(f, "{}", self.value)
    }
}

fn solve() {
    let n = get!(usize);
    let a = get!([usize]; n);

    let mut dp = vec![vec![ModInt::new(0); 1<<n];n+1];
    dp[0][0] = ModInt::new(1);
    for i in 0..n {
        for mask in 0usize..1<<n {
            if mask.count_ones() as usize != i {
                continue;
            }
            for j in 0..n {
                let new_mask = mask | (1<<j);
                if mask == new_mask {
                    continue;
                }
                if a[i][j] == 1 {
                    let tmp = dp[i][mask];
                    dp[i+1][new_mask] += tmp;
                }
            }
        }
    }
    println!("{}", dp[n][(1<<n)-1]);
}

