pub fn count_ones(i: usize) -> usize {
    let i = i - ((i >> 1) & 0x5555555555555555);
    let i = (i & 0x3333333333333333) + ((i >> 2) & 0x3333333333333333);
    let r = (((i + (i >> 4)) & 0xF0F0F0F0F0F0F0F) * 0x101010101010101) >> 56;
    r as usize
}

fn main() {
    input! {
