    dp[0][0] = 1;

    for i in 0..n {
        for j in 0..(1 << n) {
            if count_ones(j) != i {
                continue;
            }
            for k in 0..n {
                if j & (1 << k) == 0 && a[i][k] == 1 {
                    dp[i + 1][j | (1 << k)] += dp[i][j];
                    dp[i + 1][j | (1 << k)] %= 1_000_000_007;
                }
            }
        }
    }
    println!("{}", dp[n][(1 << n) - 1]);
}

