fn main() {
    input! {
        n: usize,
        a: [[i64; n]; n],
    }

    let mut tbl = vec![vec![None; 1 << n]; n + 1];
    let ans = rec(0, 0, &a, &mut tbl);
    println!("{}", ans);
}

fn rec(pos: usize, opp: usize, a: &Vec<Vec<i64>>, tbl: &mut Vec<Vec<Option<Mod>>>) -> Mod {
    if pos == a.len() {
        return 1.into();
    }

    if tbl[pos][opp].is_some() {
        return tbl[pos][opp].unwrap();
    }

    let mut ret = 0.into();

    for i in 0..a.len() {
        if opp & 1 << i != 0 {
            continue;
        }

        if a[pos][i] == 0 {
            continue;
        }

        ret += rec(pos + 1, opp | 1 << i, a, tbl);
    }

    tbl[pos][opp] = Some(ret);
    ret
}

