    let mut dp = vec![vec![0u64; 1 << n]; n];

    for i in 0..n {
        if a[0][i] == 1 {
            dp[0][1 << i] = 1;
        }
    }
    for i in 1..n {
        let j = 0;
        for j in 0..n {
            if a[i][j] == 0 {
                continue;
            }
            for s in 0..1 << n {
                if dp[i - 1][s] == 0 || BitSet::new(n, s as u32)[j] {
                    continue;
                }
                dp[i][s + (1 << j)] += dp[i - 1][s];
                dp[i][s + (1 << j)] %= big_int;
                dp[i][s] %= big_int;
            }
        }
    }
