    }
    let mut matched: i32 = (1 << n) - 1;
    let mut dp: HashMap<i32, i64> = HashMap::new();
    let result = find_match(0, &affinities, matched, &mut dp);
    println!("{}", result);
    Ok(())
}

fn find_match(
    row: usize,
    affinities: &Vec<Vec<i32>>,
    current_matched: i32,
    dp: &mut HashMap<i32, i64>,
) -> i64 {
    if row == affinities.len() {
        return 1;
    }
    if let Some(&value) = dp.get(&current_matched) {
        return value;
    }
    let mut result = 0i64;
    for i in 0..affinities[row].len() {
        if affinities[row][i] == 1 && current_matched & (1 << i) as i32 != 0 {
            result += find_match(row + 1, affinities, current_matched ^ (1 << i) as i32, dp);
            result %= MOD;
        }
    }
    dp.insert(current_matched, result);
    result
}

