const P: i64 = 1_000_000_007;

fn main() {
    let N = read!(usize);
    let A = read![[i32]; N];

    // dp[m][s] = (男性 0..m と集合 s に含まれる女性を使ってできるペアの個数)
    // dp[m][s] = sum[f in 0..N] dp[m-1][s \ f]

    let mut dp = vec![vec![0; 1 << N]; N + 1];

    dp[0][0] = 1;
    for m in 0..N {
        for s in 0..(1 << N) {
            let pop_count = (0..N).filter(|&i| (s & (1 << i)) != 0).count();
            if pop_count != m {
                continue;
            }

            for f in 0..N {
                if (s & (1 << f)) != 0 {
                    continue;
                }
                if A[m][f] == 0 {
                    continue;
                }

                dp[m + 1][s | (1 << f)] += dp[m][s];
                dp[m + 1][s | (1 << f)] %= P;
            }
        }
    }

    println!("{}", dp[N][(1 << N) - 1])
}

#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, bytes) => {
        read_value!($next, String).into_bytes()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

fn main() {
    input! {
        n: usize,
        a: [[usize; n]; n],
    }
    let mut dp = vec![vec![0; 1 << n]; n + 1];
    dp[0][0] = 1;

    for i in 0..n {
        for j in 0..(1 << n) {
            for k in 0..n {
                if j & (1 << k) == 0 && a[i][k] == 1 {
                    dp[i + 1][j | (1 << k)] += dp[i][j];
                    dp[i + 1][j | (1 << k)] %= 1_000_000_007;
                }
            }
        }
    }
    println!("{}", dp[n][(1 << n) - 1]);
}
